  function ssLoadCustomApiPresets() {
    try {
      const raw = localStorage.getItem(SS_CUSTOM_API_PRESETS_KEY);
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr.filter(x => x && (x.apiurl || x.key || x.model)) : [];
    } catch {
      return [];
    }
  }

  function ssSaveCustomApiPresets(list) {
    try {
      localStorage.setItem(SS_CUSTOM_API_PRESETS_KEY, JSON.stringify(Array.isArray(list) ? list : []));
    } catch { }
  }

  function ssGetCustomApiPresetOptionsHtml() {
    const list = ssLoadCustomApiPresets();
    if (!list.length) return '<option value="">暂无保存项</option>';
