  }

  function ssReadCustomApiValues(prefix) {
    const $ = id => topDoc.getElementById(`${prefix}-${id}`);
    return {
      apiurl: $('api-url')?.value?.trim() || '',
      key: $('api-key')?.value?.trim() || '',
      model: $('api-model')?.value?.trim() || $('model')?.value?.trim() || '',
    };
  }

  function ssApplyCustomApiValues(prefix, item) {
    if (!item) return;
    const set = (id, v) => {
      const el = topDoc.getElementById(`${prefix}-${id}`);
      if (el) el.value = v || '';
    };
    set('api-url', item.apiurl);
    set('api-key', item.key);
    set('api-model', item.model);
