  function buildPromptBackup() {
    const result = {};
    const refs = getAllUserEditablePromptRefsForBackup();

    try {
      const preset = getPreset('in_use');
      const prompts = preset?.prompts || [];

      for (const ref of refs) {
        const p = prompts.find(x => x?.id === ref || x?.identifier === ref);
        if (!p) continue;

        const key = p.id || p.identifier || ref;

        result[key] = {
          id: p.id || '',
          identifier: p.identifier || '',
          name: p.name || '',
          enabled: !!p.enabled,
          content: p.content || '',
        };
      }
    } catch (e) {
      log('构建 prompt 备份失败', e);
    }

    return result;
  }

  function buildAllLocalStorageBackup() {
    const data = {
      version: 'xuanhu_backup_v3',
      exportedAt: new Date().toISOString(),
      localStorage: {},
      promptBackup: buildPromptBackup(),
      keyCount: 0,
    };

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (!key) continue;

      if (
        key.startsWith('SPreset_') ||
        key.startsWith('smoothStream_') ||
        key.startsWith('Xuanhu_ParallelWorld_') ||
        key === CONFIG.HUSOU_STORAGE_KEY ||
        key === CONFIG.HUSHEN_STORAGE_KEY ||
        key === 'websearch_settings' ||
        key === 'hushen_profile_settings'
      ) {
        data.localStorage[key] = localStorage.getItem(key);
      }
    }

    data.keyCount = Object.keys(data.localStorage).length;

    return data;
  }


  function downloadJsonFile(obj, filename) {
    const blob = new Blob([JSON.stringify(obj, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = topDoc.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  }

