  async function importAllLocalConfig() {
    const inp = topDoc.createElement('input');
    inp.type = 'file';
    inp.accept = 'application/json';

    inp.onchange = async (e) => {
      const file = e.target.files?.[0];
      if (!file) return;

      try {
        const text = await file.text();
        const data = JSON.parse(text);

        if (!data?.localStorage || typeof data.localStorage !== 'object') {
          throw new Error('备份文件格式错误');
        }

        const ok = topWindow?.confirm
          ? topWindow.confirm('确定要导入并覆盖本地玄狐配置吗？\n\n导入前会先清除当前所有玄狐相关的 localStorage 数据，再写入备份数据，确保完全还原。导入后会自动刷新脚本状态。')
          : confirm('确定要导入并覆盖本地玄狐配置吗？\n\n导入前会先清除当前所有玄狐相关的 localStorage 数据，再写入备份数据，确保完全还原。导入后会自动刷新脚本状态。');

        if (!ok) return;

        const xuanhuKeyPrefixes = [
          'SPreset_',
          'smoothStream_',
          'Xuanhu_ParallelWorld_',
        ];
        const xuanhuExactKeys = new Set([
          CONFIG.HUSOU_STORAGE_KEY,
          CONFIG.HUSHEN_STORAGE_KEY,
          'websearch_settings',
          'hushen_profile_settings',
        ]);

        const keysToRemove = [];
        for (let i = 0; i < localStorage.length; i++) {
          const key = localStorage.key(i);
          if (!key) continue;
          if (xuanhuKeyPrefixes.some(p => key.startsWith(p)) || xuanhuExactKeys.has(key)) {
            keysToRemove.push(key);
          }
        }
        for (const key of keysToRemove) {
          localStorage.removeItem(key);
        }
        log(`[配置恢复] 已清除 ${keysToRemove.length} 个旧 localStorage key`);

        for (const [key, value] of Object.entries(data.localStorage)) {
          if (value == null) localStorage.removeItem(key);
          else localStorage.setItem(key, String(value));
        }
        log(`[配置恢复] 已写入 ${Object.keys(data.localStorage).length} 个 localStorage key`);

        if (data.promptBackup && typeof data.promptBackup === 'object') {
          await updatePresetWith('in_use', (preset) => {
            for (const backup of Object.values(data.promptBackup)) {
              const refList = [backup.id, backup.identifier].filter(Boolean);

              const p = preset.prompts.find(x =>
                refList.includes(x.id) ||
                refList.includes(x.identifier)
              );

              if (!p) continue;

              if (typeof backup.content === 'string') p.content = backup.content;
              if (typeof backup.enabled === 'boolean') p.enabled = backup.enabled;
            }

            return preset;
          });
        }

        state.husouSettings = loadHusouSettings();
        state.hushenSettings = loadHushenSettings();
        foxMemoryConfig = loadFoxMemoryConfig();
        novelModeConfig = loadNovelModeConfig();
        try { pwState.config = pwLoadConfig(); } catch {}
        try { state.outlineText = outlineLoadCurrentText(); } catch {}

        toast(`✅ 已导入全部本地配置（${Object.keys(data.localStorage).length} 项 localStorage + 预设条目），重新打开面板即可读取`, 'success');
      } catch (err) {
        toast(`❌ 导入失败：${err.message || err}`, 'error');
      }
    };

    inp.click();
  }

