  // ✅ 全局兜底：用事件代理在 toast-container 上监听 .ss-toast-cancel 点击。
  //    即使 toast DOM 在某些时机没正确取到（比如 newestOnTop / 并发任务弹窗），
  //    也能保证"中断按钮"始终可点。绑定一次即可。
  (function ssBindToastCancelDelegation() {
    const bind = (doc) => {
      if (!doc || doc.__ssToastCancelBound) return;
      doc.__ssToastCancelBound = true;
      doc.addEventListener('click', (ev) => {
        const target = ev.target;
        if (!target || !target.closest) return;
        const btn = target.closest('.ss-toast-cancel');
        if (!btn) return;
        ev.preventDefault();
        ev.stopPropagation();
        // 优先取按钮上的 data-task；取不到时回退到所在 toast 的 dataset.ssTask
        let taskName = btn.getAttribute('data-task') || '';
        const toastEl = btn.closest('.toast');
        if (!taskName) {
          taskName = toastEl?.dataset?.ssTask || '';
        }
        if (!taskName) return;
        // 与按钮直绑路径去重：任一路径先触发即标记，避免重复中断
        if (toastEl && toastEl.__ssCancelHandled) return;
        if (toastEl) toastEl.__ssCancelHandled = true;
        try { ssCancelTask(taskName); } catch { }
        try { ssClearTaskToast(taskName); } catch { }
