  // ==================== 🦊 面板自动保存代理 ====================
  // 用法：ssAttachAutoSave(panelEl, { saveBtnIds: ['foo-save'], excludeSelectors: ['.search-input'] })
  //       或者 ssAttachAutoSave(panelEl, { resolveSaveBtns: (target) => ['some-id'] })
  // 工作方式：监听面板内所有 input/select/textarea/checkbox 的 input 与 change 事件，
  //          发生变化时 debounce 600ms 后静默触发对应保存按钮的 click（保留原 save 逻辑），
  //          同时显示一个轻量"自动保存中…"指示器；按钮自身的点击事件不受影响。
  // 不会监听：button、type=button、type=submit、reset、file，以及 excludeSelectors 命中的元素，
  //          以及面板上 data-no-autosave 标记的元素。
  function ssAttachAutoSave(panelEl, opts = {}) {
    if (!panelEl || panelEl.__ssAutoSaveAttached) return;
    panelEl.__ssAutoSaveAttached = true;

    const saveBtnIds = Array.isArray(opts.saveBtnIds) ? opts.saveBtnIds.filter(Boolean) : [];
    const resolveSaveBtns = typeof opts.resolveSaveBtns === 'function' ? opts.resolveSaveBtns : null;
    const excludeSelectors = Array.isArray(opts.excludeSelectors) ? opts.excludeSelectors : [];
    const debounceMs = typeof opts.debounceMs === 'number' ? opts.debounceMs : 600;

    // 在面板顶部插入一个轻量指示条
    let indicator = panelEl.querySelector('.ss-autosave-indicator');
    if (!indicator) {
      indicator = topDoc.createElement('div');
      indicator.className = 'ss-autosave-indicator';
      indicator.style.cssText = 'font-size:11px;color:#7a8f7a;margin:-2px 0 6px 0;padding:3px 8px;border-radius:6px;background:rgba(120,180,120,0.06);border:1px solid rgba(120,180,120,0.15);display:inline-block;align-self:flex-start;transition:opacity 0.25s;opacity:0.85;';
      indicator.textContent = '✨ 已开启自动保存：你的修改会立即生效，无需手动点保存';
      // 插入到面板第一个子元素之后（通常是标题栏）
      const firstChild = panelEl.firstElementChild;
      if (firstChild && firstChild.nextSibling) {
        panelEl.insertBefore(indicator, firstChild.nextSibling);
      } else {
        panelEl.insertBefore(indicator, panelEl.firstChild);
      }
    }

    // 为不同的 changed target 分别累计待触发的 save 按钮 ID
    const pendingIds = new Set();
    let savingTimer = null;

    const flashSaving = () => {
      indicator.textContent = '💾 自动保存中…';
      indicator.style.color = '#f0a070';
      indicator.style.background = 'rgba(232,120,74,0.06)';
      indicator.style.borderColor = 'rgba(232,120,74,0.18)';
      clearTimeout(indicator.__resetTimer);
      indicator.__resetTimer = setTimeout(() => {
        indicator.textContent = '✅ 已自动保存';
        indicator.style.color = '#7ab97a';
        indicator.style.background = 'rgba(120,180,120,0.08)';
        indicator.style.borderColor = 'rgba(120,180,120,0.2)';
        // 2.5 秒后回到默认提示
        clearTimeout(indicator.__idleTimer);
        indicator.__idleTimer = setTimeout(() => {
          indicator.textContent = '✨ 已开启自动保存：你的修改会立即生效，无需手动点保存';
          indicator.style.color = '#7a8f7a';
          indicator.style.background = 'rgba(120,180,120,0.06)';
          indicator.style.borderColor = 'rgba(120,180,120,0.15)';
        }, 2500);
      }, 250);
    };

    const triggerSave = () => {
      const ids = Array.from(pendingIds);
      pendingIds.clear();
      if (!ids.length) return;
      __ssBeginAutoSaveSilent();
      try {
        for (const id of ids) {
          const btn = panelEl.querySelector('#' + id) || topDoc.getElementById(id);
          if (btn && typeof btn.click === 'function' && !btn.disabled) {
            try { btn.click(); } catch (e) { try { log('[autosave] 触发', id, '失败', e); } catch {} }
          }
        }
      } finally {
        // settle 1500ms 覆盖 async save handler 在 await 之后才 toast 的场景
        __ssEndAutoSaveSilent(1500);
      }
      flashSaving();
    };

    const queueIdsFor = (target) => {
      // 优先用 resolveSaveBtns（更精细）；否则用通用 saveBtnIds
      let ids = null;
      if (resolveSaveBtns) {
        try { ids = resolveSaveBtns(target); } catch (e) { try { log('[autosave] resolveSaveBtns 抛错', e); } catch {} }
      }
      if (!ids || !ids.length) ids = saveBtnIds;
      if (!ids || !ids.length) return false;
      let added = false;
      for (const id of ids) {
        if (id) { pendingIds.add(id); added = true; }
      }
      return added;
    };

    const isWatchable = (el) => {
      if (!el || !el.tagName) return false;
      const tag = el.tagName.toLowerCase();
      if (tag !== 'input' && tag !== 'select' && tag !== 'textarea') return false;
      // 跳过按钮型 input
      const t = (el.type || '').toLowerCase();
      if (t === 'button' || t === 'submit' || t === 'reset' || t === 'file' || t === 'image') return false;
      // 跳过只读
      if (el.readOnly === true || el.disabled === true) return false;
      // 跳过显式标记
      if (el.hasAttribute('data-no-autosave')) return false;
      // 跳过 excludeSelectors 命中
      for (const sel of excludeSelectors) {
        try { if (sel && el.matches(sel)) return false; } catch {}
        try { if (sel && el.closest(sel)) return false; } catch {}
      }
      return true;
    };

    const onEvt = (e) => {
      if (!isWatchable(e.target)) return;
      if (!queueIdsFor(e.target)) return;
      clearTimeout(savingTimer);
      savingTimer = setTimeout(triggerSave, debounceMs);
    };

    panelEl.addEventListener('input', onEvt, true);
    panelEl.addEventListener('change', onEvt, true);

    // 面板被 remove 时同步清理 timer 与监听器，避免后续触发不存在的按钮
    let cleanupInterval = null;
    const cleanup = () => {
      clearTimeout(savingTimer);
      clearTimeout(indicator?.__resetTimer);
      clearTimeout(indicator?.__idleTimer);
      panelEl.removeEventListener('input', onEvt, true);
      panelEl.removeEventListener('change', onEvt, true);
      if (cleanupInterval) { clearInterval(cleanupInterval); cleanupInterval = null; }
    };
    panelEl.__ssAutoSaveCleanup = cleanup;

    // 不再用 MutationObserver 监听 body 全量子节点变动（成本随会话累积）：
    // 改为低频 poll 检查 panel 是否仍在 DOM 中，触发后即清理并停 poll。
    // 面板关闭通常由用户操作（≤数秒延迟可接受），不影响功能。
    cleanupInterval = setInterval(() => {
      if (!panelEl.isConnected) cleanup();
    }, 3000);
  }

  // ==================== 🦊 面板恢复默认按钮 ====================
  // 用法：ssAttachPanelResetButton(panelEl, { label: '↩ 恢复狐裁默认', confirm: '...', onReset: () => { ... } })
  // 在面板顶部（标题栏附近）插入一个红色"恢复本面板默认"按钮，
  // 点击时弹确认 → 调用 onReset() → 关闭重开当前面板（由 onReset 自行实现或返回 reopen 函数）。
  function ssAttachPanelResetButton(panelEl, opts = {}) {
    if (!panelEl || panelEl.__ssResetBtnAttached) return;
    panelEl.__ssResetBtnAttached = true;

    const label = opts.label || '↩ 恢复本面板默认';
    const confirmText = opts.confirm || '确定恢复本面板的全部设置为默认值吗？此操作不可撤销。';
    const onReset = typeof opts.onReset === 'function' ? opts.onReset : null;

    const btn = topDoc.createElement('button');
    btn.type = 'button';
    btn.className = 'ss-panel-reset-btn';
    btn.textContent = label;
    btn.setAttribute('data-no-autosave', '1');
    btn.style.cssText = 'align-self:flex-start;padding:5px 10px;border:1px solid rgba(139,0,0,0.35);border-radius:6px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:11px;font-family:inherit;margin:0 0 6px 0;';
    btn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      // 与文件其它处一致的调用方式：保留 this 绑定，避免 strict-mode 抛 Illegal invocation
      const ok = topWindow?.confirm ? topWindow.confirm(confirmText) : confirm(confirmText);
      if (!ok) return;
      try { onReset && onReset(); } catch (err) { try { log('[reset] 失败', err); } catch {} ; toast(`❌ 恢复默认失败：${err?.message || err}`, 'error'); return; }
      toast('✅ 已恢复本面板默认设置', 'success');
    };

    // 插入：尝试放在自动保存指示器之后（如果有），否则插入到第一个子元素后
    const indicator = panelEl.querySelector('.ss-autosave-indicator');
    if (indicator && indicator.nextSibling) {
      panelEl.insertBefore(btn, indicator.nextSibling);
    } else {
      const firstChild = panelEl.firstElementChild;
      if (firstChild && firstChild.nextSibling) {
        panelEl.insertBefore(btn, firstChild.nextSibling);
      } else {
        panelEl.insertBefore(btn, panelEl.firstChild);
      }
    }
  }

  // ==================== 🦊 全局生成类型追踪器：reroll / swipe 保护 ====================
  // 背景：
  //   SillyTavern 的 MESSAGE_RECEIVED 事件并不总是把 type 透传给监听器
  //   （只有 GENERATION_STARTED 一定会传 type='regenerate' / 'swipe' / 'continue' / 'quiet' / 'impersonate' / 'normal'）。
  //   而狐忆自动分析、平行世界自动推进、狐构自动修正都挂在 MESSAGE_RECEIVED 上，
  //   靠 (type && type !== 'normal') 来过滤"非用户主动新回复"的情况。
  //   一旦 MESSAGE_RECEIVED 没有 type 参数，这个过滤就会失效——用户重 roll / swipe
  //   出来的回复也会被当成"普通新回复"，再触发一遍狐忆 / 平行世界更新，
  //   这就是"重 roll、swipe 又更新一遍平行世界和狐忆"出问题的根因。
  //
  // 策略：
  //   在 GENERATION_STARTED 里抓住本次生成的 type，存进全局变量；
  //   MESSAGE_RECEIVED 处理函数在 type 缺失时，回退用这个全局值来判断。
  //   GENERATION_STARTED 总能拿到 type，所以即使 ST 没把 type 透传给 MESSAGE_RECEIVED，
  //   我们也能在事件链里把它接住。
  //
  // 注意：
  //   - dryRun 不算正式生成，不能污染 lastType（否则资料抓取等会被误标记成 normal/quiet）。
  //   - 脚本自己跑的 generateRaw（狐忆/平行世界/狐构/狐搜/大总结/文风分析等）会以 'quiet' 类型
  //     再触发 GENERATION_STARTED，**必须过滤掉**——否则会污染 lastType，下一次真正主线 normal
  //     回复的 MESSAGE_RECEIVED 在 ST 没透传 type 时回退到残留 'quiet'，合法回复也被跳过。
  //     我们靠 ssActiveTasks / state.*IsRunning|Generating|Analyzing / pwState.running|internalGenerating
  //     这些已有的"内部任务进行中"标志，在追踪器入口就把内部 GENERATION_STARTED 拦掉。
  //   - 同时，我们在 foxMemoryShouldAutoAnalyze / pwShouldAutoAdvance 内部已经在 MESSAGE_RECEIVED 触发的
  //     "那一刻"就读取 lastType 并冻结到 snapshotType（见下文），所以即使追踪器漏掉了某种内部任务，
  //     setTimeout 之后 lastType 再被覆盖也不会影响本次判定。这是双重保险。
  let xhLastGenerationType = null;
  let xhLastGenerationTypeHandle = null;

  function xhGetLastGenerationType() {
    return xhLastGenerationType;
  }

  function xhRegisterGenerationTypeTracker() {
    xhUnregisterGenerationTypeTracker();
    try {
      const eo = getFn('eventOn');
      const te = getFn('tavern_events') || tavern_events;
      if (typeof eo !== 'function' || !te?.GENERATION_STARTED) {
        log('[生成类型追踪] 注册失败：缺少 eventOn 或 GENERATION_STARTED');
        return;
      }
      xhLastGenerationTypeHandle = eo(te.GENERATION_STARTED, (type, _option, dryRun) => {
        if (dryRun) return;
        // 🦊 关键：脚本自身跑的 generateRaw（狐忆 / 平行世界 / 狐搜 / 狐构 / 大总结 /
        //    文风分析 / 狐析 / 狐裁 等）也会触发 GENERATION_STARTED 且 type 一般为 'quiet'。
        //    必须过滤掉，否则会把 xhLastGenerationType 污染成 'quiet'，下一次真正用户
        //    主线 normal 回复的 MESSAGE_RECEIVED 在 ST 没透传 type 时回退到这个残留值，
        //    合法的主线回复也会被错误跳过狐忆 / 平行世界更新。
        let isInternal = false;
        try {
          isInternal =
            (typeof ssActiveTasks !== 'undefined' && ssActiveTasks?.size > 0) ||
            !!state?.husouIsRunning ||
            !!state?.foxAnalyzing ||
            !!state?.outlineIsCorrecting ||
            !!state?.outlineIsGenerating ||
            !!state?.hushenIsAnalyzing ||
            !!pwState?.running ||
            !!pwState?.internalGenerating;
        } catch { }
        if (isInternal) {
          log('[生成类型追踪] 跳过内部任务的 GENERATION_STARTED type=', type);
          return;
        }
        xhLastGenerationType = type || 'normal';
        log('[生成类型追踪] 捕获 GENERATION_STARTED type=', xhLastGenerationType);
      });
      log('[生成类型追踪] 已注册 GENERATION_STARTED 监听');
    } catch (e) {
      log('[生成类型追踪] 注册异常', e);
    }
  }

  function xhUnregisterGenerationTypeTracker() {
    try { xhLastGenerationTypeHandle?.stop?.(); } catch { }
    xhLastGenerationTypeHandle = null;
  }

  // ==================== 🦊 自动任务全局队列：防止狐搜/狐忆/狐构/平行世界同时 generateRaw 冲突 ====================
  const xhAutoQueue = {
    chain: Promise.resolve(),
    pending: new Set(),
  };

  function xhIsAbortLike(e) {
    const msg = e?.message || String(e || '');
    return /abort|aborted|cancel|取消|中断/i.test(msg);
  }

  async function xhWaitForIdleBeforeAuto(timeoutMs = 180000) {
    const start = Date.now();

    while (ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || pwState?.running) {
      if (Date.now() - start > timeoutMs) {
        throw new Error('等待其他玄狐任务结束超时');
      }

      await new Promise(r => setTimeout(r, 350));
    }
  }

  function xhEnqueueAutoTask(taskKey, label, runner, opts = {}) {
    const key = String(taskKey || label || 'auto_task');
    const dedupe = opts.dedupe !== false;

    if (dedupe && xhAutoQueue.pending.has(key)) {
      log(`[自动任务队列] 已存在待执行任务，跳过重复入队：${label}`);
      return xhAutoQueue.chain;
    }

    xhAutoQueue.pending.add(key);

    xhAutoQueue.chain = xhAutoQueue.chain
      .catch(() => { })
      .then(async () => {
        await xhWaitForIdleBeforeAuto();

        log(`[自动任务队列] 开始：${label}`);

        try {
          await runner();
          log(`[自动任务队列] 完成：${label}`);
        } catch (e) {
          if (xhIsAbortLike(e)) {
