  function ssInsertBlockAfterFoxExtra(content, block) {
    let text = ssStripCurrentPromptInjectBlock(String(content || ''));

    if (!block?.trim()) return text;

    const injectBlock = `\n\n${block.trim()}\n`;

    const closeRe = /<\s*\/\s*fox_extra\s*>/i;
     if (closeRe.test(text)) {
       return text.replace(closeRe, m => `${injectBlock}${m}`);
     }

    const openRe = /<\s*fox_extra\b[^>]*>/i;
    if (openRe.test(text)) {
      return text.replace(openRe, m => `${m}${injectBlock}`);
    }

    return `${injectBlock}\n${text}`.trim();
  }

  // ✅ 把 block 注入到预设里预留的 <fox_extra></fox_extra> 之间（标签内部）
  // 用户的预设里已经写好了空的 <fox_extra></fox_extra>，这里直接查找并把内容塞进去。
  // 命中返回 { ok: true, content: 新文本 }；找不到返回 { ok: false, content: 原文本 }
  function ssInsertBlockInsideFoxExtra(content, block) {
    const text = String(content || '');
    if (!block?.trim()) return { ok: false, content: text };

    const trimmed = block.trim();
    const pairRe = /<\s*fox_extra\b[^>]*>([\s\S]*?)<\s*\/\s*fox_extra\s*>/i;
    const m = pairRe.exec(text);
    if (!m) return { ok: false, content: text };

    const inner = ssStripCurrentPromptInjectBlock(m[1] || '').trim();
    const newInner = inner
      ? `\n${inner}\n\n${trimmed}\n`
      : `\n${trimmed}\n`;

    const replaced = text.replace(pairRe, full => {
      const open = full.match(/<\s*fox_extra\b[^>]*>/i)?.[0] || '<fox_extra>';
      const close = full.match(/<\s*\/\s*fox_extra\s*>/i)?.[0] || '</fox_extra>';
      return `${open}${newInner}${close}`;
    });
    return { ok: true, content: replaced };
  }

  function ssFindFoxExtraPairInPromptArray(arr) {
    if (!Array.isArray(arr)) return null;
    const openRe = /<\s*fox_extra\b[^>]*>/i;
    const closeRe = /<\s*\/\s*fox_extra\s*>/i;
    let openIndex = -1;

    for (let i = 0; i < arr.length; i++) {
      const content = arr[i]?.content;
      if (typeof content !== 'string') continue;
      if (openIndex < 0 && openRe.test(content)) openIndex = i;
      if (openIndex >= 0 && closeRe.test(content)) return { openIndex, closeIndex: i };
    }

    return openIndex >= 0 ? { openIndex, closeIndex: -1 } : null;
  }

  function ssInjectBlockIntoFoxExtraAcrossPromptArray(arr, block) {
    if (!Array.isArray(arr) || !block?.trim()) return false;
    const pair = ssFindFoxExtraPairInPromptArray(arr);
    if (!pair || pair.openIndex < 0) return false;

    const targetIndex = pair.closeIndex >= 0 ? pair.closeIndex : pair.openIndex;
    const target = arr[targetIndex];
    if (!target || typeof target.content !== 'string') return false;

    const before = target.content;
    const after = ssInsertBlockAfterFoxExtra(before, block);
    if (after === before) return false;
    target.content = after;
    return true;
  }

  function ssStripFoxJudgeInjectBlock(text) {
    return String(text || '').replace(
      new RegExp(
        `\\n*${SS_FOXJUDGE_INJECT_START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${SS_FOXJUDGE_INJECT_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\n*`,
        'g'
      ),
      ''
    );
  }

  function ssEnsureKErrorOutputBottomUser(arr) {
    if (!Array.isArray(arr)) return false;
    const enabled = localStorage.getItem(CONFIG.KERROR_OUTPUT_KEY) === 'true';

    for (let i = arr.length - 1; i >= 0; i--) {
      const msg = arr[i];
      if (msg?.role === 'user' && String(msg.content || '').trim() === 'OUTPUT') {
        arr.splice(i, 1);
      }
    }

    if (!enabled) return false;

    arr.push({ role: 'user', content: 'OUTPUT' });
    return true;
  }

  function ssAppendKErrorOutputToPromptString(promptText) {
    let text = String(promptText || '').replace(/\n*user\s*[:：]\s*OUTPUT\s*$/i, '').trimEnd();
    if (localStorage.getItem(CONFIG.KERROR_OUTPUT_KEY) !== 'true') return text;
    return `${text}\n\nuser：OUTPUT`;
  }

  function ssInjectIntoPromptArrayByFoxExtra(arr) {
    if (!Array.isArray(arr)) return false;

    // 🔨 固定拷打：每次原封不动注入到 </User_latest_request> 上方（与 fox_extra 注入互不影响）
    try { ssInjectFixedTortureIntoArray(arr); } catch (e) { log('[固定拷打] 数组注入失败', e); }

    const existingBlock = ssFindExistingCurrentPromptInjectBlockInArray(arr);

    // 先清除旧标记，防止多个事件重复注入。
    // 如果上一轮是独立注入 user 消息，清空后内容为空，则直接移除。
    for (let i = arr.length - 1; i >= 0; i--) {
      const msg = arr[i];

      if (msg && typeof msg.content === 'string') {
        const before = msg.content;
        const after = ssStripCurrentPromptInjectBlock(before);

        msg.content = after;

        if (before !== after && !after.trim()) {
          arr.splice(i, 1);
        }
      }
    }

    // 清除旧的狐裁思维链注入标记，防止重复注入
    for (let i = arr.length - 1; i >= 0; i--) {
      const msg = arr[i];

      if (msg && typeof msg.content === 'string') {
        const before = msg.content;
        const after = ssStripFoxJudgeInjectBlock(before);

        msg.content = after;

        if (before !== after && !after.trim()) {
          arr.splice(i, 1);
        }
      }
    }

    let block = ssBuildCurrentPromptInjectBlock();
    if (!block && existingBlock) block = existingBlock;

    let judgeText = '';
    let judgeVersionSnapshot = 0;
    try {
      const cfg = foxJudgeReadConfig();
      if (cfg.enabled && foxJudgeLastCombined) {
        const cleaned = foxJudgeCleanLeakageAfterThinkClose(foxJudgeLastCombined);
        judgeText = `${SS_FOXJUDGE_INJECT_START}\n${cleaned}\n${SS_FOXJUDGE_INJECT_END}`;
        judgeVersionSnapshot = foxJudgeInjectVersion;
      }
    } catch (e) {
      log('[狐裁] 读取思维链状态失败', e);
    }

    const hasInjectText = !!block || !!judgeText;
    let injected = false;
    let judgeActuallyInjected = false;

    if (block) {
      for (let i = 0; i < arr.length; i++) {
        const msg = arr[i];
        if (!msg || typeof msg.content !== 'string') continue;
        if (!/<\s*fox_extra\b[^>]*>[\s\S]*?<\s*\/\s*fox_extra\s*>/i.test(msg.content)) continue;

        const r = ssInsertBlockInsideFoxExtra(msg.content, block);
        if (r.ok) {
          msg.content = r.content;
          injected = true;
          log(`[统一注入] 已注入到预留的 <fox_extra></fox_extra> 内部（${ssDescribeInjectBlock(block)}）`);
          break;
        }
      }

      if (!injected && ssInjectBlockIntoFoxExtraAcrossPromptArray(arr, block)) {
        injected = true;
        log(`[统一注入] 已跨消息注入到预留的 <fox_extra></fox_extra> 内部（${ssDescribeInjectBlock(block)}）`);
      }

      if (!injected) {
        log('[统一注入] 未找到预留的 <fox_extra></fox_extra>，回退到旧版注入策略');

        const anchorRegex = ssBuildTailAnchorRegex(ssGetTailAnchor());
        let tailIndex = -1;
        if (anchorRegex) {
          tailIndex = arr.findIndex(m =>
            typeof m?.content === 'string' && anchorRegex.test(m.content)
          );
        }

        let userInsertIndex;
        if (tailIndex >= 0) {
          userInsertIndex = tailIndex;
        } else {
          let targetIndex = arr.findIndex(m => m?.role === 'system' && typeof m.content === 'string');
          userInsertIndex = targetIndex >= 0 ? targetIndex + 1 : 0;
        }
        arr.splice(userInsertIndex, 0, { role: 'user', content: block });
      }
    }

    if (judgeText) {
      arr.push({ role: 'assistant', content: judgeText });
      judgeActuallyInjected = true;
      log('[狐裁] 思维链已注入到主模型请求体最底部');
    }

    ssEnsureKErrorOutputBottomUser(arr);

    if (judgeActuallyInjected && judgeVersionSnapshot > 0 && judgeVersionSnapshot !== foxJudgeInjectedToastVersion) {
      foxJudgeInjectedToastVersion = judgeVersionSnapshot;
      try { toast('🦊 狐裁：思维链已注入主模型请求体最下方', 'success'); } catch { }
    }

    return hasInjectText || localStorage.getItem(CONFIG.KERROR_OUTPUT_KEY) === 'true';
  }
  function ssInjectIntoPromptStringByFoxExtra(promptText) {
    let result = String(promptText || '');

    // 🔨 固定拷打：每次原封不动注入到 </User_latest_request> 上方
    try {
      const fixedText = ssGetBeatFixedTorture();
      if (fixedText) result = ssInjectFixedTortureIntoString(result, fixedText);
    } catch (e) { log('[固定拷打] string 注入失败', e); }

    // 先清掉旧标记；如果本次是同一请求的第二个 prompt 事件，保留第一次已经消费/构建出的块。
    const existingBlock = ssExtractCurrentPromptInjectBlock(result);
    result = ssStripCurrentPromptInjectBlock(result);
    result = ssStripFoxJudgeInjectBlock(result);

    let block = ssBuildCurrentPromptInjectBlock();
    if (!block && existingBlock) block = existingBlock;

    let cfg = null;
    try { cfg = foxJudgeReadConfig(); } catch { }
    const judgeText = (cfg?.enabled && foxJudgeLastCombined)
      ? `${SS_FOXJUDGE_INJECT_START}\n${foxJudgeCleanLeakageAfterThinkClose(foxJudgeLastCombined)}\n${SS_FOXJUDGE_INJECT_END}`
      : '';
    const judgeVersionSnapshot = judgeText ? foxJudgeInjectVersion : 0;

    const combinedParts = [];
    if (block) combinedParts.push(block);
    const combinedBlock = combinedParts.join('\n\n');

    if (!combinedBlock && !judgeText) return ssAppendKErrorOutputToPromptString(result);

    let judgeActuallyInjected = false;

    if (combinedBlock) {
      const r = ssInsertBlockInsideFoxExtra(result, combinedBlock);
      if (r.ok) {
        log(`[统一注入] string prompt：已注入到预留的 <fox_extra></fox_extra> 内部（${ssDescribeInjectBlock(block)}）`);
        result = r.content;
      } else {
        // 回退：找不到预留 fox_extra，按尾部锚点或老逻辑注入
        log('[统一注入] string prompt：未找到预留的 <fox_extra></fox_extra>，回退到旧版策略');
        const anchorRegex = ssBuildTailAnchorRegex(ssGetTailAnchor());
        const anchorMatch = anchorRegex ? anchorRegex.exec(result) : null;

        if (anchorMatch && block) {
          const splitIdx = anchorMatch.index;
          const head = result.slice(0, splitIdx);
          const tail = result.slice(splitIdx);
          result = `${head.replace(/\s+$/, '')}\n\n${combinedBlock}\n\n${tail}`;
          log('[统一注入] 回退路径：已插入到尾部锚点之前');
        } else {
          if (block) result = ssInsertBlockAfterFoxExtra(result, block);
          log('[统一注入] 回退路径：默认末尾追加');
        }
      }
    }

    if (judgeText) {
      result = `${result.replace(/\s+$/, '')}\n\n${judgeText}`;
      judgeActuallyInjected = true;
      log('[狐裁] string prompt 思维链已追加到最底部');
    }

    // 🦊 主模型请求时已成功注入思维链：弹 toast 提醒用户（同一版本只弹一次）。
    if (judgeActuallyInjected && judgeVersionSnapshot > 0 && judgeVersionSnapshot !== foxJudgeInjectedToastVersion) {
      foxJudgeInjectedToastVersion = judgeVersionSnapshot;
      try { toast('🦊 狐裁：思维链已注入主模型请求体最下方', 'success'); } catch { }
    }

    return ssAppendKErrorOutputToPromptString(result);
  }

  // ==================== 🔨 固定拷打：注入到 </User_latest_request> 上方 ====================
  // 把"拷打模式 - 固定拷打"面板里的内容，每次请求都原封不动地注入到请求体里
  //   <User_latest_request> ... {{lastUserMessage}} ...（注入到这里）</User_latest_request>
  // 即紧贴 </User_latest_request> 结束标签的上方，用 SS_FIXED_TORTURE_START/END 哨兵包裹。
  // 为避免同一次请求被多个事件（CHAT_COMPLETION_PROMPT_READY / GENERATE_AFTER_COMBINE_PROMPTS）
  // 重复注入，注入前先剥离旧哨兵块再重新注入，保证可靠幂等。
  function ssGetBeatFixedTorture() {
    try {
      return String(state.beatFixedTortureDraft || localStorage.getItem(CONFIG.BEAT_FIXED_TORTURE_KEY) || '').trim();
    } catch {
      return '';
    }
  }

  // 固定拷打注入用的哨兵标记：用它来可靠地去重/剥离，避免靠 endsWith 的脆弱判断。
  const SS_FIXED_TORTURE_START = '<!-- SS_FIXED_TORTURE_START -->';
  const SS_FIXED_TORTURE_END = '<!-- SS_FIXED_TORTURE_END -->';

  // 从内容里剥离之前注入的固定拷打哨兵块（含标记本身及其前后多余空白）。
  function ssStripFixedTortureBlock(content) {
    if (typeof content !== 'string' || !content) return content;
    const re = new RegExp(
      `\\s*${SS_FIXED_TORTURE_START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${SS_FIXED_TORTURE_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*`,
      'g'
    );
    return content.replace(re, '\n\n');
  }

  // 在单条字符串内容里，把 fixedText 注入到 </User_latest_request> 上方。
  // 返回新的字符串（无 </User_latest_request> 或无固定拷打文本时原样返回）。
  // 幂等：先剥离旧哨兵块再重新注入，无论中间是否夹了其他内容都不会重复叠加。
  function ssInjectFixedTortureIntoString(content, fixedText) {
    if (typeof content !== 'string' || !content) return content;
    if (!fixedText) return ssStripFixedTortureBlock(content);

    // 先剥离上一次注入的哨兵块，保证幂等。
    const cleaned = ssStripFixedTortureBlock(content);

    const closeRe = /<\/User_latest_request>/i;
    const m = closeRe.exec(cleaned);
    if (!m) return cleaned;

    const idx = m.index;
    const before = cleaned.slice(0, idx).replace(/\s+$/, '');
    const after = cleaned.slice(idx);

    const block = `${SS_FIXED_TORTURE_START}\n${fixedText}\n${SS_FIXED_TORTURE_END}`;
    return `${before}\n\n${block}\n\n${after}`;
  }

  // 数组形态：遍历每条消息的 content，注入到第一条命中 </User_latest_request> 的消息里
  function ssInjectFixedTortureIntoArray(arr) {
    if (!Array.isArray(arr)) return;
    const fixedText = ssGetBeatFixedTorture();

    // ✅ 先对所有消息全局剥离旧哨兵块，保证最终只有本次目标消息带固定拷打，
    //    避免目标消息在不同事件间位置变化时其它消息里残留旧注入。
    for (const msg of arr) {
      if (msg && typeof msg.content === 'string') {
        const stripped = ssStripFixedTortureBlock(msg.content);
        if (stripped !== msg.content) msg.content = stripped;
      }
    }

    if (!fixedText) return;

    for (let i = 0; i < arr.length; i++) {
      const msg = arr[i];
      if (!msg || typeof msg.content !== 'string') continue;
      if (!/<\/User_latest_request>/i.test(msg.content)) continue;
      const next = ssInjectFixedTortureIntoString(msg.content, fixedText);
      if (next !== msg.content) {
        msg.content = next;
        log('[固定拷打] 已注入到 </User_latest_request> 上方');
      }
      break; // 只注入第一条命中的消息
    }
  }


  function ssDefaultIncludeTagPairs() {
    return [
      { start: '<All_Context>', end: '</All_Context>' },
      { start: '<content>', end: '</content>' },
    ];
  }

  function ssDefaultExcludeTagPairs() {
    return [
      { start: '<stage_2_pre_output_check>', end: '</stage_2_pre_output_check>' },
      { start: '<stage_1_base_requirements>', end: '</stage_1_base_requirements>' },
      { start: '<think_fox~>', end: '</think_fox~>' },
    ];
  }

  // 🦊 大总结默认标签清洗：只清掉 fox_selc / fox_tip / think_fox~ 三类标签内容，
  // 其余正文全部保留。大总结只读聊天记录，不读平行世界/狐忆/狐构/狐搜等任何其他内容。
  function ssDefaultSummaryFilterSettings() {
    return {
      enableContentFilter: true,
      includeTagPairs: [],
      excludeTagPairs: [
        { start: '<fox_selc>', end: '</fox_selc>' },
        { start: '<fox_tip>', end: '</fox_tip>' },
        { start: '<think_fox~>', end: '</think_fox~>' },
      ],
    };
  }

  function ssPairsToLines(pairs, side) {
    return (pairs || []).map(p => side === 'start' ? (p.start || '') : (p.end || '')).join('\n');
  }

  function ssLinesToPairs(startText, endText) {
    const starts = String(startText ?? '').split('\n').map(x => x.trim());
    const ends = String(endText ?? '').split('\n').map(x => x.trim());
    const max = Math.max(starts.length, ends.length);
    const pairs = [];

    for (let i = 0; i < max; i++) {
      const start = starts[i] || '';
      const end = ends[i] || '';

      // 两边都空才跳过；允许“只填开始”或“只填结束”
      if (!start && !end) continue;

      pairs.push({ start, end });
    }

    return pairs;
  }

  function ssNormalizeTagFilterSettings(settings = {}) {
    const s = { ...settings };

    // 新版优先：includeTagPairs / excludeTagPairs
    if (!Array.isArray(s.includeTagPairs)) {
      if (typeof s.includeTagStarts === 'string' || typeof s.includeTagEnds === 'string') {
        s.includeTagPairs = ssLinesToPairs(s.includeTagStarts || '', s.includeTagEnds || '');
      } else {
        s.includeTagPairs = ssDefaultIncludeTagPairs();
      }
    }

    if (!Array.isArray(s.excludeTagPairs)) {
      if (typeof s.excludeTagStarts === 'string' || typeof s.excludeTagEnds === 'string') {
        s.excludeTagPairs = ssLinesToPairs(s.excludeTagStarts || '', s.excludeTagEnds || '');
      } else {
        s.excludeTagPairs = ssDefaultExcludeTagPairs();
      }
    }

    // 兼容旧版错误默认值
    const incStarts = String(s.includeTagStarts || '').trim();
    const incEnds = String(s.includeTagEnds || '').trim();

    if (
      incStarts === '<content\n<All_Context\n<SearchResults' ||
      incStarts === '<content\r\n<All_Context\r\n<SearchResults'
    ) {
      s.includeTagPairs = ssDefaultIncludeTagPairs();
    }

    if (
      incEnds === 'content>\nAll_Context>\nSearchResults>' ||
      incEnds === 'content>\r\nAll_Context>\r\nSearchResults>'
    ) {
      s.includeTagPairs = ssDefaultIncludeTagPairs();
    }

    // 兼容旧版把 <think_fox~> 填到排除开始标签的错误配置
    if (
      String(s.excludeTagStarts || '').trim() === '<think_fox~>' &&
      !String(s.excludeTagEnds || '').trim()
    ) {
      s.excludeTagPairs = ssDefaultExcludeTagPairs();
    }

    if (
      String(s.excludeTagStarts || '').trim() === '<think_fox~' &&
      !String(s.excludeTagEnds || '').trim()
    ) {
      s.excludeTagPairs = ssDefaultExcludeTagPairs();
    }

    // 兼容旧版 think_fox~ 排除标签“只有尾没有头”的错误配置：
    // 把 { start:'', end:'</think_fox~>' } 自动补成有头有尾的 { start:'<think_fox~>', end:'</think_fox~>' }
    if (Array.isArray(s.excludeTagPairs)) {
      for (const p of s.excludeTagPairs) {
        if (
          p &&
          (!p.start || String(p.start).trim() === '') &&
          String(p.end || '').trim() === '</think_fox~>'
        ) {
          p.start = '<think_fox~>';
        }
      }
    }

    // 同步旧字段，方便旧逻辑/导出备份兼容
    s.includeTagStarts = ssPairsToLines(s.includeTagPairs, 'start');
    s.includeTagEnds = ssPairsToLines(s.includeTagPairs, 'end');
    s.excludeTagStarts = ssPairsToLines(s.excludeTagPairs, 'start');
    s.excludeTagEnds = ssPairsToLines(s.excludeTagPairs, 'end');

    return s;
  }

  function ssMergeRanges(ranges) {
    const arr = ranges
      .filter(r => Array.isArray(r) && r.length === 2 && r[0] < r[1])
      .sort((a, b) => a[0] - b[0]);

    if (!arr.length) return [];

    const merged = [arr[0]];

    for (let i = 1; i < arr.length; i++) {
      const last = merged[merged.length - 1];
      const cur = arr[i];

      if (cur[0] <= last[1]) {
        last[1] = Math.max(last[1], cur[1]);
      } else {
        merged.push(cur);
      }
    }

    return merged;
  }

  function ssRemoveRanges(text, ranges) {
    const raw = String(text || '');
    const merged = ssMergeRanges(ranges);

    if (!merged.length) return raw;

    let result = '';
    let last = 0;

    for (const [s, e] of merged) {
      if (s > last) result += raw.slice(last, s);
      last = Math.max(last, e);
    }

    result += raw.slice(last);
    return result;
  }

  function ssFindTagRanges(text, startTag, endTag, mode = 'include') {
    const raw = String(text || '');
    const ranges = [];

    const start = String(startTag || '');
    const end = String(endTag || '');

    // 开始 + 结束
    if (start && end) {
      let pos = 0;

      while (pos < raw.length) {
        const sIdx = raw.indexOf(start, pos);
        if (sIdx < 0) break;

        const contentStart = sIdx + start.length;
        const eIdx = raw.indexOf(end, contentStart);
        if (eIdx < 0) break;

        if (mode === 'exclude') {
          ranges.push([sIdx, eIdx + end.length]);
        } else {
          ranges.push([contentStart, eIdx]);
        }

        pos = eIdx + end.length;
      }

      return ranges;
    }

    // 只填开始：从开始标签到末尾
    if (start && !end) {
      const sIdx = raw.indexOf(start);

      if (sIdx >= 0) {
        if (mode === 'exclude') ranges.push([sIdx, raw.length]);
        else ranges.push([sIdx + start.length, raw.length]);
      }

      return ranges;
    }

    // 只填结束：从开头到结束标签
    if (!start && end) {
      const eIdx = raw.indexOf(end);

      if (eIdx >= 0) {
        if (mode === 'exclude') ranges.push([0, eIdx + end.length]);
        else ranges.push([0, eIdx]);
      }

      return ranges;
    }

    return ranges;
  }

  function ssApplyExcludeToChunk(fullText, chunkStart, chunkEnd, excludeRanges) {
    const localRanges = [];

    for (const [s, e] of excludeRanges) {
      const ss = Math.max(s, chunkStart);
      const ee = Math.min(e, chunkEnd);

      if (ss < ee) {
        localRanges.push([ss - chunkStart, ee - chunkStart]);
      }
    }

    const chunk = String(fullText || '').slice(chunkStart, chunkEnd);
    return ssRemoveRanges(chunk, localRanges).trim();
  }

  function ssFilterByTagPairs(rawMessage, settings, opts = {}) {
    const raw = String(rawMessage || '');
    if (!raw.trim()) return '';

    const s = ssNormalizeTagFilterSettings(settings || {});
    if (s.enableContentFilter === false) return raw.trim();

    const includePairs = Array.isArray(s.includeTagPairs) ? s.includeTagPairs : [];
    const excludePairs = Array.isArray(s.excludeTagPairs) ? s.excludeTagPairs : [];

    let excludeRanges = [];

    for (const pair of excludePairs) {
      excludeRanges.push(
        ...ssFindTagRanges(raw, pair.start, pair.end, 'exclude')
      );
    }

    excludeRanges = ssMergeRanges(excludeRanges);

    // 没有包含标签：读取全文，但扣掉排除标签
    if (!includePairs.length) {
      return ssRemoveRanges(raw, excludeRanges).trim();
    }

    let includeRanges = [];

    for (const pair of includePairs) {
      includeRanges.push(
        ...ssFindTagRanges(raw, pair.start, pair.end, 'include')
      );
    }

    includeRanges = ssMergeRanges(includeRanges);

    // ✅ 严格模式：
    // 只要配置了包含标签，就只允许读取匹配到的包含标签内容。
    // 没匹配到时默认返回空，绝不回退全文。
    if (!includeRanges.length) {
      return opts.fallbackToFullText === true
        ? ssRemoveRanges(raw, excludeRanges).trim()
        : '';
    }

    const parts = [];

    for (const [sIdx, eIdx] of includeRanges) {
      const chunk = ssApplyExcludeToChunk(raw, sIdx, eIdx, excludeRanges);
      if (chunk) parts.push(chunk);
    }

    // ✅ 即使包含标签内部被排除标签删空，也不回退全文
    return parts.join('\n\n').trim();
  }

  function ssCreateTagPairsEditorHtml(prefix, title, pairs, hint = '') {
