          if (HUSHEN_PREF_IDENTIFIER_SET.has(ref)) {
            p.content = '';
            p.enabled = false;
            foundAny = true;
          }
        }
        savePrompts();
      }
    }

    if (foundAny) toast('⚠️ 已清除所有用户偏好注入', 'success');
    else toast('⚠️ 未找到任何用户偏好条目', 'warning');

    return foundAny;
  }

  function getPreferenceStates() {
    const states = {};

    let prompts = [];
    try {
      prompts = getPreset?.('in_use')?.prompts || getPromptsArray() || [];
    } catch {
      prompts = getPromptsArray() || [];
    }

    for (const mod of HUSHEN_MODULES) {
      const entry = prompts.find(p => p?.identifier === mod.identifier || p?.id === mod.identifier);
      states[mod.id] = entry?.enabled === true;
    }

    return states;
  }


