  function loadOutlineFilterSettings() {
    const defaults = ssNormalizeTagFilterSettings({
      enableContentFilter: true,

      // 狐构默认读取完整上下文，不默认限定 <content>
      // 因为狐构需要读取正文以外的角色设定、世界书、玩家设定、聊天上下文。
      includeTagPairs: [],

      // 只删除污染块
      excludeTagPairs: ssDefaultExcludeTagPairs(),
    });

    try {
      const raw = localStorage.getItem(CONFIG.OUTLINE_FILTER_KEY);
      if (!raw) return defaults;

      const parsed = JSON.parse(raw);

      let merged = ssNormalizeTagFilterSettings({
        ...defaults,
        ...parsed,
      });

      // ✅ 迁移旧版狐构默认：如果包含标签还是旧的 <content> + <All_Context>，
      // 说明用户没主动改过，强制改成“读取完整请求体”。
      const inc = JSON.stringify(merged.includeTagPairs || []);
      const old1 = JSON.stringify([
        { start: '<content>', end: '</content>' },
        { start: '<All_Context>', end: '</All_Context>' },
      ]);
      const old2 = JSON.stringify([
        { start: '<All_Context>', end: '</All_Context>' },
        { start: '<content>', end: '</content>' },
      ]);

      if (inc === old1 || inc === old2) {
        merged.includeTagPairs = [];
        merged.includeTagStarts = '';
        merged.includeTagEnds = '';
      }

      return merged;
    } catch {
      return defaults;
    }
  }
  function saveOutlineFilterSettings() {
    try {
      state.outlineFilterSettings = ssNormalizeTagFilterSettings(
        state.outlineFilterSettings || loadOutlineFilterSettings()
      );

      localStorage.setItem(
        CONFIG.OUTLINE_FILTER_KEY,
        JSON.stringify(state.outlineFilterSettings)
      );
    } catch (e) {
      log('[狐构] 保存标签过滤设置失败', e);
    }
  }
  function outlineParseTagPairs(startText, endText) {
    const starts = String(startText || '')
      .split('\n')
      .map(x => x.trim())
      .filter(Boolean);

    const ends = String(endText || '')
      .split('\n')
      .map(x => x.trim())
      .filter(Boolean);

    const max = Math.max(starts.length, ends.length);
    const pairs = [];

    for (let i = 0; i < max; i++) {
      pairs.push({
        start: starts[i] || '',
        end: ends[i] || '',
      });
    }

    return pairs;
  }

  function outlineMergeRanges(ranges) {
    const arr = ranges
      .filter(r => Array.isArray(r) && r.length === 2 && r[0] < r[1])
      .sort((a, b) => a[0] - b[0]);

    if (!arr.length) return [];

    const merged = [arr[0]];

    for (let i = 1; i < arr.length; i++) {
      const last = merged[merged.length - 1];
      const cur = arr[i];

      if (cur[0] <= last[1]) {
        last[1] = Math.max(last[1], cur[1]);
      } else {
        merged.push(cur);
      }
    }

    return merged;
  }

  function outlineRemoveRanges(text, ranges) {
    const raw = String(text || '');
    const merged = outlineMergeRanges(ranges);

    if (!merged.length) return raw;

    let result = '';
    let last = 0;

    for (const [s, e] of merged) {
      if (s > last) result += raw.slice(last, s);
      last = Math.max(last, e);
    }

    result += raw.slice(last);
    return result;
  }

  function outlineFindExactRanges(text, startTag, endTag, mode = 'include') {
    const raw = String(text || '');
    const ranges = [];

    const start = String(startTag || '');
    const end = String(endTag || '');

    // 开始 + 结束
    if (start && end) {
      let pos = 0;

      while (pos < raw.length) {
        const sIdx = raw.indexOf(start, pos);
        if (sIdx < 0) break;

        const contentStart = sIdx + start.length;
        const eIdx = raw.indexOf(end, contentStart);
        if (eIdx < 0) break;

        if (mode === 'exclude') {
          ranges.push([sIdx, eIdx + end.length]);
        } else {
          ranges.push([contentStart, eIdx]);
        }

        pos = eIdx + end.length;
      }

      return ranges;
    }

    // 只填开始标签
    if (start && !end) {
      const sIdx = raw.indexOf(start);

      if (sIdx >= 0) {
        if (mode === 'exclude') {
          ranges.push([sIdx, raw.length]);
        } else {
          ranges.push([sIdx + start.length, raw.length]);
        }
      }

      return ranges;
    }

    // 只填结束标签
    // include：取结束标签之前
    // exclude：排除结束标签之前，包括结束标签本身
    if (!start && end) {
      const eIdx = raw.indexOf(end);

      if (eIdx >= 0) {
        if (mode === 'exclude') {
          ranges.push([0, eIdx + end.length]);
        } else {
          ranges.push([0, eIdx]);
        }
      }

      return ranges;
    }

    return ranges;
  }

  function outlineApplyExcludeToChunk(fullText, chunkStart, chunkEnd, excludeRanges) {
    const localRanges = [];

    for (const [s, e] of excludeRanges) {
      const ss = Math.max(s, chunkStart);
      const ee = Math.min(e, chunkEnd);

      if (ss < ee) {
        localRanges.push([ss - chunkStart, ee - chunkStart]);
      }
    }

    const chunk = fullText.slice(chunkStart, chunkEnd);
    return outlineRemoveRanges(chunk, localRanges).trim();
  }

  function outlineFilterMessageContent(rawMessage) {
    const raw = String(rawMessage || '');
    if (!raw.trim()) return '';

    const s = state.outlineFilterSettings || loadOutlineFilterSettings();
    state.outlineFilterSettings = s;

    if (!s.enableContentFilter) return raw.trim();

    const includeTags = outlineParseTagPairs(s.includeTagStarts, s.includeTagEnds);
    const excludeTags = outlineParseTagPairs(s.excludeTagStarts, s.excludeTagEnds);

    let excludeRanges = [];

    for (const tag of excludeTags) {
      excludeRanges.push(
        ...outlineFindExactRanges(raw, tag.start, tag.end, 'exclude')
      );
    }

    excludeRanges = outlineMergeRanges(excludeRanges);

    // 没有配置包含标签：读取全文，但扣掉排除范围
    if (!includeTags.length) {
      return outlineRemoveRanges(raw, excludeRanges).trim();
    }

    let includeRanges = [];

    for (const tag of includeTags) {
      includeRanges.push(
        ...outlineFindExactRanges(raw, tag.start, tag.end, 'include')
      );
    }

    includeRanges = outlineMergeRanges(includeRanges);

    // ✅ 狐构默认是“只读取 <content>...</content>”
    // 所以配置了包含标签但没匹配到时，不回退全文，直接跳过。
    if (!includeRanges.length) {
      return '';
    }

    const parts = [];

    for (const [sIdx, eIdx] of includeRanges) {
      const chunk = outlineApplyExcludeToChunk(raw, sIdx, eIdx, excludeRanges);
      if (chunk) parts.push(chunk);
    }

    return parts.join('\n\n').trim();
  }

  function outlineGetContextStartIdByActualFloors(lastId, floorLimit) {
    const limit = Math.max(0, parseInt(floorLimit) || 0);
    if (limit <= 0) return 0;
    return Math.max(0, Number(lastId) - limit + 1);
  }

  function outlineCountActualFloorsBetween(fromExclusive, toInclusive) {
    const from = Math.max(0, Number(fromExclusive) + 1);
    const to = Math.max(0, Number(toInclusive));
    if (!Number.isFinite(from) || !Number.isFinite(to) || to < from) return 0;
    return to - from + 1;
  }

  function outlineGetContext() {
    const parts = [];

    if (!state.outlineFilterSettings) {
      state.outlineFilterSettings = loadOutlineFilterSettings();
    }

    // ===== 1. 角色卡基础信息 =====
    try {
      const ctx = SillyTavern?.getContext?.();
      const char = ctx?.characters?.[ctx?.characterId];

      if (char) {
        if (char.name?.trim()) {
          parts.push(`【角色名】\n${char.name}`);
        }

        if (char.description?.trim()) {
          parts.push(`【角色描述】\n${char.description}`);
        }

        if (char.personality?.trim()) {
          const personality = String(char.personality || '')
            .replace(/【🦊狐搜外部搜索参考[\s\S]*?【外部搜索参考结束】/g, '')
            .replace(/【🔍 外部搜索参考[\s\S]*?【外部搜索参考结束】/g, '')
            .trim();

          if (personality) {
            parts.push(`【性格】\n${personality}`);
          }
        }

        if (char.scenario?.trim()) {
          parts.push(`【场景】\n${char.scenario}`);
        }
      }
    } catch (e) {
      log('[狐构] 读取角色卡上下文失败', e);
    }

    // ===== 2. 聊天记录：楼层范围按实际楼层计算，用户楼层也计数 =====
    try {
      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');

      if (glmi && gcm) {
        const lid = glmi();

        if (lid >= 0) {
          const floorLimit = Math.max(0, parseInt(state.outlineContextFloors) || 0);

          const startId = outlineGetContextStartIdByActualFloors(lid, floorLimit);
          const range = `${startId}-${lid}`;

          const ms = gcm(range, {
            hide_state: 'all',
            include_swipes: false,
          }) || [];

          const chatText = ms
            .filter(m => m && typeof m.message === 'string')
            .map(m => {
              const isUser = m.role === 'user';
              const isChar = m.role === 'assistant';

              const role = isUser
                ? '用户'
                : (isChar ? 'AI' : '系统');

              const name = m.name ? `/${m.name}` : '';
              const hiddenMark = m.is_hidden ? '（隐藏楼层）' : '';

              let msg = String(m.message || '');

              // 去掉系统性注入块，避免污染狐构修正
              msg = msg
                .replace(new RegExp(`${CONFIG.SUMMARY_FLOOR_START}[\\s\\S]*?${CONFIG.SUMMARY_FLOOR_END}`, 'g'), '')
                .replace(new RegExp(`${FULL_SUMMARY_FLOOR_MARK}[\\s\\S]*`, 'g'), '')
                .replace(/<fox_outline>[\s\S]*?<\/fox_outline>/gi, '')
                .trim();

              if (!msg) return '';

              let finalMsg = '';

              if (isChar) {
                // ✅ 标签过滤只作用于 AI/char 楼层。
                // 默认只取 <content>...</content>，并排除 </think_fox~> 之前内容。
                finalMsg = outlineFilterMessageContent(msg);
              } else {
                // ✅ 用户楼层不做 <content> 标签过滤，直接保留用户输入。
                // 用户楼层也不参与“最近 N 楼”的统计。
                finalMsg = msg;
              }

              if (!finalMsg.trim()) return '';

              return `【第${m.message_id}楼 ${role}${name}${hiddenMark}】\n${finalMsg.trim()}`;
            })
            .filter(Boolean)
            .join('\n\n');

              const rangeText = floorLimit > 0
            ? `最近 ${floorLimit} 个实际楼层｜实际读取范围：${range}`
            : `全部楼层｜实际读取范围：${range}`;

          if (chatText.trim()) {
            parts.push(`【聊天记录｜${rangeText}】\n${chatText}`);
          } else {
            parts.push(`【聊天记录｜${rangeText}】\n（未读取到符合狐构规则的内容。若 AI 楼层没有 <content> 标签，请关闭狐构标签过滤或调整包含标签。）`);
          }
        }
      }
    } catch (e) {
      log('[狐构] 读取聊天记录失败', e);
    }

    return parts.join('\n\n');
  }

  // ✅ 狐构专用：构建“已标签过滤”的 chat_history prompts
  // 注意：
  // 1. 不手动读取世界书，不手动拼角色卡，避免重复。
  // 2. 世界书/角色卡/场景由 generate({ preset_name:'in_use' }) 的原始请求自动处理。
  // 3. 这里只覆盖 chat_history，让聊天记录经过狐构标签过滤。
  // 4. AI/assistant 楼层使用标签过滤；用户楼层原样保留。
  function outlineGetFilteredChatHistoryPrompts() {
    const prompts = [];

    if (!state.outlineFilterSettings) {
      state.outlineFilterSettings = loadOutlineFilterSettings();
    }

    try {
      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');

      if (!glmi || !gcm) return prompts;

      const lid = glmi();
      if (lid < 0) return prompts;

      const floorLimit = Math.max(0, parseInt(state.outlineContextFloors) || 0);
      const startId = outlineGetContextStartIdByActualFloors(lid, floorLimit);
      const range = `${startId}-${lid}`;

      const ms = gcm(range, {
        hide_state: 'all',
        include_swipes: false,
      }) || [];

      for (const m of ms) {
        if (!m || typeof m.message !== 'string') continue;

        const role = m.role === 'assistant'
          ? 'assistant'
          : (m.role === 'user' ? 'user' : 'system');

        let msg = String(m.message || '');

        // 去掉玄狐自己注入的系统性块，避免污染狐构
        msg = msg
          .replace(new RegExp(`${CONFIG.SUMMARY_FLOOR_START}[\\s\\S]*?${CONFIG.SUMMARY_FLOOR_END}`, 'g'), '')
          .replace(new RegExp(`${FULL_SUMMARY_FLOOR_MARK}[\\s\\S]*`, 'g'), '')
          .replace(/<fox_outline>[\s\S]*?<\/fox_outline>/gi, '')
          .trim();

        if (!msg) continue;

        let finalMsg = '';

        if (role === 'assistant') {
          // ✅ AI 楼层走狐构标签过滤
          finalMsg = outlineFilterMessageContent(msg);
        } else {
          // ✅ 用户楼层不做 content 过滤
          finalMsg = msg;
        }

        if (!finalMsg.trim()) continue;

        const name = m.name ? `/${m.name}` : '';
        const hiddenMark = m.is_hidden ? '（隐藏楼层）' : '';

        prompts.push({
          role,
          content: `【第${m.message_id}楼 ${role}${name}${hiddenMark}】\n${finalMsg.trim()}`,
        });
      }

      log(`[狐构] 已构建过滤后 chat_history：${prompts.length} 条，范围 ${range}`);
    } catch (e) {
      log('[狐构] 构建过滤后 chat_history 失败', e);
    }

    return prompts;
  }
  // ==================== 狐构固定上下文顺序 ====================
  // 按用户要求固定顺序：
  // 1. charDescription
  // 2. personaDescription
  // 3. worldInfoBefore
  // 4. worldInfoAfter
  // 5. chatHistory
  //
  // chatHistory 中：
