  // - user 楼层不做标签过滤
  // - 不做字数限制

  function outlineBuildFixedContextOrderedPrompts() {
    // 狐构和狐忆统一使用同一个固定上下文构建函数。
    // 顺序固定：
    // char_description → persona_description → world_info_before → world_info_after → chatHistory
    // user 消息不做标签过滤，assistant/char 消息按当前模块过滤设置处理。
    return ssBuildFixedContextOrderedPrompts(
      state.outlineFilterSettings || loadOutlineFilterSettings()
    );
