  // ==================== 🦊 狐构注入策略覆盖：本地为准，默认不注入预设 ====================

  function outlineIsInjectToPreset() {
    return localStorage.getItem(CONFIG.OUTLINE_INJECT_TO_PRESET_KEY) === 'true';
  }

  async function outlineSyncPresetByConfig(rawOutline = state.outlineText) {
    const raw = String(rawOutline || '').trim();
    const injectToPreset = outlineIsInjectToPreset();

    state.outlineInjectToPreset = injectToPreset;

    if (injectToPreset && raw) {
      await setPromptContentById(CONFIG.OUTLINE_ID, ssBuildOutlineInject(raw));
      await togglePromptById(CONFIG.OUTLINE_ID, true);
      log('[狐构] 已同步到预设条目');
    } else {
      // 默认：关闭预设条目并清空，避免跨角色卡污染
      await setPromptContentById(CONFIG.OUTLINE_ID, '');
      await togglePromptById(CONFIG.OUTLINE_ID, false);
      log('[狐构] 已关闭预设注入，仅保留本地大纲');
    }
  }

  // 覆盖旧函数：保存时只写 localStorage；是否写预设取决于开关
  outlineSetRawAndInject = async function (rawOutline) {
    const raw = String(rawOutline || '').trim();

    state.outlineText = raw;
    outlineSaveLocalRaw(raw);

    await outlineSyncPresetByConfig(raw);
  };

  // 覆盖旧函数：读取时永远本地优先；预设只作为旧数据迁移来源
  outlineLoadCurrentText = function () {
    const localRaw = outlineLoadLocalRaw();

    if (localRaw.trim()) {
      state.outlineText = localRaw;
      return localRaw;
    }

    // 兼容旧版本：如果旧预设里有大纲，迁移进当前角色卡本地库
    const promptRaw = outlineReadRawFromPrompt();

    if (promptRaw.trim()) {
      state.outlineText = promptRaw;
