  function renderOutlineCandidates(cards, rawText) {
    const container = topDoc.getElementById('ss-outline-candidates');
    if (!container) return;

    container.innerHTML = '';

    cards.forEach((card, i) => {
      const el = topDoc.createElement('div');
      el.className = 'outline-card';
      el.dataset.index = i;

      el.innerHTML = `
        <div class="outline-card-header">
          <span class="outline-card-title">${escapeHtml(card.title)}</span>
          <span class="outline-card-reveal-btn" data-reveal="${i}">👁 显示全文</span>
        </div>
        <div class="outline-card-body">${escapeHtml(card.content)}</div>
      `;

      // ✅ 修复点1：
      // 点击“显示全文”按钮时，才触发剧透警告和解除模糊。
      const revealBtn = el.querySelector('.outline-card-reveal-btn');
      if (revealBtn) {
        revealBtn.addEventListener('click', (ev) => {
          ev.preventDefault();
          ev.stopPropagation();

          if (el.classList.contains('revealed')) return;

          const ok = topWindow?.confirm
            ? topWindow.confirm('⚠️ 剧透警告！确定要查看大纲内容吗？')
            : confirm('⚠️ 剧透警告！确定要查看大纲内容吗？');

          if (!ok) return;

          el.classList.add('revealed');
          revealBtn.textContent = '✓ 已显示';
        });
      }

      // ✅ 修复点2：
      // 点击卡片本体 = 直接注入。
      // 不再强制显示全文，不再弹剧透警告。
      el.addEventListener('click', async () => {
        if (state.outlineSelectedCard === i) {
          toast(`✅ 「${card.title}」已经是当前注入大纲`, 'info');
