  function foxMemoryNormalizeExtractionSettings(config = foxMemoryConfig) {
    const detail = ['high', 'medium', 'low'].includes(config?.extractionDetailLevel)
      ? config.extractionDetailLevel
      : 'medium';

    let minWords = parseInt(config?.extractionMinWords);
    let maxWords = parseInt(config?.extractionMaxWords);

    if (!Number.isFinite(minWords)) minWords = 50;
    if (!Number.isFinite(maxWords)) maxWords = 300;

    minWords = Math.max(1, minWords);
    maxWords = Math.max(minWords, maxWords);

    return { detail, minWords, maxWords, preset: FOX_MEMORY_EXTRACTION_DETAIL_PRESETS[detail] };
  }

  function foxMemoryBuildExtractionControlPrompt(config = foxMemoryConfig) {
