    '2a7e29d8-0162-4a68-a733-68914349f121',
    '1d72c92b-3aa8-43f3-b9ad-69509ac08d28',
    '3f087674-153f-42e7-aa25-bafab147f1e9',
    '72a4289f-5e61-4c3e-8577-fd00ca52ed6b',
  ];
  const FOX_JUDGE_PRESET_SNAPSHOT_KEY = 'SPreset_FoxJudge_PresetSnapshot';

  const FOX_JUDGE_MODIFIED_IDS = [
