  function foxJudgeIsPresetAutoApplied() {
    try {
      if (!isPromptEnabledInPreset(FOX_JUDGE_NO_COT_ID)) return false;
      if (isPromptEnabledInPreset(FOX_JUDGE_DIRECT_OUT_THINK_ID)) return false;
      if (isPromptEnabledInPreset(FOX_JUDGE_DIRECT_OUT_ID)) return false;
      for (const id of FOX_JUDGE_COT_IDS) {
        if (isPromptEnabledInPreset(id)) return false;
      }
      for (const id of FOX_JUDGE_THINKING_STRENGTH_IDS) {
        if (isPromptEnabledInPreset(id)) return false;
      }
      return true;
    } catch {
      return false;
    }
  }

  async function foxJudgeApplyAutoPresetChanges() {
    try {
      const changesToSave = {};
      try {
        const preset = getPreset('in_use');
        for (const p of preset.prompts || []) {
          const ref = p.id || p.identifier || '';
          if (FOX_JUDGE_MODIFIED_IDS.includes(ref)) {
            changesToSave[ref] = !!p.enabled;
          }
        }
      } catch {}
      localStorage.setItem(FOX_JUDGE_PRESET_SNAPSHOT_KEY, JSON.stringify(changesToSave));
      log('[狐裁] 已保存被修改条目的原始状态', Object.keys(changesToSave).length, '条');

      await updatePresetWith('in_use', (preset) => {
        for (const p of preset.prompts || []) {
          const ref = p.id || p.identifier || '';
          if (FOX_JUDGE_COT_IDS.includes(ref)) p.enabled = false;
          if (ref === FOX_JUDGE_NO_COT_ID) p.enabled = true;
          // ✅ 用户要求：开启内置思维链时，两个尾部条目都直接关闭，不要打开任意一个
          if (ref === FOX_JUDGE_DIRECT_OUT_THINK_ID) p.enabled = false;
          if (ref === FOX_JUDGE_DIRECT_OUT_ID) p.enabled = false;
          if (FOX_JUDGE_THINKING_STRENGTH_IDS.includes(ref)) p.enabled = false;
        }
        return preset;
      });

      if (!foxJudgeIsPresetAutoApplied()) {
        await updatePresetWith('in_use', (preset) => {
          for (const p of preset.prompts || []) {
            const ref = p.id || p.identifier || '';
            if (FOX_JUDGE_COT_IDS.includes(ref)) p.enabled = false;
            if (ref === FOX_JUDGE_NO_COT_ID) p.enabled = true;
            if (ref === FOX_JUDGE_DIRECT_OUT_THINK_ID) p.enabled = false;
            if (ref === FOX_JUDGE_DIRECT_OUT_ID) p.enabled = false;
            if (FOX_JUDGE_THINKING_STRENGTH_IDS.includes(ref)) p.enabled = false;
          }
          return preset;
        }, { render: 'immediate' });
      }

      if (!foxJudgeIsPresetAutoApplied()) {
        toast('⚠️ 狐裁防呆：预设选项自动修改未完全生效，请重新打开预设确认', 'warning');
      }

      log('[狐裁] 已自动切换：思维链→无思维链，尾部→两个全部关闭，思考强度→关闭');
    } catch (e) {
      log('[狐裁] 自动切换预设失败', e);
    }
  }

  async function foxJudgeRestorePresetFromSnapshot() {
    try {
      const raw = localStorage.getItem(FOX_JUDGE_PRESET_SNAPSHOT_KEY);
      if (!raw) {
        log('[狐裁] 无预设快照，跳过恢复');
        return;
      }
      const changes = JSON.parse(raw);
      await updatePresetWith('in_use', (preset) => {
        for (const p of preset.prompts || []) {
          const ref = p.id || p.identifier || '';
          if (ref in changes) {
            p.enabled = changes[ref];
          }
        }
        return preset;
      });
      localStorage.removeItem(FOX_JUDGE_PRESET_SNAPSHOT_KEY);
      log('[狐裁] 已从快照恢复被修改的预设条目', Object.keys(changes).length, '条');
    } catch (e) {
      log('[狐裁] 恢复预设快照失败', e);
    }
  }

  function foxJudgeGetStaticCache(charId) {
    try {
      const raw = localStorage.getItem(FOX_JUDGE_LS_KEYS.charCachePrefix + charId);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || parsed.version !== 2) return null;
      if (parsed.char_id !== charId) return null;
      return parsed;
    } catch { return null; }
  }

  function foxJudgeSaveStaticCache(charId, cache) {
    try {
      localStorage.setItem(
        FOX_JUDGE_LS_KEYS.charCachePrefix + charId,
        JSON.stringify(cache)
      );
    } catch (e) {
      log('[狐裁] 缓存保存失败', e);
    }
  }

  function foxJudgeInvalidateStaticCache() {
    try {
      const keys = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith(FOX_JUDGE_LS_KEYS.charCachePrefix)) keys.push(k);
      }
      keys.forEach(k => localStorage.removeItem(k));
      log(`[狐裁] 已清空 ${keys.length} 个缓存`);
    } catch (e) {
      log('[狐裁] 缓存清空失败', e);
    }
  }

  function foxJudgeBuildCustomApiParams(cfg) {
    if (!cfg) return null;
    if (cfg.apiType !== 'custom') return null;
    const ca = cfg.customApi || {};
    if (!ca.apiurl && !ca.proxyPreset) return null;

    const customApi = { source: ca.source || 'openai' };
    if (ca.proxyPreset) customApi.proxy_preset = ca.proxyPreset;
    else {
      if (ca.apiurl) customApi.apiurl = ca.apiurl;
      if (ca.key) customApi.key = ca.key;
    }
    if (ca.model) customApi.model = ca.model;
    if (ca.temperature !== '' && !isNaN(parseFloat(ca.temperature))) customApi.temperature = parseFloat(ca.temperature);
    if (ca.top_p !== '' && !isNaN(parseFloat(ca.top_p))) customApi.top_p = parseFloat(ca.top_p);
    if (ca.frequency_penalty !== '' && !isNaN(parseFloat(ca.frequency_penalty))) customApi.frequency_penalty = parseFloat(ca.frequency_penalty);
    if (ca.presence_penalty !== '' && !isNaN(parseFloat(ca.presence_penalty))) customApi.presence_penalty = parseFloat(ca.presence_penalty);
    if (ca.max_tokens !== '' && !isNaN(parseInt(ca.max_tokens))) customApi.max_tokens = parseInt(ca.max_tokens);
    return customApi;
  }

  // 🦊 狐裁附加参数：根据 cfg.customApi 中的 YAML 文本构建 fetch hook inject。
  //    仅在 apiType === 'custom' 时生效，避免误污染主模型请求。
  function foxJudgeBuildExtraInject(cfg) {
    if (!cfg) return null;
    if (cfg.apiType !== 'custom') return null;
    return ssBuildExtraInjectFromCustomApi(cfg.customApi || {});
  }

  const FOX_JUDGE_DEFAULT_FILTER_SETTINGS = {
    enableContentFilter: true,
    includeTagPairs: [],
    excludeTagPairs: [
      { start: '<think_fox~>', end: '</think_fox~>' },
      { start: '<fox_selc>', end: '</fox_selc>' },
      { start: '<fox_tip>', end: '</fox_tip>' },
      { start: '<User_latest_request>', end: '</User_latest_request>' },
    ],
  };

  function foxJudgeGetFilterSettings() {
    const cfg = foxJudgeReadConfig();
    return cfg.filterSettings || FOX_JUDGE_DEFAULT_FILTER_SETTINGS;
  }

  // ✅ 鲁棒提取：generateRaw 在不同 ST 版本 / custom_api / 推理模型下返回形态不一致：
  //    - 直接 string
  //    - { content: string }
  //    - { text: string } / { message: string } / { output: string }
  //    - { message: { content: string | Array } }（Claude 风格）
  //    - { choices: [{ message: { content }, text }] }（OpenAI 风格）
  //    - { content: [{ type: 'text', text: '...' }] }（Anthropic content blocks）
  //    - 推理模型可能把正文放在 reasoning_content / thinking 字段
  //    任何一种形态没被识别就会导致"明明 AI 回了内容却被判定空回复"。
  function foxJudgeExtractText(r) {
    if (r == null) return '';
    if (typeof r === 'string') {
      // ✅ 部分代理 / 自定义 API 会把整个 JSON 响应体当字符串返回，
      //    直接当纯文本会把 {"choices":[...]} 这种结构误当成"正文"或被判残缺。
      //    仅当看起来像 JSON 对象/数组时才尝试解析，解析失败就按原始字符串处理。
      const s = r.trim();
      if (s && (s[0] === '{' || s[0] === '[') && (s.includes('"content"') || s.includes('"choices"') || s.includes('"reasoning'))) {
        try {
          const parsed = JSON.parse(s);
          const t = foxJudgeExtractText(parsed);
          if (t && t.trim()) return t;
        } catch { }
      }
      return r;
    }
    if (typeof r === 'number' || typeof r === 'boolean') return String(r);
    if (Array.isArray(r)) {
      return r.map(x => foxJudgeExtractText(x)).filter(Boolean).join('\n');
    }
    if (typeof r !== 'object') return '';

    // OpenAI 风格：choices[].message.content / choices[].text / choices[].delta.content
    if (Array.isArray(r.choices) && r.choices.length) {
      const parts = r.choices.map(c => {
        if (!c) return '';
        if (typeof c === 'string') return c;
        return foxJudgeExtractText(c.message)
          || foxJudgeExtractText(c.delta)
          || (typeof c.text === 'string' ? c.text : '')
          || foxJudgeExtractText(c.content);
      }).filter(Boolean);
      if (parts.length) return parts.join('\n');
    }

    // 常见单字段
    const directKeys = ['content', 'text', 'message', 'output', 'output_text', 'response', 'data', 'result'];
    for (const k of directKeys) {
      if (r[k] != null) {
        const t = foxJudgeExtractText(r[k]);
        if (t && t.trim()) return t;
      }
    }

    // Anthropic content blocks: [{ type:'text', text:'...' }]
    if (Array.isArray(r.content)) {
      const t = r.content.map(b => {
        if (!b) return '';
        if (typeof b === 'string') return b;
        return (typeof b.text === 'string' ? b.text : '') || foxJudgeExtractText(b.content);
      }).filter(Boolean).join('\n');
      if (t.trim()) return t;
    }

    // 推理模型兜底：reasoning_content / thinking（避免 content 为空但思考非空时被判空）
    const reasoningKeys = ['reasoning_content', 'reasoning', 'thinking', 'thought'];
    for (const k of reasoningKeys) {
      if (typeof r[k] === 'string' && r[k].trim()) return r[k];
    }

    return '';
  }

  // 截断检测：思维链返回内容是否被截断/不完整
  // - 只用来识别"真·空回复 / 几乎完全没输出"的情况
  // - 默认 minLength=50：模型正常思考即使简短也会远超 50 字符；
  //   之前 300 的阈值过严，会把"模型实际有正常输出"的简短回复误判为空回复并疯狂重试。
  function foxJudgeIsEmptyOrError(result, minLength = 50) {
    // ✅ 只检测字数：空 / 非字符串 / 长度不够都视为需要重试，不再匹配任何文字内容。
    //    避免模型正常输出（含"抱歉/cannot/error"等词或恰好命中拒答正则）被误判重试。
    if (!result || typeof result !== 'string') return true;
    const trimmed = result.trim();
    if (!trimmed) return true;
    if (trimmed.length < minLength) return true;
    return false;
  }

  // ✅ 结构完整性检测改为字数化：长度达标即合格，不再检查具体板块标题，
  //    防止模型正常输出但板块名换了写法时被误判残缺触发重试。
  function foxJudgePhase1IsStructureOk(text) {
    if (!text || typeof text !== 'string') return false;
    return text.trim().length >= 50;
  }

  function foxJudgePhase2IsStructureOk(text) {
    if (!text || typeof text !== 'string') return false;
    return text.trim().length >= 50;
  }

  async function foxJudgeRunPhase1WithRetry(cfg, contextText, maxRetries = 3) {
    // 🔄 重试总开关关闭时：只跑一次，不检测空回/报错，直接返回结果（报错照常上抛）。
    if (!cfg?.retryEnabled) {
      const raw = await foxJudgeRunPhase1(cfg, contextText);
      // 🦊 在拼接前清洗 AI 原始输出里的 <think_fox~> / </think_fox~> 杂散标签，
      //    避免 AI 在被要求纯思考时仍然吐出标签，把后续拼接逻辑卡掉。
      //    注意：只清这两个标签本身，绝不清拼接阶段最终包裹的 <think_fox~>...</think_fox~>。
      return foxJudgeStripStrayThinkTags(raw);
    }
    // 只要识别"真·空回复"即可，正常思考即使简短也会远超 50 字符，避免误伤
    const MIN_LEN = 50;
    let lastError = null;
    for (let attempt = 0; attempt < maxRetries + 1; attempt++) {
      try {
        const raw = await foxJudgeRunPhase1(cfg, contextText);
        // 🦊 关键：先清洗 AI 原始输出的杂散 <think_fox~> 标签，再做"空回复/字数不足"判断，
        //    这样能避免"AI 整段思考被 <think_fox~></think_fox~> 包裹、清洗后变空"被误判为合格。
        const result = foxJudgeStripStrayThinkTags(raw);
        // 只检测字数：达标即合格，不再匹配文字内容/板块标题
        const emptyOrErr = foxJudgeIsEmptyOrError(result, MIN_LEN);
        if (!emptyOrErr) return result;
        if (attempt < maxRetries) {
          const trimmedLen = result?.trim()?.length || 0;
          const reason = trimmedLen === 0 ? '空回复'
            : `字数不足（仅 ${trimmedLen} 字符，要求 ≥ ${MIN_LEN}）`;
          log(`[狐裁] 第一阶段${reason}，第 ${attempt + 1} 次重试……`);
          ssTaskToast('fox_judge_chain', `🦊 狐裁：第一阶段${reason}，重试 ${attempt + 1}/${maxRetries}…`);
          await new Promise(r => setTimeout(r, 1000));
        }
        lastError = new Error('第一阶段返回空或字数不足');
      } catch (e) {
        lastError = e;
        if (attempt < maxRetries && !/abort|aborted|cancel|中断|取消/i.test(e?.message || '')) {
          log(`[狐裁] 第一阶段失败，第 ${attempt + 1} 次重试……`, e);
          ssTaskToast('fox_judge_chain', `🦊 狐裁：第一阶段报错，重试 ${attempt + 1}/${maxRetries}…`);
          await new Promise(r => setTimeout(r, 1500));
        } else {
          throw e;
        }
      }
    }
    throw lastError || new Error('第一阶段重试用尽仍为空');
  }

  async function foxJudgeRunPhase2WithRetry(cfg, phase1Result, userInput, contextText, maxRetries = 3) {
    // 🔄 重试总开关关闭时：只跑一次，不检测空回/报错，直接返回结果（报错照常上抛）。
    if (!cfg?.retryEnabled) {
      const raw = await foxJudgeRunPhase2(cfg, phase1Result, userInput, contextText);
      // 🦊 同 phase1：拼接前先清掉 AI 原始输出里的 <think_fox~> 杂散标签。
      return foxJudgeStripStrayThinkTags(raw);
    }
    // 只要识别"真·空回复"即可，正常思考即使简短也会远超 50 字符，避免误伤
    const MIN_LEN = 50;
    let lastError = null;
    for (let attempt = 0; attempt < maxRetries + 1; attempt++) {
      try {
        const raw = await foxJudgeRunPhase2(cfg, phase1Result, userInput, contextText);
        // 🦊 同 phase1：先洗杂散标签再做空回判断，避免被误判为合格。
        const result = foxJudgeStripStrayThinkTags(raw);
        // 只检测字数：达标即合格，不再匹配文字内容/板块标题
        const emptyOrErr = foxJudgeIsEmptyOrError(result, MIN_LEN);
        if (!emptyOrErr) return result;
        if (attempt < maxRetries) {
          const trimmedLen = result?.trim()?.length || 0;
          const reason = trimmedLen === 0 ? '空回复'
            : `字数不足（仅 ${trimmedLen} 字符，要求 ≥ ${MIN_LEN}）`;
          log(`[狐裁] 第二阶段${reason}，第 ${attempt + 1} 次重试……`);
          ssTaskToast('fox_judge_chain', `🦊 狐裁：第二阶段${reason}，重试 ${attempt + 1}/${maxRetries}…`);
          await new Promise(r => setTimeout(r, 1000));
        }
        lastError = new Error('第二阶段返回空或字数不足');
      } catch (e) {
        lastError = e;
        if (attempt < maxRetries && !/abort|aborted|cancel|中断|取消/i.test(e?.message || '')) {
          log(`[狐裁] 第二阶段失败，第 ${attempt + 1} 次重试……`, e);
          ssTaskToast('fox_judge_chain', `🦊 狐裁：第二阶段报错，重试 ${attempt + 1}/${maxRetries}…`);
          await new Promise(r => setTimeout(r, 1500));
        } else {
          throw e;
        }
      }
    }
    throw lastError || new Error('第二阶段重试用尽仍为空');
  }

  async function foxJudgeRunPhase1(cfg, contextText) {
    const ordered = [
      {
        role: 'system',
        content: `
        你是一位思考大师，你负责读取下面的要求和完整上下文内容，按要求进行一次全面的思考，你不负责正文撰写，禁止输出任何正文续写内容，不要被正文续写要求所迷惑，你只负责思考。
        以下内容是完整上下文、设定、世界书与用户偏好。

要求：
- 你必须把这些内容视为本次固定规则确认的完整上下文。
- 如果上下文中存在设定、世界观、角色信息、玩家角色信息、历史剧情，请全部纳入判断。
- 禁止只根据最新用户消息确认规则。
- 禁止忽略用户偏好。
- 禁止忽略要求。
- 禁止输出正文。

【上下文开始】
${contextText}
【上下文结束】
接下来是思考强度要求：`,
      },
      {
        role: 'system',
        content: `${FOX_JUDGE_STRENGTH_PROMPTS[cfg.strength] || FOX_JUDGE_STRENGTH_PROMPTS.default}

${cfg.phase1Prompt || FOX_JUDGE_PHASE1_PROMPT}
${FOX_JUDGE_FORCE_CONTENT_DIRECTIVE}`,
      },
    ];

    const params = {
      user_input: FOX_JUDGE_FORCE_USER_INPUT,
      should_silence: true,
      should_stream: false,
      max_chat_history: 0,
      ordered_prompts: [...ordered, 'user_input'],
    };
    const customApi = foxJudgeBuildCustomApiParams(cfg);
    if (customApi) params.custom_api = customApi;
    const __extra = foxJudgeBuildExtraInject(cfg);
    if (__extra) params.__ssExtraInject = __extra;
    // 🦊 狐裁一阶段思考跳过脚本侧破限注入：预设里已自带破限条目，无需脚本重复推送。
    params.__ssSkipJailbreak = true;
    // ✅ 修复中断 BUG：通过 ssGenerateRaw 复用 fox_judge_chain 任务的 generationId，
    //    让 ssCancelTask -> stopGenerationById 能真正中断本阶段的生成
    const r = await ssGenerateRaw('fox_judge_chain', params, '狐裁第一阶段');
    // 中断时 ssCancelTask 会让 gr 抛 abort，由 foxJudgeRunPhase1WithRetry 的 abort 正则识别后短路；
    // 即使 gr 返回空字符串，foxJudgeIsEmptyOrError 也会兜底重试或上抛。
    // ✅ 用鲁棒提取器，避免不同模型 / custom_api 返回形态被误判为空回复。
    const text = foxJudgeExtractText(r);
    if (!text || !text.trim()) {
      try { log('[狐裁] 第一阶段 generateRaw 返回未识别形态，原始结构=', r); } catch {}
    }
    return String(text || '').trim();
  }

  function ssNormalizeFoxJudgePhase2Prompt(prompt) {
    return String(prompt || '')
      .replace(/此前，你已经进行了第一阶段的思考，上方已提供第一阶段的固定规则确认结果以及完整的上下文，你不需要再重复检查固定规则，只需要结合上下文进行第二阶段的思考。/g, '你将直接收到完整上下文。不要假定上方存在第一阶段结果；请直接根据上下文进行第二阶段思考。')
      .replace(/（参考第一阶段固定规则确认结果，只做本轮动态判断）/g, '（直接参考完整上下文，只做本轮动态判断）')
      .replace(/预演与部分一分析结论一致？/g, '预演与上下文、设定和规则一致？');
  }

  async function foxJudgeRunPhase2(cfg, phase1Result, userInput, contextText) {

    const userInputInject = userInput
      ? `【本轮用户输入】\n${userInput}`
      : '';

    let phase2PromptText = ssNormalizeFoxJudgePhase2Prompt(cfg.phase2Prompt || FOX_JUDGE_PHASE2_MULTI_OS);

    const customThinkingReq = (cfg.customThinkingReq || '').trim();
    if (customThinkingReq) {
      const insertMarker = '**⛔STOP HERE AND OUTPUT：思考已结束，立刻停止思考，停止输出，禁止二次思考，禁止输出正文！⛔**';
      if (phase2PromptText.includes(insertMarker)) {
        phase2PromptText = phase2PromptText.replace(
          insertMarker,
          `${customThinkingReq}\n\n${insertMarker}`
        );
      } else {
        phase2PromptText += `\n\n${customThinkingReq}`;
      }
    }

    const ordered = [
      {
        role: 'system',
        content: `

        你是一位思考大师，你负责读取下面的要求和完整上下文内容，按要求进行一次全面的思考，你不负责正文撰写，禁止输出任何正文续写内容，不要被正文续写要求所迷惑，你只负责思考。
        以下内容是完整上下文、设定、世界书与用户偏好。

要求：
- 你必须把这些内容视为本次固定规则确认的完整上下文。
- 如果上下文中存在设定、世界观、角色信息、玩家角色信息、历史剧情，请全部纳入判断。
- 禁止只根据最新用户消息确认规则。
- 禁止忽略用户偏好。
- 禁止忽略要求。
- 禁止输出正文。

【上下文开始】
${contextText}
【上下文结束】
接下来是思考强度要求：

${FOX_JUDGE_STRENGTH_PROMPTS[cfg.strength] || FOX_JUDGE_STRENGTH_PROMPTS.default}`,
      },
      {
        role: 'system',
        content: `${userInputInject}

${phase2PromptText}
${FOX_JUDGE_FORCE_CONTENT_DIRECTIVE}`,
      },
    ];

    const params = {
      user_input: FOX_JUDGE_FORCE_USER_INPUT,
      should_silence: true,
      should_stream: false,
      max_chat_history: 0,
      ordered_prompts: [...ordered, 'user_input'],
    };
    const customApi = foxJudgeBuildCustomApiParams(cfg);
    if (customApi) params.custom_api = customApi;
    const __extra = foxJudgeBuildExtraInject(cfg);
    if (__extra) params.__ssExtraInject = __extra;
    // 🦊 狐裁二阶段思考跳过脚本侧破限注入：预设里已自带破限条目，无需脚本重复推送。
    params.__ssSkipJailbreak = true;
    // ✅ 修复中断 BUG：通过 ssGenerateRaw 复用 fox_judge_chain 任务的 generationId，
    //    让 ssCancelTask -> stopGenerationById 能真正中断本阶段的生成
    const r = await ssGenerateRaw('fox_judge_chain', params, '狐裁第二阶段');
    // 中断时 ssCancelTask 会让 gr 抛 abort，由 foxJudgeRunPhase2WithRetry 的 abort 正则识别后短路；
    // 即使 gr 返回空字符串，foxJudgeIsEmptyOrError 也会兜底重试或上抛。
    // ✅ 用鲁棒提取器，避免不同模型 / custom_api 返回形态（OpenAI choices / Anthropic content blocks /
    //    推理模型 reasoning_content 等）被错判为"空回复"。
    const text = foxJudgeExtractText(r);
    if (!text || !text.trim()) {
      try { log('[狐裁] 第二阶段 generateRaw 返回未识别形态，原始结构=', r); } catch {}
    }
    return String(text || '').trim();
  }

  function foxJudgeBuildDynamicContext(userInput, lastAssistantText) {
    const lines = [];
    if (userInput) lines.push(`【本轮用户输入】\n${userInput}`);
    if (lastAssistantText) lines.push(`【最新 AI 回复｜参考】\n${lastAssistantText}`);
    lines.push('请基于以上内容进行第二阶段思考。');
    return lines.join('\n\n');
  }

  function foxJudgeStripThinkBlock(text) {
    return String(text || '').replace(/<think_fox~>[\s\S]*?<\/think_fox~>/g, '').trim();
  }

  // ✅ 安全清理：仅移除模型违规输出的杂散 <think_fox~> / </think_fox~> 标签本身，
  //    绝不按位置截断后续内容。
  //    用于单独的 phase1 / phase2 思考文本（纯思考，不含真正的标签语义）。
  //    之前 phase1/phase2 误用 foxJudgeCleanLeakageAfterThinkClose，
  //    一旦模型在思考开头/中部漏写一个 </think_fox~>（提示词禁止但模型常违反），
  //    lastIndexOf 截断会把该标签之后的真实思考内容全部删掉 → 第二阶段被拼成空气。
  //
  // 🦊 同时清理 ``` 代码围栏：部分模型（尤其 Claude / DeepSeek 思考模型）会把思考用
  //    ```think / ```markdown / ``` 之类的代码块包起来输出，拼接到最终 <think_fox~>...</think_fox~>
  //    里之后，```会被酒馆 markdown 渲染识别成代码块起止，导致后续整段正文 / 选项 / 状态栏
  //    被一并渲染成 monospace 黑框 = "格式完全爆炸"。
  //    清理范围：成对/未成对的 ``` 围栏全部去掉，但仅作用于一/二阶段思考原文（拼接前），
  //    不影响外层 <think_fox~>...</think_fox~> 的合法标签。
  function foxJudgeStripStrayThinkTags(text) {
    let s = String(text || '');
    // 1) 清掉 think_fox~ 杂散标签（成对/未成对都清）
    s = s.replace(/<\/?think_fox~>/g, '');
    // 2) 清掉所有 ``` 代码围栏（包括 ```lang 起始行）。
    //    - ```lang 这类带语言标识的起始行：```python / ```think / ```markdown 等 → 整行连同换行一起去掉
    //    - 纯 ``` 行 / 行内 ``` → 直接删除三个反引号
    //    注意：不动单反引号 ` 与双反引号 ``，避免破坏正常文字。
    s = s.replace(/```[a-zA-Z0-9_-]*\s*\n?/g, '');
    s = s.replace(/```/g, '');
    return s.trim();
  }

  // ⚠️ 破坏性：lastIndexOf 之后全部截断。
  //    只可用于"已经成型的、最终要注入楼层的、外层带 <think_fox~>...</think_fox~> 的完整块"，
  //    用来切掉闭合标签之后泄漏的正文。禁止用于单独的 phase1/phase2 思考文本！
  function foxJudgeCleanLeakageAfterThinkClose(text) {
    let s = String(text || '');
    const closeIdx = s.lastIndexOf('</think_fox~>');
    if (closeIdx >= 0) {
      s = s.substring(0, closeIdx + '</think_fox~>'.length);
    }
    return s.trim();
  }

  // ✅ 仅第一阶段注入拼接 + 写入内存缓存。
  //    被两处共用：1) cfg.phase1Only 快速模式； 2) 第二阶段重试用尽时的兜底分支。
  //    抽出来避免两边模板/赋值漂移（之前曾因复制粘贴导致两份逻辑不同步的风险）。
  function foxJudgeBuildPhase1OnlyInjection(phase1Result) {
    // ✅ 先去掉成对的 think 块（若模型把自己包了一层），再去掉杂散标签本身；
    //    绝不对单段思考做 lastIndexOf 截断，避免吞掉真实内容。
    let cleanPhase1 = foxJudgeStripThinkBlock(phase1Result || '');
    cleanPhase1 = foxJudgeStripStrayThinkTags(cleanPhase1);
    const combined = `<think_fox~>
${cleanPhase1}
思考完毕，立刻按要求开始输出正文
</think_fox~>`;
    const cleaned = foxJudgeCleanLeakageAfterThinkClose(combined);
    foxJudgeLastCombined = cleaned;
    foxJudgePendingInject = cleaned;
    foxJudgePreservedChain = cleaned;
    foxJudgeInjectVersion++;
    return combined;
  }

  function foxJudgeStripXmlTags(text) {
    const PH_OPEN = '\x00THINK_FOX_OPEN\x00';
    const PH_CLOSE = '\x00THINK_FOX_CLOSE\x00';
    // 🦊 标签清洗：
    //   旧版正则 <\/?[a-zA-Z_][a-zA-Z0-9_\-]*[^>]*>
    //   只匹配 ASCII 标签名，导致中文标签（例如 <平行世界> / <狐忆> / <人物档案>）
    //   一路漏出来，注入到主模型输出后，被酒馆当成未识别 HTML 渲染，格式爆炸。
    //   现在改成 <\/?[^<>\r\n]*> ：匹配任何 < 开头、> 结尾、且中间不再嵌套 < / > / 换行 的标签，
    //   无视标签名是中文 / 英文 / 数字 / 符号，全部清掉。
    //   排除换行的目的：避免 AI 把 < / > 当数学比较符号、且裸 < 与远处 > 跨行时被整段误吞。
    //   <think_fox~> / </think_fox~> 在清洗前已被占位符替换出去，不会被误删，
    //   清洗后再换回真实标签，所以思维链外层标签完整保留。
    return String(text || '')
      .replace(/<think_fox~>/g, PH_OPEN)
      .replace(/<\/think_fox~>/g, PH_CLOSE)
      .replace(/<\/?[^<>\r\n]*>/g, '')
      .replace(new RegExp(PH_OPEN.replace(/\x00/g, '\\x00'), 'g'), '<think_fox~>')
      .replace(new RegExp(PH_CLOSE.replace(/\x00/g, '\\x00'), 'g'), '</think_fox~>')
      .trim();
  }

  async function foxJudgeInjectIntoMainOutput(targetMessageId) {
    try {
      const rawCombined = foxJudgeLastCombined || foxJudgePendingInject;
      if (!rawCombined) return;

      const combined = foxJudgeStripXmlTags(rawCombined);
      const cleanedCombined = foxJudgeCleanLeakageAfterThinkClose(combined);

      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');
      const scm = getFn('setChatMessages');
      if (!glmi || !gcm || !scm) return;

      const lastId = targetMessageId != null ? targetMessageId : glmi();
      if (lastId < 0) return;

      const cm = gcm(lastId, { include_swipes: true })?.[0];
      if (!cm || cm.role !== 'assistant') return;

      const cid = cm.swipe_id ?? 0;
      const original = String(cm.swipes?.[cid] || '');

      if (original.includes('<think_fox~>')) return;

      const cleaned = foxJudgeStripThinkBlock(original);
      const cleanedOrig = foxJudgeCleanLeakageAfterThinkClose(cleaned);
      const newContent = `${cleanedCombined}\n\n${cleanedOrig}`;

      const nsa = [...(cm.swipes || [])];
      nsa[cid] = newContent;
      await scm([{ message_id: lastId, swipe_id: cid, swipes: nsa }], { refresh: 'affected' });
      log('[狐裁] 思维链已注入到主模型输出楼层顶部');
    } catch (e) {
      log('[狐裁] 注入主模型输出失败', e);
    }
  }

  let foxJudgeLastCombined = '';
  let foxJudgePendingInject = '';
  // 🦊 保留上一次完整思维链（含 phase1+phase2）。与 foxJudgeLastCombined 不同的是：
  //   - foxJudgeLastCombined / foxJudgePendingInject 是"本轮主请求待注入"的一次性缓存，
  //     MESSAGE_RECEIVED 600ms 后会被清空，避免被下一个主请求误注入。
  //   - foxJudgePreservedChain 不参与"本轮注入"，仅在用户**关闭** swipe/reroll 重新思考时，
  //     由 reroll/swipe 拦截器读取它，原样塞回 foxJudgeLastCombined + foxJudgePendingInject
  //     供本次新的主请求使用——语义即"不重跑第二阶段，沿用上一次完整思维链"。
  //   - 只有 CHAT_CHANGED / 用户主动关闭狐裁开关 / 清空全部缓存按钮 时才清空。
  let foxJudgePreservedChain = '';
  // 🦊 注入版本号：每完成一次两阶段思考就 +1。
  //    用于解决 MESSAGE_RECEIVED 600ms 延迟清理 vs 新一轮思维链已就位的竞态——
  //    旧的 MESSAGE_RECEIVED 清理只能清掉自己那一版的缓存，绝不会误清掉新一版。
  let foxJudgeInjectVersion = 0;
  // 🦊 标记“本次主请求是否已成功把思维链注入到请求体最下方”。
  //    供 toast 防抖：同一次主请求只弹一次“已注入”提示，避免
  //    GENERATE_AFTER_COMBINE_PROMPTS 与 CHAT_COMPLETION_PROMPT_READY 双触发各弹一次。
  let foxJudgeInjectedToastVersion = 0;

  async function foxJudgeRunChain({ userInput, lastAssistantText, forceRefresh = false, phase2Only = false } = {}) {
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return { combined: '', phase1: '', phase2: '', skipped: 'disabled' };

    // ✅ 重入保护：上一次还在跑就拒绝本次（不强制取消上一次）
    //    上层（foxPushInterceptAndPolish / foxJudgeInterceptAndThink / foxJudgeHandleRerollSwipe）
    //    都已经做了"自身正在思考"的拦截，正常路径下不会有重复调用进来。
    //    这里只做兜底，避免之前"取消上一次又立刻返回 cancelled、上层却继续 fire 主请求"
    //    导致正文一边出、思维链一边在跑的循环。
    if (ssIsTaskRunning('fox_judge_chain')) {
      log('[狐裁] 检测到上一次思维链仍在进行，拒绝本次重入');
      return { combined: '', phase1: '', phase2: '', skipped: 'busy' };
    }

    // ✅ phase2Only 与 phase1Only 互斥：调用方要"重跑第二阶段"，但配置是"仅第一阶段"，
    //    直接放弃本次思考（外层调用点本就有 cfg.phase1Only return 的前置守卫，这里是兜底）
    if (phase2Only && cfg.phase1Only) {
      log('[狐裁] phase2Only 与 phase1Only 互斥，本次跳过狐裁思考');
      return { combined: '', phase1: '', phase2: '', skipped: 'phase1_only_conflict' };
    }

    const charId = getCurrentCharId();
    let phase1Result;
    let phase1FromCache = false;

    ssStartTask('fox_judge_chain', '狐裁思维链');

    try {
      const filterSettings = cfg.filterSettings || FOX_JUDGE_DEFAULT_FILTER_SETTINGS;
      // 🦊 关键修复（双重计费根因）：为了抓酒馆按 in_use 预设组合好的完整 prompt（含预设/世界书/
      //    破限/狐析等所有条目），仍走 ssCaptureMainRequestMessages（事件抓取）。但内部发起的
      //    静默 generate 会被 fetch hook 在请求真正发往上游之前短路（看 ssDryRunCaptureTokens），
      //    所以**不会真的命中主模型 = 不会产生额外计费**。
      //    上下文与"狐裁第二阶段"完全等价：预设条目、世界书、破限、狐析、角色卡、楼层全有。
      const contextText = await ssBuildFilteredMainContextText('狐裁', filterSettings, { skipRoleLabels: true });

      // Phase 1：phase2Only 模式直接走缓存（必须有缓存才能用，否则跑一次 Phase1）
      if (phase2Only) {
        // ✅ phase2Only 含义就是"复用已有 phase1"，因此读缓存不再受 cacheEnabled 限制：
        //    即使用户关闭了缓存写入，只要存在已保存的非空 phase1_result（例如来自快速模式
        //    或用户手动粘贴保存），就用它；这样能避免无意义地重跑 phase1 并保留用户编辑。
        try { foxJudgeCheckAndInvalidateIfChanged(); } catch {}
        const staticCache = foxJudgeGetStaticCache(charId);
        if (staticCache && (cfg.phase1Fixed || !staticCache.stale) && typeof staticCache.phase1_result === 'string' && staticCache.phase1_result.trim()) {
          phase1Result = staticCache.phase1_result;
          phase1FromCache = true;
          log('[狐裁] phase2Only：命中缓存，跳过第一阶段');
        }
        if (!phase1Result) {
          // 没缓存也只跑一次 Phase1（不强制刷新），跑完缓存起来
          ssTaskToast('fox_judge_chain', '🦊 狐裁：phase2Only 但无缓存，先补跑第一阶段……');
          phase1Result = await foxJudgeRunPhase1WithRetry(cfg, contextText, cfg.maxRetries);
          // ✅ 写入缓存：即使 cfg.cacheEnabled=false 也写入，因为本次是 phase2Only 显式语义，
          //    用户既然走 phase2Only 就一定会复用 phase1，不写缓存等同于每次都重跑。
          if (phase1Result) {
            foxJudgeSaveStaticCache(charId, {
              version: 2,
              char_id: charId,
              phase1_result: phase1Result,
              strength: cfg.strength,
              created_at: new Date().toISOString(),
            });
          }
        }
      } else {
        // 正常模式：优先检查缓存
        if ((cfg.cacheEnabled || cfg.phase1Fixed) && !forceRefresh) {
          foxJudgeCheckAndInvalidateIfChanged();
          const staticCache = foxJudgeGetStaticCache(charId);
          // ✅ 命中条件：phase1_result 必须是非空字符串、且不是 stale。
          //    避免之前若 cache 存了空字符串（例如保存编辑时被清空）也算"命中缓存"
          //    导致主流程拿到空 phase1 直接进二阶段（外观上"无视第一段"）。
          if (staticCache && (cfg.phase1Fixed || !staticCache.stale) && typeof staticCache.phase1_result === 'string' && staticCache.phase1_result.trim()) {
            phase1Result = staticCache.phase1_result;
            phase1FromCache = true;
            log('[狐裁] 命中缓存，跳过第一阶段');
          }
        }

        if (!phase1Result) {
          ssTaskToast('fox_judge_chain', '🦊 狐裁：正在思考第一阶段……');

          phase1Result = await foxJudgeRunPhase1WithRetry(cfg, contextText, cfg.maxRetries);

          if (phase1Result && (cfg.cacheEnabled || cfg.phase1Fixed)) {
            foxJudgeSaveStaticCache(charId, {
              version: 2,
              char_id: charId,
              phase1_result: phase1Result,
              strength: cfg.strength,
              created_at: new Date().toISOString(),
            });
            log('[狐裁] 第一阶段完成，已缓存');
          } else {
            log('[狐裁] 第一阶段完成（未缓存，缓存已关闭）');
          }
        }
      }

      // phase1Only：仅在非 phase2Only 模式下生效；phase2Only 不允许走 phase1Only 短路
      if (cfg.phase1Only && !phase2Only) {
        const combined = foxJudgeBuildPhase1OnlyInjection(phase1Result);
        log('[狐裁] 仅第一阶段模式：跳过第二阶段，Phase1来自缓存=', phase1FromCache);

        toast('🦊 狐裁思维链完成（仅第一阶段）', 'success');

        return { combined, phase1: phase1Result, phase2: '', skipped: 'phase1_only' };
      }

      ssTaskToast('fox_judge_chain', '🦊 狐裁：正在思考第二阶段……');

      // ✅ 第二阶段失败兜底：如果第二阶段重试用尽仍失败，但第一阶段已正常输出，
      //    则降级为仅第一阶段注入（等同于快速模式），不要直接放过让主模型在没有思维链下出正文。
      let phase2Result = '';
      let phase2Failed = false;
      let phase2FailMsg = '';
      try {
        phase2Result = await foxJudgeRunPhase2WithRetry(cfg, phase1Result, userInput, contextText, cfg.maxRetries);
      } catch (phase2Err) {
        const m2 = phase2Err?.message || String(phase2Err || '');
        // 中断 / 取消 直接上抛由外层 catch 处理（不要静默吞掉）
        if (/abort|aborted|cancel|中断|取消/i.test(m2)) throw phase2Err;
        phase2Failed = true;
        phase2FailMsg = m2;
        log('[狐裁] 第二阶段重试用尽，触发兜底：仅注入第一阶段（等同快速模式）。错误=', phase2Err);
      }

      if (phase2Failed) {
        // 兜底分支：与 phase1Only 一致的拼接 + 注入逻辑（共用 foxJudgeBuildPhase1OnlyInjection）
        if (!phase1Result || !String(phase1Result).trim()) {
          // 第一阶段也没有内容（理论上前面已重试过），直接报错让外层处理
          throw new Error(`第二阶段失败且第一阶段无内容：${phase2FailMsg || '未知原因'}`);
        }
        const combined = foxJudgeBuildPhase1OnlyInjection(phase1Result);
        log('[狐裁] 兜底完成：仅注入第一阶段（length=', combined.length, '），Phase1来自缓存=', phase1FromCache);

        toast('⚠️ 狐裁：第二阶段失败，已兜底仅注入第一阶段', 'warning');

        return { combined, phase1: phase1Result, phase2: '', skipped: 'phase2_failed_fallback_phase1' };
      }

      let cleanPhase1 = foxJudgeStripThinkBlock(phase1Result || '');
      let cleanPhase2 = foxJudgeStripThinkBlock(phase2Result || '');
      cleanPhase1 = foxJudgeStripStrayThinkTags(cleanPhase1);
      cleanPhase2 = foxJudgeStripStrayThinkTags(cleanPhase2);
      const combined = `<think_fox~>
${cleanPhase1}
[OS]
${cleanPhase2}
思考完毕，立刻按要求开始输出正文
</think_fox~>`;

      foxJudgeLastCombined = foxJudgeCleanLeakageAfterThinkClose(combined);
      foxJudgePendingInject = foxJudgeCleanLeakageAfterThinkClose(combined);
      foxJudgePreservedChain = foxJudgeCleanLeakageAfterThinkClose(combined);
      foxJudgeInjectVersion++;
      log('[狐裁] 两阶段思考完成，length=', combined.length, 'Phase1来自缓存=', phase1FromCache, '等待主模型输出后注入楼层', 'version=', foxJudgeInjectVersion);

      toast('🦊 狐裁思维链完成', 'success');

      return { combined, phase1: phase1Result, phase2: phase2Result, skipped: null };
    } catch (e) {
      const msg = e?.message || String(e || '');
      if (/abort|aborted|cancel|中断|取消/i.test(msg)) {
        toast('⛔ 狐裁已中断', 'warning');
        return { combined: '', phase1: '', phase2: '', skipped: 'cancelled' };
      }
      log('[狐裁] 思维链失败', e);
      toast(`❌ 狐裁失败：${msg}`, 'error');
      return { combined: '', phase1: '', phase2: '', skipped: 'error' };
    } finally {
      ssClearTaskToast('fox_judge_chain');
      ssEndTask('fox_judge_chain');
    }
  }

  let foxJudgeOutputInjectHandles = [];

  function foxJudgeRegisterOutputInjectListener() {
    foxJudgeUnregisterOutputInjectListener();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;
    if (typeof eo !== 'function') return;

    if (te?.MESSAGE_RECEIVED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.MESSAGE_RECEIVED, async (messageId, type) => {
          const cfg = foxJudgeReadConfig();
          if (!cfg.enabled) return;
          if (!foxJudgePendingInject && !foxJudgeLastCombined) return;

          // 🦊 关键：抓取“当前这条 MESSAGE_RECEIVED 关心的”那一版思维链快照。
          //    600ms 之后再清缓存时，必须只清这一版——如果用户在等待期间又跑了
          //    新一轮 swipe/reroll 思考，导致 foxJudgeInjectVersion 已经 +1，
          //    那这条旧 MESSAGE_RECEIVED 就不再清空全局缓存，避免“新思维链被旧
          //    监听器误清空 → 下一次主请求注入失败”这个时好时坏的根因。
          const myVersion = foxJudgeInjectVersion;
          const mySnapshot = foxJudgeLastCombined || foxJudgePendingInject;

          await new Promise(r => setTimeout(r, 600));

          await foxJudgeInjectIntoMainOutput(messageId);

          if (foxJudgeInjectVersion !== myVersion) {
            log('[狐裁] MESSAGE_RECEIVED：检测到新一轮思维链已就位（v', myVersion, '→', foxJudgeInjectVersion, '），跳过清空，保护新缓存');
            return;
          }
          // 仅当全局缓存仍是“我关心的那一版”时才清空，避免误清。
          if (foxJudgeLastCombined === mySnapshot || foxJudgePendingInject === mySnapshot) {
            foxJudgePendingInject = '';
            foxJudgeLastCombined = '';
            log('[狐裁] MESSAGE_RECEIVED：思维链已注入到主模型输出楼层顶部，缓存已清空 v=', myVersion);
          } else {
            log('[狐裁] MESSAGE_RECEIVED：缓存内容已被替换，跳过清空');
          }
        })
      );
    }

    if (te?.MESSAGE_DELETED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.MESSAGE_DELETED, async (messageId) => {
          const cfg = foxJudgeReadConfig();
          if (!cfg.enabled) return;

          try {
            const glmi = getFn('getLastMessageId');
            const gcm = getFn('getChatMessages');
            if (glmi && gcm) {
              const lastId = glmi();
              if (lastId >= 0) {
                const cm = gcm(lastId, { include_swipes: true })?.[0];
                if (cm && cm.role === 'assistant') {
                  const text = String(cm.message || '');
                  if (text.includes('<think_fox~>')) {
                    foxJudgeLastCombined = '';
                    foxJudgePendingInject = '';
                    log('[狐裁] MESSAGE_DELETED：检测到含思维链楼层，已同步清理内存缓存');
                  }
                }
              }
            }
          } catch (e) {
            log('[狐裁] MESSAGE_DELETED 同步清理失败', e);
          }
        })
      );
    }

    if (te?.GENERATION_ENDED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.GENERATION_ENDED, () => {
          try { foxJudgeRegisterSwipeRerollListeners(); } catch { }
          // ✅ 修复：发送按钮 / Enter 监听也可能因为 DOM 被酒馆重建而丢失
          //         导致用户点发送或按 Enter 时狐裁完全不触发。
          //         这里跟 swipe/reroll 一起重新注册，保证监听始终在 DOM 上。
          try { registerFoxJudgeInterceptListener(); } catch { }
        })
      );
    }

    // ✅ 切换聊天/角色卡时酒馆也会重建输入区域 DOM，需要重新挂载拦截器
    // 注：狐裁思维链缓存 / 拦截锁的清空统一在 husouRegisterListeners 的 CHAT_CHANGED 中枢处理，
    //     那里始终注册，能覆盖狐裁监听未激活的情况。
    if (te?.CHAT_CHANGED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.CHAT_CHANGED, () => {
          try { foxJudgeRegisterSwipeRerollListeners(); } catch { }
          try { registerFoxJudgeInterceptListener(); } catch { }
        })
      );
    }
  }

  function foxJudgeUnregisterOutputInjectListener() {
    for (const h of foxJudgeOutputInjectHandles) {
      try { if (typeof h?.stop === 'function') h.stop(); } catch { }
    }
    foxJudgeOutputInjectHandles = [];
  }

  let foxJudgeRethinkPending = false;
  let foxJudgeRerollBtnHandle = null;
  let foxJudgeSwipeBtnHandle = null;
  let foxJudgeSkipNextReroll = false;
  let foxJudgeSkipNextSwipe = false;

  async function foxJudgeHandleRerollSwipe(source) {
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return;
    if (foxJudgeRethinkPending) {
      toast('⏳ 狐裁思考中，请稍候…', 'info');
      return;
    }

    if (ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || state.hushenIsAnalyzing || pwState?.running) return;

    foxJudgeRethinkPending = true;

    try {
      log(`[狐裁] ${source} 拦截：开始重跑第二阶段`);

      // 注意：理论上前置守卫（`foxJudgeOnRerollClick`/`OnSwipeClick` 在 ssActiveTasks.size > 0 时早返回）
      // 已经过滤掉了"上一次还在跑"的情况，这里走不到。`foxJudgeRunChain` 内部也有重入保护会返回 busy。
      // 之前这里的 ssCancelTask + await 300ms 是兜底防御，但与新版"重入返回 busy"语义冲突，
      // 反而会让上一次跑到一半的思考被中断却不让本次启动，故移除。

      foxJudgeLastCombined = '';
      foxJudgePendingInject = '';

      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');
      let userInput = '';
      let lastAssistantText = '';
      if (glmi && gcm) {
        const lastId = glmi();
        if (lastId >= 0) {
          for (let i = lastId; i >= Math.max(0, lastId - 5); i--) {
            const m = gcm(i, { hide_state: 'all', include_swipes: false })?.[0];
            if (!m) continue;
            if (!userInput && m.role === 'user') {
              userInput = String(m.message || '').trim();
            }
            if (!lastAssistantText && m.role === 'assistant') {
              lastAssistantText = String(m.message || '').trim();
              try { lastAssistantText = ssCleanXuanhuInjectedBlocksFromMessage(lastAssistantText); } catch { }
              lastAssistantText = foxJudgeStripThinkBlock(lastAssistantText);
            }
            if (userInput && lastAssistantText) break;
          }
        }
      }

      const usePhase2Only = (() => {
        // phase1Only 快速模式 → 不存在第二阶段，必须走完整 phase1 流程（forced from foxJudgeRunChain）
        if (cfg.phase1Only) return false;
        // ✅ 修复 BUG：只有当 phase1 缓存确实存在且非空时才走 phase2Only。
        //    避免用户手动清空缓存后 reroll 仍按 phase2Only 走，
        //    内部虽有"phase2Only 但无缓存就补跑 phase1"的兜底，
        //    但 cacheEnabled=false 时该兜底分支条件是 `!phase1Result`，
        //    依然能走，这里再加一层显式判断让流程语义更稳。
        try {
          const charId = getCurrentCharId();
          // 先做一次指纹失效检查，避免读到已失效但残留的 cache
          try { foxJudgeCheckAndInvalidateIfChanged?.(); } catch {}
          const sc = foxJudgeGetStaticCache?.(charId);
          const has = !!(sc && !sc.stale && typeof sc.phase1_result === 'string' && sc.phase1_result.trim());
          if (!has) {
            log('[狐裁] reroll/swipe：缓存不存在或为空，走完整 phase1+phase2 流程');
            return false;
          }
        } catch (e) {
          log('[狐裁] reroll/swipe：检查缓存失败，回退完整流程', e);
          return false;
        }
        return true;
      })();
      const result = await foxJudgeRunChain({ userInput, lastAssistantText, phase2Only: usePhase2Only });
      if (result.combined) {
        foxJudgeLastCombined = result.combined;
        foxJudgePendingInject = result.combined;
        log(`[狐裁] ${source} 重新思考完成，准备释放按钮（phase1Only=${cfg.phase1Only}）`);
      } else if (result.skipped === 'busy') {
        log(`[狐裁] ${source} 上一次思维链仍在进行，本次跳过狐裁注入`);
      }
    } catch (err) {
      log(`[狐裁] ${source} 重新思考失败:`, err);
    } finally {
      foxJudgeRethinkPending = false;
    }
  }

  function foxJudgeOnRerollClick(e) {
    // 🦊 双绑定去重：避免文档级和元素级监听都跑一次。
    // ⚠️ 只在确实进入处理路径时才打标记，no-op 不污染事件对象。
    if (e && e.__foxJudgeRerollHandled) return;
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return;
    if (e) { try { e.__foxJudgeRerollHandled = true; } catch { } }

    if (foxJudgeSkipNextReroll) {
      foxJudgeSkipNextReroll = false;
      return;
    }

    // 🦊 关闭"Reroll 时重新思考"分支：不重跑思维链，直接复用上一次保留的完整思维链
    //    塞回 foxJudgeLastCombined/Pending，然后放行原生 reroll 让主请求按原流程注入。
    //    若没有保留思维链（首次使用 / 切聊天后 / 用户主动清空），则什么都不做，
    //    让 reroll 不带思维链原生跑——这是用户明确的意图："就别再思考了"。
    if (!cfg.rerollRethink) {
      if (foxJudgePreservedChain) {
        foxJudgeLastCombined = foxJudgePreservedChain;
        foxJudgePendingInject = foxJudgePreservedChain;
        foxJudgeInjectVersion++;
        log('[狐裁] Reroll：已沿用上一次完整思维链，跳过重新思考');
      } else {
        log('[狐裁] Reroll：未启用重新思考且无保留思维链，本次裸 reroll');
      }
      return;
    }

    if (foxJudgeRethinkPending) {
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思考中，请稍候…', 'info');
      return;
    }
    // ✅ 关键修复：自己上一轮的 fox_judge_chain 任务还在跑（例如发送/Enter 拦截
    //    触发的思维链还没结束），reroll 不能"让出"——必须挡住，否则 SillyTavern
    //    会在 phase2 还没拼完时就发出 reroll 请求。
    if (ssIsTaskRunning('fox_judge_chain')) {
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思维链未结束，请稍候再 reroll…', 'info');
      return;
    }
    // 其他后台任务在跑：让出 reroll，同时清空旧思维链避免误注入
    if (ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || state.hushenIsAnalyzing || pwState?.running) {
      try {
        const reasons = [];
        if (ssActiveTasks.size > 0) reasons.push(`ssActiveTasks=${[...ssActiveTasks.keys()].join(',')}`);
        if (state.husouIsRunning) reasons.push('husouIsRunning');
        if (state.foxAnalyzing) reasons.push('foxAnalyzing');
        if (state.outlineIsCorrecting) reasons.push('outlineIsCorrecting');
        if (state.outlineIsGenerating) reasons.push('outlineIsGenerating');
        if (state.hushenIsAnalyzing) reasons.push('hushenIsAnalyzing');
        if (pwState?.running) reasons.push('pwState.running');
        log('[狐裁] reroll 拦截被其他后台任务挡住，本次让出原生 reroll：', reasons.join(' | '));
      } catch { }
      foxJudgeLastCombined = '';
      foxJudgePendingInject = '';
      return;
    }

    e.stopImmediatePropagation();
    e.preventDefault();

    foxJudgeHandleRerollSwipe('reroll').then(() => {
      foxJudgeSkipNextReroll = true;
      const btn = topDoc.getElementById('option_regenerate') || topDoc.getElementById('regenerate');
      if (btn) btn.click();
    });
  }

  function foxJudgeOnSwipeClick(e) {
    // 🦊 双绑定去重：避免文档级和元素级监听都跑一次。
    // ⚠️ 只在确实进入处理路径时才打标记，no-op 不污染事件对象。
    if (e && e.__foxJudgeSwipeHandled) return;
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return;
    if (e) { try { e.__foxJudgeSwipeHandled = true; } catch { } }

    if (foxJudgeSkipNextSwipe) {
      foxJudgeSkipNextSwipe = false;
      return;
    }

    // 🦊 关闭"Swipe 时重新思考"分支：不重跑思维链，直接复用上一次保留的完整思维链
    //    塞回 foxJudgeLastCombined/Pending，然后放行原生 swipe 让主请求按原流程注入。
    if (!cfg.swipeRethink) {
      if (foxJudgePreservedChain) {
        foxJudgeLastCombined = foxJudgePreservedChain;
        foxJudgePendingInject = foxJudgePreservedChain;
        foxJudgeInjectVersion++;
        log('[狐裁] Swipe：已沿用上一次完整思维链，跳过重新思考');
      } else {
        log('[狐裁] Swipe：未启用重新思考且无保留思维链，本次裸 swipe');
      }
      return;
    }

    if (foxJudgeRethinkPending) {
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思考中，请稍候…', 'info');
      return;
    }
    // ✅ 关键修复：自己上一轮的 fox_judge_chain 任务还在跑（例如发送/Enter 拦截
    //    触发的思维链还没结束），swipe 不能"让出"——必须挡住，否则 SillyTavern
    //    会在 phase2 还没拼完时就发出 swipe 请求，正文先于思维链跑完出现，
    //    用户表现就是"上面在思考第二阶段，下面已经出正文"。
    if (ssIsTaskRunning('fox_judge_chain')) {
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思维链未结束，请稍候再 swipe…', 'info');
      return;
    }
    // 其他后台任务在跑：让出 swipe，同时清空旧思维链避免误注入
    if (ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || state.hushenIsAnalyzing || pwState?.running) {
      try {
        const reasons = [];
        if (ssActiveTasks.size > 0) reasons.push(`ssActiveTasks=${[...ssActiveTasks.keys()].join(',')}`);
        if (state.husouIsRunning) reasons.push('husouIsRunning');
        if (state.foxAnalyzing) reasons.push('foxAnalyzing');
        if (state.outlineIsCorrecting) reasons.push('outlineIsCorrecting');
        if (state.outlineIsGenerating) reasons.push('outlineIsGenerating');
        if (state.hushenIsAnalyzing) reasons.push('hushenIsAnalyzing');
        if (pwState?.running) reasons.push('pwState.running');
        log('[狐裁] swipe 拦截被其他后台任务挡住，本次让出原生 swipe：', reasons.join(' | '));
      } catch { }
      foxJudgeLastCombined = '';
      foxJudgePendingInject = '';
      return;
    }

    e.stopImmediatePropagation();
    e.preventDefault();

    foxJudgeHandleRerollSwipe('swipe').then(() => {
      foxJudgeSkipNextSwipe = true;
      const swipeBtns = topDoc.querySelectorAll('.swipe_right, #swipe_right');
      if (swipeBtns.length) {
        swipeBtns[swipeBtns.length - 1].click();
      }
    });
  }

  // 🦊 文档级捕获兜底（reroll/swipe）：与 send 的兜底一样，挂一次到 topDoc，
  //    每次点击实时读取 cfg.enabled / cfg.rerollRethink / cfg.swipeRethink，
  //    防止酒馆重建按钮 DOM 后元素级监听失效导致狐裁完全不触发。
  let foxJudgeSwipeRerollDocGuardInstalled = false;
  let foxJudgeSwipeRerollDocGuardStops = [];
  function foxJudgeEnsureSwipeRerollDocGuard() {
    if (foxJudgeSwipeRerollDocGuardInstalled) return;
    try {
      const docClick = (e) => {
        const enabled = localStorage.getItem(FOX_JUDGE_LS_KEYS.enabled) === 'true';
        if (!enabled) return;
        const target = e.target;
        if (!target || !target.closest) return;
        // reroll 按钮：始终交给 handler 自行判断 rerollRethink。
        // 即使关闭 rerollRethink，handler 也要进入复用 preserved 思维链分支。
        if (target.closest('#option_regenerate') || target.closest('#regenerate')) {
          foxJudgeOnRerollClick(e);
          return;
        }
        // swipe 按钮（只处理最后一条消息的右翻按钮）
        const swipeBtn = target.closest('.swipe_right, #swipe_right');
        if (swipeBtn) {
          // 只拦截最后一条消息（即页面上最后一个 swipe_right）
          try {
            const swipeBtns = topDoc.querySelectorAll('.swipe_right, #swipe_right');
            const lastBtn = swipeBtns.length ? swipeBtns[swipeBtns.length - 1] : null;
            if (lastBtn && swipeBtn === lastBtn) {
              foxJudgeOnSwipeClick(e);
            }
          } catch { }
        }
      };
      topDoc.addEventListener('click', docClick, true);
      foxJudgeSwipeRerollDocGuardInstalled = true;
      foxJudgeSwipeRerollDocGuardStops = [
        () => { try { topDoc.removeEventListener('click', docClick, true); } catch { } },
      ];
      log('[狐裁] reroll/swipe 文档级捕获兜底已安装');
    } catch (e) {
      log('[狐裁] 安装 reroll/swipe 文档级兜底失败', e);
    }
  }
  function foxJudgeUninstallSwipeRerollDocGuard() {
    for (const fn of foxJudgeSwipeRerollDocGuardStops) {
      try { fn(); } catch { }
    }
    foxJudgeSwipeRerollDocGuardStops = [];
    foxJudgeSwipeRerollDocGuardInstalled = false;
  }

  function foxJudgeRegisterSwipeRerollListeners() {
    foxJudgeUnregisterSwipeRerollListeners();

    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return;

    // 🦊 兜底层：无论后续直接绑定成功与否，文档级捕获总是生效。
    foxJudgeEnsureSwipeRerollDocGuard();

    // 🦊 不再按 cfg.swipeRethink / cfg.rerollRethink 决定是否绑定元素级监听：
    //    关闭重新思考时，handler 仍需进入"复用 preserved 思维链"分支，
    //    把 foxJudgePreservedChain 塞回本次 foxJudgeLastCombined，
    //    否则 reroll/swipe 出来的新输出会缺失思维链注入。
    const regenBtn = topDoc.getElementById('option_regenerate') || topDoc.getElementById('regenerate');
    if (regenBtn) {
      regenBtn.addEventListener('click', foxJudgeOnRerollClick, true);
      foxJudgeRerollBtnHandle = { el: regenBtn, fn: foxJudgeOnRerollClick };
      log('[狐裁] reroll 拦截器已注册（rethink=' + (cfg.rerollRethink !== false) + '）');
    }

    const swipeBtns = topDoc.querySelectorAll('.swipe_right, #swipe_right');
    if (swipeBtns.length) {
      const lastBtn = swipeBtns[swipeBtns.length - 1];
      lastBtn.addEventListener('click', foxJudgeOnSwipeClick, true);
      foxJudgeSwipeBtnHandle = { el: lastBtn, fn: foxJudgeOnSwipeClick };
      log('[狐裁] swipe 拦截器已注册（rethink=' + (cfg.swipeRethink !== false) + '）');
    }
  }

  function foxJudgeUnregisterSwipeRerollListeners() {
    try {
      if (foxJudgeRerollBtnHandle?.el && foxJudgeRerollBtnHandle.fn) {
        foxJudgeRerollBtnHandle.el.removeEventListener('click', foxJudgeRerollBtnHandle.fn, true);
      }
    } catch { }
    try {
      if (foxJudgeSwipeBtnHandle?.el && foxJudgeSwipeBtnHandle.fn) {
        foxJudgeSwipeBtnHandle.el.removeEventListener('click', foxJudgeSwipeBtnHandle.fn, true);
      }
    } catch { }
    foxJudgeRerollBtnHandle = null;
    foxJudgeSwipeBtnHandle = null;
    foxJudgeRethinkPending = false;
    foxJudgeSkipNextReroll = false;
    foxJudgeSkipNextSwipe = false;
  }

  function foxJudgeCalcCharFingerprint() {
    try {
      const ctx = SillyTavern?.getContext?.();
      const char = ctx?.characters?.[ctx?.characterId];
      const charId = getCurrentCharId();

      if (!char) return `${charId}_none`;

      const parts = [
        charId,
        char.name || '',
        char.description || '',
        char.personality || '',
        char.scenario || '',
      ];

      try {
        const preset = getPreset?.('in_use');
        const prompts = preset?.prompts || [];
        const promptMap = new Map();
        for (const p of prompts) {
          const ref = p.id || p.identifier || '';
          if (ref) promptMap.set(ref, p);
        }

        const toggleParts = [];
        for (const t of CONFIG.QUICK_TOGGLE_IDS) {
          const p = promptMap.get(t.id);
          toggleParts.push(`${t.id}=${p ? !!p.enabled : 'x'}`);
        }
        parts.push('QT:' + toggleParts.join(','));

        const selectParts = [];
        for (const g of CONFIG.SELECT_GROUPS) {
          for (const opt of g.options) {
            const p = promptMap.get(opt.id);
            selectParts.push(`${opt.id}=${p ? !!p.enabled : 'x'}`);
          }
        }
        parts.push('SG:' + selectParts.join(','));

        const killParts = [];
        for (const t of CONFIG.KILL_TOGGLES) {
          const p = promptMap.get(t.id);
          killParts.push(`${t.id}=${p ? !!p.enabled : 'x'}`);
        }
        parts.push('KT:' + killParts.join(','));

        const customParts = [];
        for (const ce of CONFIG.CUSTOM_EDIT_IDS) {
          const p = promptMap.get(ce.id);
          const en = p ? !!p.enabled : false;
          const contentFull = p?.content || '';
          customParts.push(`${ce.id}=${en}:${contentFull}`);
        }
        parts.push('CE:' + customParts.join('|'));
      } catch (e) {
        log('[狐裁指纹] 读取预设选项失败', e);
      }

      return parts.join('||');
    } catch {
      return `${getCurrentCharId()}_err`;
    }
  }

  function foxJudgeCheckAndInvalidateIfChanged() {
    const cfg = foxJudgeReadConfig();
    if (cfg.phase1Fixed) return;
    const charId = getCurrentCharId();
    const cache = foxJudgeGetStaticCache(charId);
    if (!cache) return;

    const currentFp = foxJudgeCalcCharFingerprint();
    if (cache.fingerprint && cache.fingerprint !== currentFp) {
      // ✅ 指纹变更不再直接删除缓存内容，避免用户手编的 phase1 文本丢失。
      //    改为仅设置 stale 标记，让上层"是否命中缓存"的判断把它当作未命中即可。
      //    用户在面板里仍能看到原内容；下次主动保存编辑会用新指纹重写覆盖。
      try {
        const stale = { ...cache, stale: true, stale_fingerprint_seen_at: new Date().toISOString() };
        localStorage.setItem(FOX_JUDGE_LS_KEYS.charCachePrefix + charId, JSON.stringify(stale));
        log('[狐裁] 检测到角色卡/预设变更，缓存已标记为 stale（保留内容，不再自动命中）');
      } catch (e) {
        log('[狐裁] 标记 stale 失败，回退为直接删除', e);
        try { localStorage.removeItem(FOX_JUDGE_LS_KEYS.charCachePrefix + charId); } catch { }
      }
    }
  }

  const __original_foxJudgeSaveStaticCache = foxJudgeSaveStaticCache;
  foxJudgeSaveStaticCache = function (charId, cache) {
    cache.fingerprint = foxJudgeCalcCharFingerprint();
    // ✅ 主动保存的缓存视为新鲜，清掉可能残留的 stale 标记
    cache.stale = false;
    delete cache.stale_fingerprint_seen_at;
    return __original_foxJudgeSaveStaticCache(charId, cache);
  };

