  function openFoxMemoryPanel() {
    if (topDoc.getElementById('ss-foxmemory-panel')) {
      topDoc.getElementById('ss-foxmemory-panel')?.remove();
      topDoc.getElementById('ss-foxmemory-overlay')?.remove();
      return;
    }

    const overlay = topDoc.createElement('div');
    overlay.id = 'ss-foxmemory-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:1000002;';
    overlay.onclick = () => { xhGuideEnd(); overlay.remove(); topDoc.getElementById('ss-foxmemory-panel')?.remove(); };

    const panel = topDoc.createElement('div');
    panel.id = 'ss-foxmemory-panel';
    panel.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:800px;max-height:88vh;overflow-y:auto;background:rgba(22,18,20,0.98);border:1px solid rgba(232,120,74,0.3);border-radius:16px;padding:24px;z-index:1000003;color:#e8ddd4;font-size:13px;box-shadow:0 20px 60px rgba(0,0,0,0.7);display:flex;flex-direction:column;gap:14px;';

    const s = foxMemoryConfig;
    const isCustom = s.apiType === 'custom';
    const isInterval = s.autoMode === 'interval';
    const memCount = foxMemoryGetCurrent().length;

    // 分类 Tab
    let catTabsHtml = `<button class="foxmem-cat-tab" data-cat="all" style="padding:5px 12px;border:1px solid rgba(232,120,74,${foxMemoryEditing.selectedCategory === 'all' ? '0.5' : '0.2'});border-radius:6px;background:rgba(232,120,74,${foxMemoryEditing.selectedCategory === 'all' ? '0.15' : '0.03'});color:#f0a070;cursor:pointer;font-size:11px;">📚 全部</button>`;
    for (const c of FOX_MEMORY_CATEGORIES) {
      catTabsHtml += `<button class="foxmem-cat-tab" data-cat="${c.id}" style="padding:5px 12px;border:1px solid rgba(232,120,74,${foxMemoryEditing.selectedCategory === c.id ? '0.5' : '0.2'});border-radius:6px;background:rgba(232,120,74,${foxMemoryEditing.selectedCategory === c.id ? '0.15' : '0.03'});color:#f0a070;cursor:pointer;font-size:11px;">${c.icon} ${c.label}</button>`;
    }

    let presetOptionsHtml = '<option value="">（选择预设）</option>';
    try {
      const fn = getFn('getPresetNames');
      if (typeof fn === 'function') {
        const names = fn().filter(x => x !== 'in_use').sort();
        for (const n of names) {
          presetOptionsHtml += `<option value="${escapeHtml(n)}" ${s.customApi.proxyPreset === n ? 'selected' : ''}>${escapeHtml(n)}</option>`;
        }
