  function foxMemoryShouldAutoAnalyze(messageId, type) {
    // 只允许普通新回复触发；重roll、swipe、continue、quiet等都跳过
    // 🦊 reroll / swipe 保护：
    //   MESSAGE_RECEIVED 偶尔不会透传 type 参数（参数为 undefined / null / ''）。
    //   此时回退到 GENERATION_STARTED 抓到的 xhLastGenerationType，
    //   避免 reroll / swipe 被当成 'normal' 再触发一次记忆分析。
    const effType = (type && typeof type === 'string')
      ? type
      : (xhGetLastGenerationType() || null);
    if (effType && effType !== 'normal') {
      log(`[记忆自动分析] 跳过：非 normal 回复 type=${effType}${type ? '' : '（来自 GENERATION_STARTED 追踪）'}`);
      return false;
    }

    if (foxMemoryIsTruncatedMessage(messageId)) {
      log('[记忆自动分析] 跳过：检测到截断');
      return false;
    }

    const text = foxMemoryGetAssistantVisibleTextForAutoCheck(messageId);

    if (!text.trim()) {
      log('[记忆自动分析] 跳过：AI 回复为空');
      return false;
    }

    if (text.length < 300) {
      log(`[记忆自动分析] 跳过：AI 回复低于 300 字，当前=${text.length}`);
      return false;
    }

    return true;
  }

  function registerFoxMemoryAutoListener() {
    unregisterFoxMemoryAutoListener();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof eo !== 'function' || !te?.MESSAGE_RECEIVED) {
      log('[记忆自动分析] 注册失败：缺少 MESSAGE_RECEIVED');
      return;
    }

    foxMemoryAutoHandle = eo(te.MESSAGE_RECEIVED, (messageId, type) => {
      const mode = foxMemoryConfig.autoMode || 'manual';

      if (mode === 'manual') return;

      // 🦊 reroll / swipe 保护：
      //   立即在 MESSAGE_RECEIVED 触发的"那一刻"快照当前生成类型，
      //   后续 setTimeout 1200ms 期间 xhLastGenerationType 可能被脚本
      //   自己的 generateRaw（quiet）覆盖，所以必须先冻结。
      const snapshotType = (type && typeof type === 'string')
        ? type
        : (xhGetLastGenerationType() || null);

      setTimeout(() => {
        try {
          if (!foxMemoryShouldAutoAnalyze(messageId, snapshotType)) return;

          if (mode === 'auto') {
            // auto 模式每条合格回复都分析，计数器对它无意义；
            // 这里清零，避免之后切到 interval 模式时带入脏计数导致首次偏早触发。
            foxMemoryGenCounter = 0;
            xhEnqueueAutoTask(
              'fox_memory_auto_analyze',
              '狐忆自动分析',
              () => foxMemoryAnalyzeNow(),
              { dedupe: true }
            );
            return;
          }

          if (mode === 'interval') {
            const interval = Math.max(1, parseInt(foxMemoryConfig.autoInterval) || 30);
            const prevId = Number.isFinite(Number(foxMemoryLastAutoAnalyzeMessageId))
              ? Number(foxMemoryLastAutoAnalyzeMessageId)
              : -1;
            const currentId = Number(messageId);
            const floorDelta = currentId > prevId ? (currentId - prevId) : 0;
            foxMemoryGenCounter += Math.max(1, floorDelta);
            foxMemoryLastAutoAnalyzeMessageId = currentId;

            log(`[记忆自动分析] 实际楼层计数：${foxMemoryGenCounter}/${interval}`);

            if (foxMemoryGenCounter >= interval) {
              foxMemoryGenCounter = 0;
              xhEnqueueAutoTask(
                'fox_memory_auto_analyze',
                '狐忆自动分析',
                () => foxMemoryAnalyzeNow(),
                { dedupe: true }
              );
            }
          }
        } catch (e) {
          log('[记忆自动分析] 检查失败:', e);
        }
      }, 1200);
    });

    log('[记忆自动分析] 已注册 MESSAGE_RECEIVED 监听，仅 normal 且 >=300 字触发');
  }

  function unregisterFoxMemoryAutoListener() {
    try { foxMemoryAutoHandle?.stop?.(); } catch (e) { }
