  function hushenRecalcModuleIndex() {
    // 根据已有用户消息数量估算当前模块进度
    const userCount = hushenConversation.filter(m => m.role === 'user').length;
    hushenModuleIndex = Math.min(userCount, HUSHEN_ANALYSIS_MODULES.length);
  }

  function hushenEditMessage(index) {
    const msg = hushenConversation[index];
    if (!msg) return;

    const next = topWindow?.prompt
      ? topWindow.prompt(msg.role === 'ai' ? '编辑狐神抚回复：' : '编辑用户回复：', msg.text)
      : prompt(msg.role === 'ai' ? '编辑狐神抚回复：' : '编辑用户回复：', msg.text);

    if (next == null) return;

    msg.text = String(next);
    hushenRecalcModuleIndex();
    hushenRenderChat();
    toast('✅ 已编辑', 'success');
  }

  function hushenRollbackTo(index) {
    const ok = topWindow?.confirm
      ? topWindow.confirm('确定回退到这一步吗？后面的狐析对话会被删除。')
      : confirm('确定回退到这一步吗？');

    if (!ok) return;

    hushenConversation = hushenConversation.slice(0, index + 1);
    hushenRecalcModuleIndex();
    hushenRenderChat();
    toast('↩️ 已回退', 'success');
  }

  async function hushenRerollFrom(index) {
    const msg = hushenConversation[index];
    if (!msg) return;

    let userIndex = index;

    if (msg.role === 'ai') {
      userIndex = -1;
      for (let i = index - 1; i >= 0; i--) {
        if (hushenConversation[i].role === 'user') {
          userIndex = i;
          break;
        }
      }
    }

    if (userIndex < 0 || !hushenConversation[userIndex]) {
      toast('⚠️ 找不到可重roll的用户输入', 'warning');
      return;
    }

    const ok = topWindow?.confirm
      ? topWindow.confirm('确定从这一步重roll吗？这一步之后的内容会被删除哦🦊')
      : confirm('确定从这一步重roll吗？');

    if (!ok) return;

    const userText = hushenConversation[userIndex].text;

    // 保留到用户消息为止，删除后面的 AI 和后续步骤
    hushenConversation = hushenConversation.slice(0, userIndex + 1);
    hushenRecalcModuleIndex();
    hushenRenderChat();

    await hushenGenerateReplyForExistingUser(userText);
  }

