    try {
      const text = await husouGenerateTask({ system, user }, s);
      const normalized = String(text || '').trim();

      const match = normalized.match(/【过滤后的知识库】([\s\S]*?)(?:$|---)/);

      if (!match) {
        log('AI过滤结果未按格式返回，已丢弃本次搜索结果:', normalized.slice(0, 300));
        return new Map();
      }

      const content = match[1].trim();

      if (!content || /（?\s*无可用信息\s*）?/i.test(content)) {
        log('AI过滤判定：无新信息，已丢弃搜索结果');
        return new Map();
      }

      const map = new Map();
      const sections = content.split(/【关于「(.+?)」的说明】/);

      for (let i = 1; i < sections.length; i += 2) {
        const name = sections[i]?.trim();
        const body = sections[i + 1]?.trim();

        if (!name || !body) continue;

        if (/无可用信息|无相关信息|全部无关|完全无关|discard|irrelevant/i.test(body)) {
          continue;
        }

        map.set(name, body);
      }

      if (!map.size) {
        log('AI过滤结果没有可解析条目，已丢弃本次搜索结果:', normalized.slice(0, 300));
        return new Map();
      }

      return map;
    } catch (e) {
      log('AI过滤失败，已丢弃本次搜索结果:', e.message || e);
      return new Map();
    }
