  // ==================== 狐搜 localStorage 管理工具 ====================
  // 狐搜现在默认以 localStorage 为准：
  // - 默认不写入 char personality
  // - 面板“管理注入内容”显示/保存的是 localStorage
  // - 清空时同时清 localStorage + 清 char personality 残留

  function husouGetLocalStorageKey(charId = getCurrentCharId()) {
    return `SPreset_HusouLocal_${encodeURIComponent(charId)}`;
  }

  function husouLoadLocalData() {
    const key = husouGetLocalStorageKey();

    try {
      const raw = localStorage.getItem(key);
      if (!raw) return { blocks: [] };

      const parsed = JSON.parse(raw);

      if (parsed && Array.isArray(parsed.blocks)) {
        return parsed;
      }

      // 兼容旧格式：如果以前存成了纯文本
      if (typeof parsed === 'string') {
        return {
          blocks: parsed.trim()
            ? [{ ts: new Date().toISOString().split('T')[0], content: parsed.trim() }]
            : [],
        };
      }

      return { blocks: [] };
    } catch {
      return { blocks: [] };
    }
  }

  function husouLoadLocalText() {
    const data = husouLoadLocalData();

    return (data.blocks || [])
      .map(b => String(b?.content || '').trim())
      .filter(Boolean)
      .join('\n\n')
      .trim();
  }

  function husouSaveLocalText(text) {
    const value = String(text || '').trim();
    const key = husouGetLocalStorageKey();

    if (!value) {
      localStorage.removeItem(key);
      return;
    }

    const data = {
      blocks: [{
        ts: new Date().toISOString().split('T')[0],
        content: value,
      }],
    };

    localStorage.setItem(key, JSON.stringify(data));
  }

  function husouClearLocalStorage() {
    localStorage.removeItem(husouGetLocalStorageKey());
  }

  function husouClearAllLocalStorageKeys() {
    try {
      const keys = [];

      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);

        if (
          key &&
          (
            key.startsWith('SPreset_HusouLocal_') ||
            key === 'SPreset_HusouLocal'
          )
        ) {
          keys.push(key);
        }
      }

      for (const key of keys) {
        localStorage.removeItem(key);
      }

      log(`[狐搜] 已强制清理所有狐搜 localStorage：${keys.length} 个`);
    } catch (e) {
      log('[狐搜] 强制清理所有狐搜 localStorage 失败', e);
    }
  }

  function husouStripSearchInjectionFromPersonality(text) {
    let cleaned = String(text || '');

    // 新版 <SearchResults> 块
    cleaned = cleaned.replace(/\n*<SearchResults>[\s\S]*?<\/SearchResults>\n*/gi, '\n');

    // 旧版中文块
    cleaned = cleaned.replace(/\n*【🦊狐搜外部搜索参考[\s\S]*?【外部搜索参考结束】\n*/g, '\n');
    cleaned = cleaned.replace(/\n*【🔍 外部搜索参考[\s\S]*?【外部搜索参考结束】\n*/g, '\n');

    // 孤儿结束标记：你现在卡住的就是这个
    cleaned = cleaned.replace(/^\s*【外部搜索参考结束】\s*$/gm, '');

    // 清理过多空行
    cleaned = cleaned
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();

    return cleaned;
  }

  async function husouClearCharPersonalityInjection() {
    try {
      const ctx = SillyTavern?.getContext?.();
      const char = ctx?.characters?.[ctx?.characterId];

      if (!char) return false;

      const oldText = char.personality || '';
      const cleaned = husouStripSearchInjectionFromPersonality(oldText);

      if (cleaned === oldText.trim()) {
        return false;
      }

      char.personality = cleaned;

      const ee = getFn('eventEmit');
      const evt = tavern_events?.CHARACTER_EDITED;

      if (ee && evt) {
        await ee(evt, {
          detail: {
            id: ctx.characterId,
            character: char,
          },
        });
      }

      return true;
    } catch (e) {
      log('[狐搜] 清理 char personality 残留失败', e);
      return false;
    }
  }

