  function husouSetTriggerButtonLoading(btn, loading) {
    if (!btn) return;

    if (loading) {
      if (!btn.dataset.oldText) {
        btn.dataset.oldText = btn.textContent || btn.value || '';
        btn.dataset.oldBackground = btn.style.background || '';
        btn.dataset.oldBorderColor = btn.style.borderColor || '';
        btn.dataset.oldColor = btn.style.color || '';
      }

      if ('value' in btn) btn.value = '⛔ 取消搜索';
      else btn.textContent = '⛔ 取消搜索';

      btn.style.background = 'rgba(139,0,0,0.22)';
      btn.style.borderColor = 'rgba(220,90,70,0.45)';
      btn.style.color = '#ffb0a0';
      btn.disabled = false;
      return;
    }

    const old = btn.dataset.oldText || '🔍 搜索';

    if ('value' in btn) btn.value = old;
    else btn.textContent = old;

    btn.style.background = btn.dataset.oldBackground || '';
    btn.style.borderColor = btn.dataset.oldBorderColor || '';
    btn.style.color = btn.dataset.oldColor || '';
    btn.disabled = false;

    delete btn.dataset.oldText;
    delete btn.dataset.oldBackground;
    delete btn.dataset.oldBorderColor;
    delete btn.dataset.oldColor;
  }


