<input id="search_reset_btn" type="button" value="⚠️恢复默认" style="flex:1;padding:10px;border:1px solid rgba(139,0,0,0.3);border-radius:8px;background:rgba(139,0,0,0.15);color:#d08080;cursor:pointer;font-size:12px;"></div>
<div id="search_engine_status" style="color:#706058;font-size:10px;margin-top:4px;">当前状态：🦊狐搜 已加载</div></div>`;
  }
  function bindHusouPanelEvents(panel) {
    const g = id => panel.querySelector('#' + id) || topDoc.getElementById(id);

    ssBindTagPairsEditor('husou-inc', panel);
    ssBindTagPairsEditor('husou-exc', panel);
    const sourceMode = g('search_source_mode');
    const customSection = g('custom_search_api_section');

    if (sourceMode && customSection) {
      const syncCustomSection = () => {
        customSection.style.display = sourceMode.value === 'custom' ? 'block' : 'none';
      };
      sourceMode.addEventListener('change', syncCustomSection);
      syncCustomSection();
    }
    const analysisApi = g('search_analysis_api');
    const customApiSection = g('custom_api_section');

    if (analysisApi && customApiSection) {
      analysisApi.addEventListener('change', () => {
        customApiSection.style.display = analysisApi.value === 'custom' ? 'grid' : 'none';
      });
    }
    const modelSel = g('search_custom_model_select'); const modelInp = g('search_custom_model');
    if (modelSel && modelInp) modelSel.addEventListener('change', () => { if (modelSel.value) modelInp.value = modelSel.value; });

    // 🦊 附加参数（YAML）三个文本框：input/change 即时保存，
    //    不依赖底部"保存设置"的 debounce，避免输入后立即关闭面板导致丢失。
    {
      const saveHusouExtraParams = () => {
        const __extra = ssReadExtraParamsFromPanel('husou', panel);
        const s = state.husouSettings || (state.husouSettings = loadHusouSettings());
        s.customExtraBodyParamsYaml = __extra.extraBodyParamsYaml;
        s.customExcludeBodyParamsYaml = __extra.excludeBodyParamsYaml;
        s.customExtraHeadersYaml = __extra.extraHeadersYaml;
        saveHusouSettings();
      };
      ['husou-extra-body-yaml', 'husou-exclude-body-yaml', 'husou-extra-headers-yaml'].forEach(id => {
        const el = g(id);
        if (el) { el.addEventListener('input', saveHusouExtraParams); el.addEventListener('change', saveHusouExtraParams); }
      });
    }

    const fetchBtn = g('search_fetch_models_btn');
    if (fetchBtn) {
      fetchBtn.addEventListener('click', async () => {
        readHusouSettingsFromPanel(panel);
        await husouFetchModels();

        // 双保险：模型获取后再同步一次选择框
        const sel = g('search_custom_model_select');
        if (sel) {
          sel.innerHTML = getHusouModelOptionsHtml(state.husouSettings.customModel);
          sel.disabled = !state.husouRuntimeModels.length;
        }
      });
    }


    const presetMode = g('search_preset_mode');
    const presetSection = g('search_preset_section');
    const builtinHint = g('search_builtin_hint');

    if (presetMode && presetSection) {
      presetMode.addEventListener('change', () => {
        presetSection.style.display = presetMode.value === 'other' ? 'block' : 'none';
        if (builtinHint) {
          builtinHint.style.display = presetMode.value === 'builtin' ? 'block' : 'none';
        }
      });
    }
    const refreshPresets = g('search_refresh_presets_btn');
    if (refreshPresets) refreshPresets.addEventListener('click', () => { readHusouSettingsFromPanel(panel); const ps = g('search_preset_name'); if (ps) ps.innerHTML = getHusouPresetOptionsHtml(state.husouSettings.searchPresetName); });
    const testPreset = g('search_test_preset_btn');
    if (testPreset) testPreset.addEventListener('click', () => { readHusouSettingsFromPanel(panel); if (!state.husouSettings.searchPresetName) { toast('未选择预设', 'warning'); return; } try { getPreset(state.husouSettings.searchPresetName); toast(`预设读取成功：${state.husouSettings.searchPresetName}`, 'success'); } catch (e) { toast('预设读取失败', 'error'); } });
    const saveBtn = g('search_save_btn');
    if (saveBtn) saveBtn.addEventListener('click', () => { readHusouSettingsFromPanel(panel); toast('已保存', 'success'); });
    const manualBtn = g('search_manual_btn');
    if (manualBtn) manualBtn.addEventListener('click', async () => {
      readHusouSettingsFromPanel(panel);

      const lastId = getFn('getLastMessageId')?.();

      if (lastId == null) {
        toast('无法获取楼层', 'error');
        return;
      }

      state.husouLastHandledId = null;

      await husouManualSearch(lastId, {
        triggerButton: manualBtn,
      });
    });
    const manualKeywordBtn = g('search_manual_keyword_btn');
    if (manualKeywordBtn) {
      manualKeywordBtn.addEventListener('click', async () => {
        readHusouSettingsFromPanel(panel);
        await husouManualKeywordSearch('', {
          triggerButton: manualKeywordBtn,
        });
        refreshAnyHusouPanel();
      });
    }
    const testBtn = g('search_test_btn');
    if (testBtn) testBtn.addEventListener('click', () => { toast('面板正常', 'info'); });
    const resetBtn = g('search_reset_btn');
    if (resetBtn) {
      resetBtn.addEventListener('click', () => {
        state.husouRuntimeModels = [];
        state.husouSettings = { ...HUSOU_DEFAULTS };
        saveHusouSettings();

        panel.innerHTML = getHusouPanelHtml(state.husouSettings);
        bindHusouPanelEvents(panel);

        requestAnimationFrame(() => {
          enhanceHusouUI?.();
          applyMobilePanelFixNow?.();
        });

        setTimeout(() => {
          refreshHusouInjectionManager(panel);
          applyMobilePanelFixNow?.();
        }, 200);

        toast('已恢复默认', 'success');
      });
    }
    const refreshInj = g('injection_refresh_btn');
    if (refreshInj) refreshInj.addEventListener('click', () => { refreshHusouInjectionManager(panel); toast('已刷新', 'info'); });
    const saveInj = g('injection_save_btn');
    if (saveInj) saveInj.addEventListener('click', async () => { const ta = g('injection_manager_textarea'); if (!ta?.value.trim()) { toast('内容为空', 'warning'); return; } await husouInjectCustom(ta.value); });
    const clearInj = g('injection_clear_btn');
    if (clearInj) clearInj.addEventListener('click', () => husouClearInjection());
  }
  function readHusouSettingsFromPanel(panel) {
    const g = id => panel.querySelector('#' + id) || topDoc.getElementById(id);
    const s = state.husouSettings; if (!s) return;
    s.enableAutoSearch = !!g('search_enable_auto')?.checked;
    const sourceModeEl = g('search_source_mode');
    if (sourceModeEl) {
      if (sourceModeEl.value === 'custom') {
        s.enableCustomSearch = true;
        s.enableWikipedia = false;
        s.enableMoegirl = false;
      } else {
        s.enableCustomSearch = false;
        s.enableWikipedia = true;
        s.enableMoegirl = true;
      }
    }
    s.enableJinaFetch = !!g('search_enable_jina')?.checked; s.smartSkip = !!g('search_smart_skip')?.checked; s.aiFilter = !!g('search_ai_filter')?.checked;
    s.saveToPersonality = !!g('search_save_personality')?.checked;
    s.injectCurrentPrompt = !!g('search_inject_prompt')?.checked;

    // 🆕 批次 3C：按角色卡存 localStorage 开关
    s.saveToHusouLocal = !!g('search_save_husou_local')?.checked;

    // 🏷️ 狐搜上下文标签过滤设置
    const husouTagFilter = ssNormalizeTagFilterSettings({
      enableContentFilter: !!g('husou-content-filter')?.checked,
      includeTagPairs: ssReadTagPairsEditor('husou-inc', panel),
      excludeTagPairs: ssReadTagPairsEditor('husou-exc', panel),
    });

    s.enableContentFilter = husouTagFilter.enableContentFilter;
    s.includeTagPairs = husouTagFilter.includeTagPairs;
    s.excludeTagPairs = husouTagFilter.excludeTagPairs;

    // 兼容旧字段
    s.includeTagStarts = husouTagFilter.includeTagStarts;
    s.includeTagEnds = husouTagFilter.includeTagEnds;
    s.excludeTagStarts = husouTagFilter.excludeTagStarts;
    s.excludeTagEnds = husouTagFilter.excludeTagEnds;
    s.analysisApi = g('search_analysis_api')?.value || 'current';
    s.customApiUrl = g('search_custom_api_url')?.value?.trim() || '';
    s.customApiKey = g('search_custom_api_key')?.value?.trim() || '';
    s.customModel = g('search_custom_model')?.value?.trim() || '';
    s.customMaxTokens = Number(g('search_custom_max_tokens')?.value || 4096);
    s.customTemperature = Number(g('search_custom_temperature')?.value || 1);
    s.customFrequencyPenalty = Number(g('search_custom_frequency_penalty')?.value || 0);
    s.customPresencePenalty = Number(g('search_custom_presence_penalty')?.value || 0);
    s.customTopP = Number(g('search_custom_top_p')?.value || 1); s.customTopK = Number(g('search_custom_top_k')?.value || 0);
    // 🦊 附加参数（YAML，仅 analysisApi === 'custom' 时生效）
    {
      const __extra = ssReadExtraParamsFromPanel('husou', panel);
      s.customExtraBodyParamsYaml = __extra.extraBodyParamsYaml;
      s.customExcludeBodyParamsYaml = __extra.excludeBodyParamsYaml;
      s.customExtraHeadersYaml = __extra.extraHeadersYaml;
    }
    s.searchPresetMode = g('search_preset_mode')?.value || 'builtin'; s.searchPresetName = g('search_preset_name')?.value?.trim() || ''; s.searchApiUrl = g('search_api_url')?.value?.trim() || ''; s.searchApiMethod = g('search_api_method')?.value || 'GET'; s.searchApiKey = g('search_api_key')?.value?.trim() || ''; s.searchApiKeyHeaderName = g('search_api_key_header_name')?.value?.trim() || ''; s.searchApiKeyHeaderTemplate = g('search_api_key_header_template')?.value?.trim() || ''; s.searchApiQueryParam = g('search_api_query_param')?.value?.trim() || ''; s.searchApiBodyTemplate = g('search_api_body_template')?.value?.trim() || ''; s.searchApiResultPath = g('search_api_result_path')?.value?.trim() || ''; s.searchApiTitleField = g('search_api_title_field')?.value?.trim() || ''; s.searchApiSnippetField = g('search_api_snippet_field')?.value?.trim() || ''; s.searchApiLinkField = g('search_api_link_field')?.value?.trim() || ''; s.searchApiLanguage = g('search_api_language')?.value?.trim() || 'zh-CN'; s.searchApiExtraParams = g('search_api_extra_params')?.value?.trim() || ''; s.maxKeywords = Number(g('search_max_keywords')?.value || 50);
    s.searchTimeout = Number(g('search_timeout')?.value || 20000);
    s.jinaPageTimeout = Number(g('search_jina_page_timeout')?.value || 20000);
    s.maxExtractLength = Number(g('search_extract_length')?.value || 40000);
    s.searchResultsCount = Number(g('search_results_count')?.value || 10);

    saveHusouSettings();
  }
  async function husouFetchModels() {
    if (state.husouRuntimeLoading) return;

    const s = state.husouSettings;
    const apiurl = (s.customApiUrl || '').trim().replace(/\/+$/, '');

    if (!apiurl) {
      toast('请先填写 API 地址', 'warning');
      return;
    }

    const panel = topDoc.getElementById('ss-husou-panel');
    const modelSelect = panel?.querySelector('#search_custom_model_select') || topDoc.getElementById('search_custom_model_select');
    const fetchBtn = panel?.querySelector('#search_fetch_models_btn') || topDoc.getElementById('search_fetch_models_btn');

    state.husouRuntimeLoading = true;

    if (fetchBtn) {
      fetchBtn.value = '获取中…';
      fetchBtn.disabled = true;
    }

    if (modelSelect) {
      modelSelect.disabled = true;
    }

    try {
      const getModelList = getFn('getModelList');

      if (typeof getModelList === 'function') {
        state.husouRuntimeModels = await getModelList({
          apiurl,
          key: s.customApiKey || '',
        });
      } else {
        const headers = SillyTavern?.getRequestHeaders?.() || {};

        const resp = await fetch('/api/backends/chat-completions/status', {
          method: 'POST',
          headers,
          body: JSON.stringify({
            reverse_proxy: apiurl,
            proxy_password: s.customApiKey || '',
            chat_completion_source: 'openai',
          }),
        });

        const json = await resp.json();

        state.husouRuntimeModels = (json?.data || [])
          .map(x => String(x?.id ?? '').trim())
          .filter(Boolean);
      }

      state.husouRuntimeModels = [...new Set(state.husouRuntimeModels)].sort();

      // ✅ 关键修复：模型获取完成后，立刻刷新当前面板里的模型下拉框
      if (modelSelect) {
        modelSelect.innerHTML = getHusouModelOptionsHtml(s.customModel);
        modelSelect.disabled = state.husouRuntimeModels.length === 0;

        // 如果当前 input 里已经有模型，尽量同步选中项
        if (s.customModel && state.husouRuntimeModels.includes(s.customModel)) {
          modelSelect.value = s.customModel;
        }
      }

      toast(
        state.husouRuntimeModels.length
          ? `已获取 ${state.husouRuntimeModels.length} 个模型`
          : '模型列表为空',
        state.husouRuntimeModels.length ? 'success' : 'warning'
      );
    } catch (e) {
      toast(`获取失败：${e.message}`, 'error');
    } finally {
      state.husouRuntimeLoading = false;

      if (fetchBtn) {
        fetchBtn.value = '获取模型';
        fetchBtn.disabled = false;
      }

      if (modelSelect) {
        modelSelect.disabled = state.husouRuntimeModels.length === 0;
      }
    }
  }


  async function husouExecuteSearch(messageId, opts = {}) {
    const manual = !!opts.manual;
    const triggerButton = opts.triggerButton || null;
    const forcedKeywords = husouNormalizeKeywords(opts.keywords || opts.manualKeywords || []);

    const mid = typeof messageId === 'object'
      ? (messageId?.message_id ?? messageId?.id)
      : messageId;

    if (mid == null && !forcedKeywords.length) {
      if (manual) toast('无法获取楼层', 'error');
      return;
    }

    if (state.husouIsRunning || ssIsTaskRunning('husou_search')) {
      ssCancelTask('husou_search', '狐搜');
      try { state.husouAbortController?.abort?.(); } catch { }
      state.husouAbortController = null;
      state.husouIsRunning = false;
      ssEndTask('husou_search');
      state.husouDebug.status = 'idle';
      state.husouDebug.lastError = '用户取消搜索';
      husouUpdateQuickPanel();
      husouSetTriggerButtonLoading(triggerButton, false);
      return;
    }

    const s = state.husouSettings || (state.husouSettings = loadHusouSettings());

    if (!manual && !s.enableAutoSearch) return;

    if (!husouHasBaseSearchSource(s)) {
      if (manual) {
        toast('请至少启用一个基础搜索来源。Jina 是网页全文抓取，不是独立搜索源。', 'warning');
      }
      return;
    }

    const midKey = String(mid);

    if (!manual && state.husouLastHandledId === midKey) return;

    const gcm = getFn('getChatMessages');
    const msg = mid != null ? gcm?.(mid)?.[0] : null;

    if (!forcedKeywords.length && (!msg || !msg.message?.trim())) {
      if (manual) toast('无法读取该楼层消息', 'warning');
      return;
    }

    if (!manual) state.husouLastHandledId = midKey;

    state.husouIsRunning = true;

    if (state.husouDebug) {
      state.husouDebug.status = 'running';
      state.husouDebug.lastError = '';
      try { husouUpdateQuickPanel(); } catch { }
    }
    husouSetTriggerButtonLoading(triggerButton, true);

    state.husouDebug = {
      status: 'running',
      keywords: [],
      rawText: '',
      filteredText: '',
      injectText: '',
      lastError: '',
    };
    husouUpdateQuickPanel();
    const husouCtrl = new AbortController();
    state.husouAbortController = husouCtrl;
    const husouGenId = ssStartTask('husou_search', '狐搜');
    ssAttachAbortController('husou_search', husouCtrl);
    state.husouPendingInject = null;
    state.husouPendingKeywords = [];
    state.husouPendingConsumed = false;

    let completed = false;
    let searchToast = null;

    try {
      searchToast = ssTaskToast(
        'husou_search',
        manual ? '🦊 搜索中🔎……' : '🦊 自动狐搜中🔎……'
      );
    } catch { }

    try {
      let keywords = [];

      if (forcedKeywords.length) {
        keywords = forcedKeywords;
        log('使用手动输入关键词：', keywords);
      } else {
        const ctx = husouGetFullContext(mid);
        keywords = await husouAnalyzeContext(ctx, s);
      }

      state.husouCurrentKeywords = keywords;
      state.husouPendingKeywords = keywords;
      state.husouDebug.keywords = keywords;
      husouUpdateQuickPanel();
      husouUpdateKeywordPanel(keywords);

      if (!keywords.length) {
        toast('狐搜：无关键词', 'info');
        completed = true;
        return;
      }

      state.husouDebug.status = 'running';
      state.husouDebug.rawText = `【搜索状态】
关键词已提取，正在调用搜索源：
${keywords.join('、')}

如果这里停留很久，说明正在等待搜索源或网络返回。`;
      husouUpdateQuickPanel();

      log('[狐搜] 开始调用搜索源，关键词：', keywords);

      const raw = await husouSearchAll(keywords, s, husouCtrl.signal);
      const rawDebugText = husouFormatMapForDebug(raw);

      state.husouDebug.rawText = rawDebugText || `【搜索源返回为空】

本次关键词：
${keywords.join('、')}

当前启用的基础搜索源：
- Wikipedia：${s.enableWikipedia ? '开启' : '关闭'}
- 萌娘百科：${s.enableMoegirl ? '开启' : '关闭'}
- 自定义搜索源：${s.enableCustomSearch ? '开启' : '关闭'}

提示：
1. 如果这里为空，说明基础搜索源没有拿到有效内容。
2. 你当前日志里“任务 4 个”通常表示只启用了 Wiki + 萌百，自定义搜索源没有启用。
3. 如果你的网络访问 Wiki / 萌百不稳定，请在狐搜面板里开启“自定义来源 API”，或把默认 enableCustomSearch 改成 true。`;

      husouUpdateQuickPanel();

      if (!raw.size) {
        state.husouDebug.status = 'error';
        state.husouDebug.lastError = '搜索源返回 0 条有效结果';
        husouUpdateQuickPanel();

        toast('狐搜：搜索源返回为空。请检查网络，或开启自定义来源 API。', 'warning');
        completed = true;
        return;
      }

      log(`原始结果 ${raw.size} 个`);

      // 原版结构：Jina 抓全文在 husouFilterResults() 内部执行
      const filtered = await husouFilterResults(raw, s, keywords, husouCtrl.signal);
      state.husouDebug.filteredText = husouFormatMapForDebug(filtered);
      state.husouDebug.injectText = husouBuildInjectBlock(filtered);
      husouUpdateQuickPanel();
      if (!filtered?.size) {
        toast('狐搜：过滤无结果', 'warning');
        completed = true;
        return;
      }

      state.husouPendingInject = filtered;
      state.husouPendingConsumed = false;

      // 关键修复：
      // 无论是否保存到 char personality，都必须调用统一保存函数。
      // husouSaveToChar 内部会自己判断：
      // - saveToHusouLocal 为 true 时，写入当前角色卡 localStorage；
      // - saveToPersonality 为 true 时，写入 char personality。
      //
      // 旧代码只在 saveToPersonality=true 时才调用，
      // 导致默认 saveToHusouLocal=true 也完全不会保存，所以管理面板一直为空。
      await husouSaveToChar(filtered);

      refreshAnyHusouPanel();

      toast(`${manual ? '手动搜索' : '自动狐搜'}完成：${filtered.size} 条`, 'success');
      if (state.husouDebug) {
        state.husouDebug.status = 'done';
        try { husouUpdateQuickPanel(); } catch { }
      }

      state.husouDebug.status = 'done';
      husouUpdateQuickPanel();
      completed = true;
    } catch (e) {
      state.husouPendingInject = null;
      state.husouPendingKeywords = [];

      if (!manual) {
        state.husouLastHandledId = null;
      }

      const msg = e?.message || String(e || '');

      if (
        e?.name === 'AbortError' ||
        /abort|aborted|cancel|中断|取消/i.test(msg)
      ) {
        toast('⛔ 狐搜已取消', 'warning');

        if (state.husouDebug) {
          state.husouDebug.status = 'idle';
          state.husouDebug.lastError = '用户取消搜索';
          try { husouUpdateQuickPanel(); } catch { }
        }
      } else {
        toast(`失败：${msg}`, 'error');

        if (state.husouDebug) {
          state.husouDebug.status = 'error';
          state.husouDebug.lastError = msg;
          try { husouUpdateQuickPanel(); } catch { }
        }
      }
    } finally {
      try {
        if (searchToast?.remove) searchToast.remove();
      } catch { }

      // 重要：
      // 这里不能 toastr.clear()。
      // 否则刚刚弹出的 “搜索无结果 / 过滤无结果 / 成功 / 失败” toast 会被立刻清掉，
      // 用户就会误以为狐搜卡死或没有任何反馈。
      // 原代码：
      // const t = topWindow?.toastr || window.toastr;
      // if (t?.clear) t.clear();

      if (!manual && !completed) {
        state.husouLastHandledId = null;
      }

      state.husouIsRunning = false;
      state.husouAbortController = null;
      husouSetTriggerButtonLoading(triggerButton, false);
      ssEndTask('husou_search');
    }
  }

  // ==================== 事件 ====================
  function onGenStart(type, option, dryRun) {
    if (dryRun || !state.enabled || window.__searchEngineBusy || !isThoughtVisible()) return;

    state.isGenerating = true;
    updateBubbleUI();

    (async () => {
      if (!state.isMini) await disableAllBeauty();
      else await disableAllMini();

      await setThoughtVisible(false);
    })();

    const tid = setTimeout(async () => {
      await forceRefreshAll();
    }, CONFIG.HIDE_DELAY);

    state._timers.hide = tid;
  }

  function onGenEnd(mid) {
    if (!state.enabled || window.__searchEngineBusy) return;

    state.isGenerating = false;
    updateBubbleUI();

    const tid = setTimeout(async () => {
      await setBeautyStyle(state.currentStyle, state.isExpanded);
      await setThoughtVisible(true);
      await forceRefreshAll();
    }, CONFIG.RESTORE_DELAY);

    state._timers.restore = tid;

    onBeatGenEnd(mid);
    onSummaryGenEnd(mid);
  }

  function onSummaryGenEnd(mid) {
    try {
      if (!state.summaryAutoEnabled && state.summaryMode !== 'auto') return;
      if (state.isSummarizing) return;
      if (ssIsTaskRunning('full_summary')) return;
      if (ssActiveTasks.has('husou_search')) return;
      if (state.outlineIsCorrecting || state.outlineIsGenerating) return;
      if (pwState?.running) return;
      if (state.foxAnalyzing) return;
      if (state.isGenerating) return;

      setTimeout(() => {
        try {
          runAutoSummaryAt(mid);
        } catch (e) {
          log('[自动总结] 触发失败', e);
        }
      }, 1500);
    } catch (e) {
      log('[自动总结] 监听失败', e);
    }
  }
  function bindEvents() {
    unbindEvents();

    try {
      if (typeof eventOn !== 'function') return;

      const h1 = tavern_events?.GENERATION_STARTED
        ? eventOn(tavern_events.GENERATION_STARTED, onGenStart)
        : null;

      const h2 = tavern_events?.GENERATION_ENDED
        ? eventOn(tavern_events.GENERATION_ENDED, onGenEnd)
        : null;

      if (h1) state.eventHandles.push(h1);
      if (h2) state.eventHandles.push(h2);
    } catch (e) {
      log('绑定事件失败', e);
    }
  }

  function unbindEvents() {
    state.eventHandles.forEach(h => {
      try { h?.stop?.(); } catch (e) { }
    });

    state.eventHandles = [];
  }

  // ==================== UI组件 ====================
  function updateBubbleUI() {
    const b = topDoc.getElementById('ss-float-bubble');
    if (!b) return;

    b.classList.toggle('enabled', state.enabled);
    b.classList.toggle('generating', state.isGenerating);
  }

  function createToggleSwitch(promptId, onChange) {
    const w = topDoc.createElement('span');
    w.style.cssText = 'display:inline-flex;gap:0;border-radius:6px;overflow:hidden;border:1px solid rgba(232,120,74,0.25);flex-shrink:0;';

    const onB = topDoc.createElement('span');
    onB.textContent = '开';

    const offB = topDoc.createElement('span');
    offB.textContent = '关';

    [onB, offB].forEach(b => {
      b.style.cssText = 'padding:3px 10px;cursor:pointer;font-size:11px;font-weight:600;transition:all 0.15s;';
    });

    function up() {
      const e = isPromptEnabledInPreset(promptId);

      if (e) {
        onB.style.background = 'rgba(232,120,74,0.25)';
        onB.style.color = '#f0a070';
        offB.style.background = 'transparent';
        offB.style.color = '#555';
      } else {
        onB.style.background = 'transparent';
        onB.style.color = '#555';
        offB.style.background = 'rgba(232,120,74,0.25)';
        offB.style.color = '#f0a070';
      }
    }

    onB.onclick = async () => {
      await togglePromptById(promptId, true);
      up();
      if (onChange) onChange(true);
    };

    offB.onclick = async () => {
      await togglePromptById(promptId, false);
      up();
      if (onChange) onChange(false);
    };

    w.appendChild(onB);
    w.appendChild(offB);
    up();

    return {
      wrapper: w,
      update: up,
    };
  }

