  // 默认开启；关闭后这些功能不再监听 Enter，用户可正常换行。
  const SS_ENTER_LISTEN_KEY = 'smoothStream_enterListenEnabled';

  function ssGetEnterListenEnabled() {
    const v = localStorage.getItem(SS_ENTER_LISTEN_KEY);
    if (v === null || v === undefined) return true;
    return v === '1' || v === 'true';
  }

  function ssSetEnterListenEnabled(enabled) {
    localStorage.setItem(SS_ENTER_LISTEN_KEY, enabled ? '1' : '0');
    return !!enabled;
  }

  // ==================== 中控面板字体大小 ====================
  const SS_PANEL_FONT_SIZE_KEY = 'smoothStream_panelFontSize';

  function ssGetPanelFontSize() {
    const v = parseInt(localStorage.getItem(SS_PANEL_FONT_SIZE_KEY) || '13');
    return Number.isFinite(v) ? Math.max(11, Math.min(20, v)) : 13;
  }

  function ssSetPanelFontSize(v) {
    const size = Math.max(11, Math.min(20, parseInt(v) || 13));
    localStorage.setItem(SS_PANEL_FONT_SIZE_KEY, String(size));
    ssApplyPanelFontSize(size);
    return size;
  }

