  function buildBubbleHTML() { return `<div id="ss-float-bubble" class="${state.enabled ? 'enabled' : ''} ${state.isGenerating ? 'generating' : ''}" style="top:${panelConfig.bubbleTop};${panelConfig.bubbleSide === 'right' ? 'right:12px;left:auto;' : 'left:12px;right:auto;'}">🦊<div class="bubble-dot"></div></div>`; }

  async function initUI() {
    if (topDoc.getElementById('ss-float-bubble')) return;

    topDoc.head.insertAdjacentHTML('beforeend', BUBBLE_CSS);
    topDoc.body.insertAdjacentHTML('beforeend', buildBubbleHTML());

    const bubble = topDoc.getElementById('ss-float-bubble');
    if (!bubble) return;

    let dragging = false;
    let dragMoved = false;
    let dragJustEnded = false;

    let startX = 0;
    let startY = 0;
    let startLeft = 0;
    let startTop = 0;

    const DRAG_THRESHOLD = 8;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    bubble.addEventListener('pointerdown', (e) => {
      dragging = true;
      dragMoved = false;

      startX = e.clientX;
      startY = e.clientY;

      const rect = bubble.getBoundingClientRect();
      startLeft = rect.left;
      startTop = rect.top;

      bubble.setPointerCapture?.(e.pointerId);
      bubble.style.transition = 'none';

      e.preventDefault();
      e.stopPropagation();
    });

    bubble.addEventListener('pointermove', (e) => {
      if (!dragging) return;

      const dx = e.clientX - startX;
      const dy = e.clientY - startY;

      if (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD) {
        dragMoved = true;
      }

      if (!dragMoved) return;

      const vw = topWindow.innerWidth || topDoc.documentElement.clientWidth || 800;
      const vh = topWindow.innerHeight || topDoc.documentElement.clientHeight || 600;

      const nextLeft = clamp(startLeft + dx, 4, vw - 52);
      const nextTop = clamp(startTop + dy, 4, vh - 52);

      bubble.style.left = `${nextLeft}px`;
      bubble.style.right = 'auto';
      bubble.style.top = `${nextTop}px`;
    });

    bubble.addEventListener('pointerup', (e) => {
      if (!dragging) return;

      dragging = false;
      bubble.style.transition = '';

      try {
        bubble.releasePointerCapture?.(e.pointerId);
      } catch { }

      if (dragMoved) {
        const rect = bubble.getBoundingClientRect();
        const vw = topWindow.innerWidth || topDoc.documentElement.clientWidth || 800;

        const side = (rect.left + rect.width / 2) < vw / 2 ? 'left' : 'right';
        const top = clamp(rect.top, 4, (topWindow.innerHeight || 600) - 52);

        bubble.style.top = `${top}px`;

        if (side === 'left') {
          bubble.style.left = '12px';
          bubble.style.right = 'auto';
        } else {
          bubble.style.right = '12px';
          bubble.style.left = 'auto';
        }

        savePanelConfig({
          bubbleTop: `${top}px`,
          bubbleSide: side,
        });
        try { pwPositionMiniBubble?.(); } catch { }
        dragJustEnded = true;
        setTimeout(() => {
          dragJustEnded = false;
        }, 180);
      }

      try { topDoc.body.focus(); } catch { }
    });

    bubble.addEventListener('pointercancel', () => {
      dragging = false;
      dragMoved = false;
      bubble.style.transition = '';
      try { topDoc.body.focus(); } catch { }
    });

    bubble.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();

      if (dragJustEnded || dragMoved) return;

      if (topDoc.getElementById('ss-dashboard')) {
        closeDashboard();
      } else {
        openDashboard();
      }
    });
  }


  // ============= 🆕 批次 3A：🦊 狐忆 工具函数 =============

  /**
   * 获取当前角色卡唯一标识
   * 优先用 characterId，没有则用 avatar 文件名
   */
  function getCurrentChatScopeId() {
    try {
      const ctx = SillyTavern?.getContext?.();

      if (ctx?.chatId) return String(ctx.chatId);
      if (ctx?.chat?.id) return String(ctx.chat.id);
      if (ctx?.chat?.name) return String(ctx.chat.name);

      const fn = getFn('getCurrentChatId');
      if (typeof fn === 'function') {
        const id = fn();
        if (id) return String(id);
      }
    } catch (e) {
      console.warn('[狐忆] 获取聊天 ID 失败:', e);
    }

    return 'default_chat';
  }

  /**
   * 获取当前角色卡唯一标识
   * 优先用 characterId，没有则用 avatar 文件名
   */
  function getCurrentCharId() {
    try {
      const ctx = SillyTavern.getContext();
      if (ctx) {
        if (ctx.characterId !== undefined && ctx.characters) {
          const char = ctx.characters[ctx.characterId];
          if (char) {
            if (char.avatar) return char.avatar.replace(/\.[^.]+$/, '');
            if (char.name) return char.name;
          }
        }
      }
    } catch (e) {
      console.warn('[狐忆] 获取角色卡 ID 失败:', e);
    }
    return 'unknown_char';
  }

  function getFoxMemoryScopeId() {
    return `${getCurrentCharId()}__chat_${getCurrentChatScopeId()}`;
  }

  function getFoxMemoryStorageKey() {
    return `SPreset_FoxMemory_${encodeURIComponent(getFoxMemoryScopeId())}`;
  }

  /**
   * 读取当前角色卡 + 当前聊天的记忆库
   */
  function loadFoxMemory() {
    const key = getFoxMemoryStorageKey();

    try {
      const raw = localStorage.getItem(key);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && parsed.memories) {
          return parsed;
        }
      }
    } catch (e) {
