  function pwLoadConfig() {
    // 防御性深拷贝：避免 PW_DEFAULT_CONFIG 中的 tag pair 数组被外部代码 push/splice 污染
    const clonePairs = (arr) => Array.isArray(arr) ? arr.map(p => ({ start: p?.start || '', end: p?.end || '' })) : [];
    const freshDefault = () => ({
      ...PW_DEFAULT_CONFIG,
      customApi: { ...PW_DEFAULT_CONFIG.customApi },
      includeTagPairs: clonePairs(PW_DEFAULT_CONFIG.includeTagPairs),
      excludeTagPairs: clonePairs(PW_DEFAULT_CONFIG.excludeTagPairs),
    });

    try {
      const raw = localStorage.getItem(PW.CONFIG_KEY);

      if (!raw) {
        return freshDefault();
      }

      const parsed = JSON.parse(raw) || {};

      const cfg = {
        ...PW_DEFAULT_CONFIG,
        ...parsed,
        customApi: {
          ...PW_DEFAULT_CONFIG.customApi,
          ...(parsed.customApi || {}),
        },
        includeTagPairs: Array.isArray(parsed.includeTagPairs)
          ? clonePairs(parsed.includeTagPairs)
          : clonePairs(PW_DEFAULT_CONFIG.includeTagPairs),
        excludeTagPairs: Array.isArray(parsed.excludeTagPairs)
          ? clonePairs(parsed.excludeTagPairs)
          : clonePairs(PW_DEFAULT_CONFIG.excludeTagPairs),
      };

      // ✅ 兼容旧版 autoAdvance:boolean
      // 如果旧配置里没有 autoMode，就根据 autoAdvance 自动迁移
      if (parsed.autoMode == null) {
        cfg.autoMode = parsed.autoAdvance ? 'auto' : 'manual';
      }

      // 保持旧字段同步，避免旧 UI/旧逻辑读取出错
      cfg.autoAdvance = cfg.autoMode !== 'manual';

      cfg.autoInterval = Math.max(1, parseInt(cfg.autoInterval) || 5);

      // ✅ 推进模式校验：只允许 two_phase / legacy_full
      if (cfg.advanceMode !== 'legacy_full' && cfg.advanceMode !== 'two_phase') {
        cfg.advanceMode = 'two_phase';
      }

      // ✅ 动态推进单次最多更新模块数：默认 4，限制在 [1, 24]
      cfg.dynamicMaxModules = Math.max(1, Math.min(24, parseInt(cfg.dynamicMaxModules) || 4));

      // ✅ chatHistoryLimit 规整：
      //   - 不是 'all' 关键字、不是空、必须是正整数才生效；其它一律视为全部
      if (cfg.chatHistoryLimit == null) {
        cfg.chatHistoryLimit = '';
      } else if (typeof cfg.chatHistoryLimit === 'number') {
        cfg.chatHistoryLimit = Number.isFinite(cfg.chatHistoryLimit) && cfg.chatHistoryLimit > 0
          ? Math.floor(cfg.chatHistoryLimit)
          : '';
      } else {
        const s = String(cfg.chatHistoryLimit).trim();
        if (!s || /^all$/i.test(s)) {
          cfg.chatHistoryLimit = '';
        } else {
          const n = parseInt(s);
          cfg.chatHistoryLimit = Number.isFinite(n) && n > 0 ? n : '';
        }
      }

      // 旧版配置迁移：新版本只保留摘要字数范围，旧 summaryMaxChars/maxInjectChars 不再作为用户配置。
      const legacySummaryMax = parseInt(cfg.summaryMaxChars);
      if (cfg.summaryWordMin == null && Number.isFinite(legacySummaryMax)) {
        cfg.summaryWordMin = Math.max(50, Math.min(2000, Math.min(300, legacySummaryMax)));
      }
      cfg.summaryWordMin = Math.max(50, Math.min(2000, parseInt(cfg.summaryWordMin) || 300));
      cfg.summaryWordMax = Math.max(50, Math.min(2000, parseInt(cfg.summaryWordMax) || 400));
      if (cfg.summaryWordMax < cfg.summaryWordMin) cfg.summaryWordMax = cfg.summaryWordMin;
      cfg.summaryMaxChars = cfg.summaryWordMax;
      delete cfg.maxInjectChars;
      cfg.maxInjectModules = Math.max(1, Math.min(50, parseInt(cfg.maxInjectModules) || 10));
      cfg.maxUrgentEvents = Math.max(1, parseInt(cfg.maxUrgentEvents) || 3);

      // 🏷️ 标签过滤：使用统一标签过滤工具规整字段
      const tagFilter = ssNormalizeTagFilterSettings({
        enableContentFilter: cfg.enableContentFilter !== false,
        includeTagPairs: cfg.includeTagPairs,
        excludeTagPairs: cfg.excludeTagPairs,
        includeTagStarts: cfg.includeTagStarts,
        includeTagEnds: cfg.includeTagEnds,
        excludeTagStarts: cfg.excludeTagStarts,
        excludeTagEnds: cfg.excludeTagEnds,
      });
      cfg.enableContentFilter = tagFilter.enableContentFilter;
      cfg.includeTagPairs = tagFilter.includeTagPairs;
      cfg.excludeTagPairs = tagFilter.excludeTagPairs;
      cfg.includeTagStarts = tagFilter.includeTagStarts;
      cfg.includeTagEnds = tagFilter.includeTagEnds;
      cfg.excludeTagStarts = tagFilter.excludeTagStarts;
      cfg.excludeTagEnds = tagFilter.excludeTagEnds;

      // 旧用户没有 fox_tips / fox_selc 时自动补一组（用户要求新增的默认排除标签）
      const ensureExcludePair = (start, end) => {
        const exists = (cfg.excludeTagPairs || []).some(p => p && p.start === start && p.end === end);
        if (!exists) {
          cfg.excludeTagPairs = [
            ...(cfg.excludeTagPairs || []),
            { start, end },
          ];
        }
      };
      const before = JSON.stringify(cfg.excludeTagPairs || []);
      ensureExcludePair('<fox_tips>', '</fox_tips>');
      ensureExcludePair('<fox_selc>', '</fox_selc>');
      if (before !== JSON.stringify(cfg.excludeTagPairs || [])) {
        cfg.excludeTagStarts = ssPairsToLines(cfg.excludeTagPairs, 'start');
        cfg.excludeTagEnds = ssPairsToLines(cfg.excludeTagPairs, 'end');
      }

      return cfg;
    } catch {
      return freshDefault();
    }
  }

  function pwSaveConfig() {
