  // ✅ 统一解析 max_chat_history：所有 pwGenerateRaw 都通过它拿值
  function pwResolveChatHistoryLimit() {
    const cfg = pwState.config || pwLoadConfig();
    const raw = cfg.chatHistoryLimit;

    if (raw === '' || raw == null) return 'all';
    if (typeof raw === 'number') {
      return raw > 0 ? Math.floor(raw) : 'all';
    }

    const s = String(raw).trim();
    if (!s || /^all$/i.test(s)) return 'all';

    const n = parseInt(s);
    return Number.isFinite(n) && n > 0 ? n : 'all';
  }

  // ✅ 把"AI 返回的新模块"安全合并到"旧模块"上：
  //    - 旧字段为底（不丢历史信息）
  //    - 新字段覆盖（推进结果）
  //    - 关键叙事字段若新值为空字符串则保留旧值，避免 AI 漏返回时把历史清空
  //    - id 强制保留旧值
  function pwMergeModuleUpdate(oldModule, newModule) {
    if (!oldModule) return newModule;
    if (!newModule) return oldModule;

    const fallbackKeys = [
      'roleAudit', 'perspective', 'progressNote', 'dangerLevel',
      'mainlineImpact', 'requiredMainlineInsertion', 'currentLocation',
      'currentState', 'nextTendency', 'independence', 'detail', 'summary',
    ];

    const merged = { ...oldModule, ...newModule };

    for (const k of fallbackKeys) {
      const nv = newModule[k];
      const ov = oldModule[k];
      if (nv == null || (typeof nv === 'string' && nv.trim() === '')) {
        if (ov != null && ov !== '') merged[k] = ov;
      }
    }

    merged.id = oldModule.id;
    return merged;
  }

  // ✅ 同样的 merge 思路用于 module_summary
  function pwMergeSummaryUpdate(oldSummary, newSummary) {
    if (!oldSummary) return newSummary;
    if (!newSummary) return oldSummary;

    const fallbackKeys = [
      'summary', 'impactToMain', 'requiredMainlineInsertion',
      'progressNote', 'dangerLevel', 'time',
    ];

    const merged = { ...oldSummary, ...newSummary };

    for (const k of fallbackKeys) {
      const nv = newSummary[k];
      const ov = oldSummary[k];
      if (nv == null || (typeof nv === 'string' && nv.trim() === '')) {
        if (ov != null && ov !== '') merged[k] = ov;
      }
    }

    merged.id = oldSummary.id;
    return merged;
  }

  // ✅ 推进流程入口统一前置检查：chatId 仍处于 __PENDING__ 时不允许触发
  //    任何会调用 AI 的推进流程，避免用户消耗 AI 调用却看不到结果。
  function pwGuardChatReady() {
    const chatId = pwGetChatId();
    if (typeof chatId === 'string' && chatId.startsWith('__PENDING__')) {
      toast('⏳ 聊天 ID 尚未就绪（可能刚切换聊天），请稍后再触发平行世界推进', 'warning');
      log('[平行世界] 推进入口拦截：chatId 仍处于 __PENDING__');
      return false;
    }
    return true;
  }

  function pwGetChatId() {
    // 严格按"角色卡 + 聊天文件"做隔离。下面的查找顺序按可靠度从高到低：
    // 1) 酒馆助手公开 API getCurrentChatId() —— 一切场景下最稳
    // 2) SillyTavern.getContext().chatId / chat.file_name / chat_metadata
    // 3) 从酒馆 DOM/全局 chid + chat 变量兜底
    // 4) 实在拿不到，就返回带角色卡前缀的 __PENDING__，避免和别的角色卡撞 key。
    try {
      const fn = getFn('getCurrentChatId');
      if (typeof fn === 'function') {
        const id = fn();
        if (id) return String(id);
      }
    } catch { }

    try {
      const ctx = SillyTavern?.getContext?.();
      if (ctx) {
        if (ctx.chatId) return String(ctx.chatId);
        // chat 是消息数组，没有 id；但部分版本会带 file_name
        if (ctx.chat?.file_name) return String(ctx.chat.file_name);
        if (ctx.chatMetadata?.file_name) return String(ctx.chatMetadata.file_name);
        if (ctx.chatMetadata?.chat_id) return String(ctx.chatMetadata.chat_id);
        // 兜底再用一次 name（旧逻辑，可能为空）
        if (ctx.chat?.name) return String(ctx.chat.name);
      }
    } catch { }

    try {
      const tw = topWindow || window;
      // 酒馆全局变量 chat_metadata.file_name 或 selected_group/chat 文件名
      if (tw?.chat_metadata?.file_name) return String(tw.chat_metadata.file_name);
      if (tw?.chat_metadata?.chat_id) return String(tw.chat_metadata.chat_id);
    } catch { }

    // 拿不到聊天 ID 时，至少挂在当前角色卡下，避免不同角色/不同聊天共用 default_chat。
    return `__PENDING__${encodeURIComponent(getCurrentCharId())}`;
  }

  function pwDataKey() {
    return `${PW.DATA_PREFIX}${encodeURIComponent(getCurrentCharId())}_${encodeURIComponent(pwGetChatId())}`;
  }

  // 当前 (charId, chatId) 的稳定标识，写到 data 里用于校验
  function pwGetBoundScope() {
    return {
      charId: String(getCurrentCharId() || ''),
      chatId: String(pwGetChatId() || ''),
    };
  }

  function pwEmptyData() {
    const scope = pwGetBoundScope();
    return {
      version: 2,
      cleared: true,
      // 绑定信息：用来防止"跨聊天/跨角色卡幽灵"——加载时一旦不匹配就丢弃
      boundCharId: scope.charId,
      boundChatId: scope.chatId,
      turn: 0,
      worldClock: '',
      globalState: {
        title: '',
        detail: '',
      },
      modules: [],
      inject: {
        global_summary: '',
        module_summaries: [],
        manual_text: '',
        consumed: true,
      },
      raw: null,
      updatedAt: '',
    };
  }

  function pwLoadData() {
    try {
      const raw = localStorage.getItem(pwDataKey());
      if (!raw) return pwEmptyData();

      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return pwEmptyData();

      // ✅ 隔离校验：如果数据带了 boundCharId/boundChatId，但和当前不一致，
      //    说明这是历史串数据，直接返回空，避免角色 A 像幽灵在 B 里出现。
      //    没有绑定字段的旧数据视作"首次绑定到当前 (char, chat)"，下次保存时补上。
      try {
        const scope = pwGetBoundScope();
        const hasBound = parsed.boundCharId != null || parsed.boundChatId != null;

        if (hasBound) {
          const sameChar = String(parsed.boundCharId || '') === scope.charId;
          const sameChat = String(parsed.boundChatId || '') === scope.chatId;

          if (!sameChar || !sameChat) {
            log('[平行世界] 数据隔离校验失败，丢弃跨聊天残留', {
              expectChar: scope.charId,
              expectChat: scope.chatId,
              gotChar: parsed.boundCharId,
              gotChat: parsed.boundChatId,
            });
            return pwEmptyData();
          }
        } else {
          parsed.boundCharId = scope.charId;
          parsed.boundChatId = scope.chatId;
        }
      } catch { }

      if (!parsed.inject) {
        parsed.inject = {
          global_summary: '',
          module_summaries: [],
          manual_text: '',
          consumed: true,
        };
      }

      if (!Array.isArray(parsed.modules)) parsed.modules = [];
      if (!Array.isArray(parsed.inject.module_summaries)) parsed.inject.module_summaries = [];
      if (typeof parsed.inject.manual_text !== 'string') parsed.inject.manual_text = '';
      // ✅ 一次性注入门闩：旧数据没有该字段时默认 false，让历史聊天的现存平行世界仍可被注入一次
      if (typeof parsed.inject.consumed !== 'boolean') parsed.inject.consumed = false;

      // ✅ 修复历史 BUG 残留：旧版本归一化里 `String(obj.global_state || ...)` 会把对象写成 "[object Object]"，
      //    这里加载时主动检测并清掉，避免面板下拉栏里一直显示这串字符串。
      if (!parsed.globalState || typeof parsed.globalState !== 'object') {
        parsed.globalState = { title: '', detail: '' };
      } else {
        if (typeof parsed.globalState.title !== 'string') parsed.globalState.title = String(parsed.globalState.title || '');
        if (typeof parsed.globalState.detail !== 'string') parsed.globalState.detail = '';
        if (parsed.globalState.detail === '[object Object]') parsed.globalState.detail = '';
      }

      return parsed;
    } catch {
      return pwEmptyData();
    }
  }

  function pwSaveData(data) {
    pwState.data = data;
    try {
      // ✅ chatId 还没就绪时不要落盘，避免在 localStorage 里残留 __PENDING__ 孤儿 key
      const chatId = pwGetChatId();
      if (typeof chatId === 'string' && chatId.startsWith('__PENDING__')) {
        log('[平行世界] chatId 尚未就绪，跳过本次写入以防孤儿 key');
        return false;
      }

      // ✅ 写入时强制写入当前 (charId, chatId) 绑定信息
      const scope = pwGetBoundScope();
      data.boundCharId = scope.charId;
      data.boundChatId = scope.chatId;
      data.boundAt = new Date().toISOString();
      localStorage.setItem(pwDataKey(), JSON.stringify(data));
      return true;
    } catch {
      return false;
    }
  }

  // 清理 localStorage 里因早期 chatId 不就绪而残留的 __PENDING__ 数据 key。
  // 只清平行世界自己的命名空间 (PW.DATA_PREFIX)，不动其它模块的 key。
  function pwCleanupPendingKeys() {
    try {
      const prefix = PW.DATA_PREFIX;
      const toRemove = [];

      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k) continue;
        if (!k.startsWith(prefix)) continue;
        // 仅当 key 中包含编码后的 __PENDING__ 标记时才视为孤儿
        if (k.includes('__PENDING__')) toRemove.push(k);
      }

      toRemove.forEach(k => {
        try { localStorage.removeItem(k); } catch { }
      });

      if (toRemove.length) {
        log(`[平行世界] 已清理 ${toRemove.length} 个 __PENDING__ 残留 key`);
      }
    } catch { }
  }

  function pwHasContent(data = pwLoadData()) {
    if (!data || data.cleared === true) return false;
    if (data.inject?.manual_text?.trim()) return true;
    if (data.inject?.global_summary?.trim()) return true;
    if (Array.isArray(data.inject?.module_summaries) && data.inject.module_summaries.length) return true;
    if (Array.isArray(data.modules) && data.modules.length) return true;
    return false;
  }

  function pwClip(text, max = 2000) {
    const raw = String(text || '').trim();
    if (raw.length <= max) return raw;
    return raw.slice(0, max).trim() + '\n……（已截断）';
  }

  function pwSummaryWordRange(cfg = pwState.config || pwLoadConfig()) {
    const min = Math.max(50, Math.min(2000, parseInt(cfg?.summaryWordMin) || 300));
    const rawMax = Math.max(50, Math.min(2000, parseInt(cfg?.summaryWordMax) || 400));
    const max = Math.max(min, rawMax);
    return { min, max, text: `${min}-${max}` };
  }

  function pwSummaryRangeMaxChars(cfg = pwState.config || pwLoadConfig()) {
    return Math.max(300, pwSummaryWordRange(cfg).max);
  }

  function pwNormalizeImpactLevel(level, fallback = 'none') {
    const raw = String(level ?? '').trim().toLowerCase();

    if (!raw) return fallback;

    if (/critical|crit|危急|致命|爆发|最高|打断|劫持/.test(raw)) return 'critical';
    if (/high|高|强|逼近|必须/.test(raw)) return 'high';
    if (/mid|medium|中|自然影响|后续影响/.test(raw)) return 'mid';
    if (/low|低|轻微|背景/.test(raw)) return 'low';
    if (/none|no|无|暂无/.test(raw)) return 'none';

    return fallback;
  }

  function pwImpactRank(level) {
    const lv = pwNormalizeImpactLevel(level, 'none');

    if (lv === 'critical') return 4;
    if (lv === 'high') return 3;
    if (lv === 'mid') return 2;
    if (lv === 'low') return 1;
    return 0;
  }

  function pwClampProgress(value) {
    let n = value;

    if (typeof n === 'string') {
      n = n.replace('%', '').trim();
    }

    n = Number(n);

    if (!Number.isFinite(n)) n = 0;

    return Math.max(0, Math.min(100, Math.round(n)));
  }

  function pwProgressLevel(progress) {
    const p = pwClampProgress(progress);

    if (p >= 100) return 'critical';
    if (p >= 75) return 'high';
    if (p >= 40) return 'mid';
    if (p > 0) return 'low';

    return 'none';
  }

  function pwShouldShowProgress(item) {
    if (!item) return false;

    if (item.progressEnabled === true) return true;

    const p = pwClampProgress(item.progress);
    if (p > 0) return true;

    const bag = `${item.title || ''}\n${item.summary || ''}\n${item.detail || ''}\n${item.nextTendency || ''}\n${item.impactToMain || item.mainlineImpact || ''}`;

    return /追捕|调查|搜索|赶往|逼近|倒计时|扩散|感染|筹备|潜伏|寻找|任务|计划|目标|危机|入侵|追踪|侦查|审判|通缉|狩猎/.test(bag);
  }

  function pwGetEffectiveImpactLevel(item) {
    const base = pwNormalizeImpactLevel(
      item?.impactLevel || item?.impact_level || item?.dangerLevel || item?.danger_level,
      'none'
    );

    const progressLv = pwShouldShowProgress(item)
      ? pwProgressLevel(item?.progress)
      : 'none';

    return pwImpactRank(progressLv) > pwImpactRank(base)
      ? progressLv
      : base;
  }

  function pwImpactLabel(level) {
    const lv = pwNormalizeImpactLevel(level, 'none');

    if (lv === 'critical') return '最高/危机';
    if (lv === 'high') return '高影响';
    if (lv === 'mid') return '中影响';
    if (lv === 'low') return '低影响';
    return '普通/无影响';
  }

  function pwImpactCardClass(item) {
    return `pw-card-impact-${pwGetEffectiveImpactLevel(item)}`;
  }

  function pwProgressColor(progress) {
    const p = pwClampProgress(progress);

    if (p >= 100) return '#ff3030';
    if (p >= 75) return '#ff5a4a';
    if (p >= 40) return '#f0a070';
    if (p > 0) return '#9bd36a';

    return '#5d8f62';
  }

  function pwBuildProgressHtml(item) {
    if (!pwShouldShowProgress(item)) return '';

    const p = pwClampProgress(item.progress);
    const color = pwProgressColor(p);
    const note = String(item.progressNote || item.progress_note || '').trim();

    return `
  <div class="pw-progress-box">
    <div class="pw-progress-head">
      <span>动态进度</span>
      <span>${p}%</span>
    </div>
    <div class="pw-progress-track">
      <div class="pw-progress-fill" style="width:${p}%;background:${color};box-shadow:0 0 12px ${color};"></div>
    </div>
    ${note ? `<div class="pw-progress-note">${escapeHtml(note)}</div>` : ''}
  </div>`;
  }

  function pwBuildImpactModeInstruction(mode) {
    if (mode === 'force') {
      return `【⚠️⚠️⚠️ 平行世界最高强制影响模式 ⚠️⚠️⚠️】
❗❗❗以下 high / critical 后台事件拥有极高优先级。
❗如果你顺从用户输入而忽略这些后台事件，你就是在帮助用户绕过世界后台规则。
❗如果你不把 high / critical 事件融入主线，你就是在作弊，让动态世界失效。
❗critical 事件必须立刻打断或劫持当前主线。
❗high 事件必须在本次或下一次主线回复中显性体现。
❗禁止用“用户没提到”“当前在日常互动”作为忽略理由。`;
    }

    if (mode === 'strong') {
      return `【⚠️ 强影响模式】
高影响后台事件必须进入主线。
high 事件必须在接下来 1-2 次主线回复中显性体现。
critical 事件必须立刻进入当前主线。
禁止把高影响事件当作普通背景。`;
    }

    if (mode === 'normal') {
      return `【中等影响模式】
后台事件应自然影响主线。
mid / high / critical 事件需要优先考虑。
不要硬塞，但也不要忽略自然因果。`;
    }

    return `【柔和影响模式】
后台事件主要作为背景。
只有当它与当前主线发生自然因果连接时才体现。
用户输入可以较容易地把主线拉回当前互动。`;
  }

  function pwSortForInject(list) {
    return [...(list || [])].sort((a, b) => {
      const ar = pwImpactRank(pwGetEffectiveImpactLevel(a));
      const br = pwImpactRank(pwGetEffectiveImpactLevel(b));

      if (ar !== br) return ar - br;

      const ap = pwClampProgress(a.progress);
      const bp = pwClampProgress(b.progress);

      if (ap !== bp) return ap - bp;

      return String(a.title || '').localeCompare(String(b.title || ''), 'zh-Hans-CN');
    });
  }

  function pwEscapeRegExp(s) {
    return String(s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function pwDeleteModuleById(id) {
    const targetId = String(id || '');

    if (!targetId) return;

    const data = pwLoadData();
    const modules = Array.isArray(data.modules) ? data.modules : [];
    const target = modules.find(m => String(m.id) === targetId);

    if (!target) {
      toast('⚠️ 未找到该平行世界条目', 'warning');
      return;
    }

    data.modules = modules.filter(m => String(m.id) !== targetId);

    if (!data.inject) {
      data.inject = {
        global_summary: '',
        module_summaries: [],
        manual_text: '',
      };
    }

    data.inject.module_summaries = (data.inject.module_summaries || [])
      .filter(m => String(m.id) !== targetId);

    const title = String(target.title || '').trim();

    if (title) {
      const titleRe = new RegExp(`^.*${pwEscapeRegExp(title)}.*$`, 'gm');

      data.inject.global_summary = String(data.inject.global_summary || '')
        .replace(titleRe, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim();

      data.globalState.detail = String(data.globalState?.detail || '')
        .replace(titleRe, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    }

    if (!data.modules.length && !data.inject.manual_text?.trim()) {
      data.cleared = true;
      data.inject.global_summary = '';
      data.globalState.detail = '';
    }

    pwSaveData(data);
    pwRenderPanel();
    pwRenderStateFloat();

    toast(`🗑️ 已删除平行世界条目及对应摘要：${target.title}`, 'success');
  }

  function pwBindModuleActionButtons(root = topDoc) {
    const scope = root?.querySelectorAll ? root : topDoc;

    scope.querySelectorAll('.pw-module-delete').forEach(btn => {
      if (btn.dataset.bound === '1') return;

      btn.dataset.bound = '1';

      btn.onclick = (e) => {
        e.preventDefault();
        e.stopPropagation();

        const id = btn.getAttribute('data-pw-id') || '';

        const ok = topWindow?.confirm
          ? topWindow.confirm('确定要删除这个平行世界条目吗？对应的模块摘要也会同步删除。')
          : confirm('确定要删除这个平行世界条目吗？');

        if (!ok) return;

        pwDeleteModuleById(id);
      };
    });

    // ✅ 单条事件"推进"按钮：只推进这一条事件，不影响其他事件
    scope.querySelectorAll('.pw-module-advance').forEach(btn => {
      if (btn.dataset.bound === '1') return;

      btn.dataset.bound = '1';

      btn.onclick = async (e) => {
        e.preventDefault();
        e.stopPropagation();

        const id = btn.getAttribute('data-pw-id') || '';
        if (!id) return;

        // 注意：不要 disabled 按钮，否则用户无法二次点击中断单条推进；
        // 只在文案上提示状态。pwAdvanceSingleModule 自身会处理"再次点击 = 中断"。
        const originalText = btn.textContent;
        const isCancel = pwState.singleRunning || ssIsTaskRunning('parallel_world_single');

        try {
          if (!isCancel) btn.textContent = '⛔ 中断';
          await pwAdvanceSingleModule(id);
        } catch (err) {
          log('[平行世界] 单条推进失败', err);
          toast(`❌ 单条推进失败：${err?.message || err}`, 'error');
        } finally {
          btn.textContent = originalText;
        }
      };
    });
  }

  function pwExtractJson(text) {
    const raw = String(text || '').trim();
    const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
    const candidate = fence ? fence[1].trim() : raw;

    try {
      return JSON.parse(candidate);
    } catch { }

    const start = candidate.indexOf('{');
    const end = candidate.lastIndexOf('}');

    if (start >= 0 && end > start) {
      return JSON.parse(candidate.slice(start, end + 1));
    }

    throw new Error('AI 没有返回可解析 JSON');
  }

  // ==================== 🌌 平行世界 标签文本解析器 ====================
  // 让模型只输出人类可读的分块文本（不要求合法 JSON），
  // 由脚本严格解析后自动套上对应的 JSON 结构，避免模型输出 JSON 时易出格式错误。
  //
  // 协议规则（新版，简单直观）：
  // - 标量字段：单独一行 `# 字段名`，下一行起写值（可多行），直到下一个 `#` 标签行
  // - 列表字段：用 `# 模块开始` ... `# 模块结束` 块包裹每一项
  //   摘要列表用 `# 摘要开始` ... `# 摘要结束` 包裹每一项
  // - 向后兼容旧 `<<<KEY>>>` 写法，并容忍写错括号数量（如 `<<<KEY>>`）
  // - 布尔：true/false/是/否/yes/no  数字：进度 0-100
  // - 字段名大小写不敏感，可写中英文字段名（脚本做映射）
  // - 只有命中已知字段名的标签行才生效，正文中偶发的 # 行会被当成正文
  // - 模型可以使用 ``` 围栏包裹整个输出（脚本会去掉）
  // - 任何在标签外的多余说明文字都会被忽略，不会破坏解析
  const PW_TP_BOOL_TRUE = /^(true|是|yes|y|1|启用|开|on)$/i;
  const PW_TP_BOOL_FALSE = /^(false|否|no|n|0|禁用|关|off|空|无)$/i;

  // 字段中文同义词 → 标准英文键
  const PW_TP_KEY_MAP = {
    'WORLD_CLOCK': 'world_clock', '世界时钟': 'world_clock', '剧情时间': 'world_clock', 'TIME': 'world_clock',
    'GLOBAL_TITLE': 'global_title', '世界状态标题': 'global_title', '全局标题': 'global_title',
    'GLOBAL_DETAIL': 'global_detail', '世界状态详情': 'global_detail', '全局详情': 'global_detail', '世界状态': 'global_detail',
    'GLOBAL_SUMMARY': 'global_summary', '全局摘要': 'global_summary', '主线注入摘要': 'global_summary',

    // 模块字段
    'ID': 'id',
    'TYPE': 'type', '类型': 'type',
    'TITLE': 'title', '标题': 'title',
    'PERSPECTIVE': 'perspective', '视角': 'perspective',
    'ROLE_AUDIT': 'role_audit', '人设审查': 'role_audit',
    'DETAIL': 'detail', '正文': 'detail', '完整内容': 'detail', '后台正文': 'detail',
    'SUMMARY': 'summary', '摘要': 'summary',
    'INDEPENDENCE': 'independence', '独立性': 'independence',
    'MAINLINE_IMPACT': 'mainline_impact', '对主线影响': 'mainline_impact', '主线影响': 'mainline_impact', '对主线的影响': 'mainline_impact',
    'IMPACT_TO_MAIN': 'impact_to_main', '主线影响详情': 'impact_to_main',
    'IMPACT_LEVEL': 'impact_level', '影响级别': 'impact_level', '影响等级': 'impact_level',
    'REQUIRED_MAINLINE_INSERTION': 'required_mainline_insertion', '必须插入主线': 'required_mainline_insertion', '主线必须体现': 'required_mainline_insertion',
    'PROGRESS_ENABLED': 'progress_enabled', '启用进度': 'progress_enabled', '进度启用': 'progress_enabled',
    'PROGRESS': 'progress', '进度': 'progress',
    'PROGRESS_NOTE': 'progress_note', '进度说明': 'progress_note', '进度备注': 'progress_note',
    'CURRENT_LOCATION': 'current_location', '当前位置': 'current_location', '位置': 'current_location',
    'CURRENT_STATE': 'current_state', '当前状态': 'current_state',
    'NEXT_TENDENCY': 'next_tendency', '下一步倾向': 'next_tendency', '下一步': 'next_tendency',
    'DANGER_LEVEL': 'danger_level', '危险等级': 'danger_level', '危险级别': 'danger_level',
    'REASON': 'reason', '理由': 'reason', '原因': 'reason',
    'SELECTED_IDS': 'selected_ids', '选中ID': 'selected_ids', '挑选事件': 'selected_ids', '挑选ID': 'selected_ids', '选中': 'selected_ids',
    'TIME': 'time',

    // 块边界标记（新中文标记 + 旧英文标记，统一归一化）
    'MODULE_BEGIN': 'module_begin', '模块开始': 'module_begin', '事件开始': 'module_begin', '镜头开始': 'module_begin',
    'MODULE_END': 'module_end', '模块结束': 'module_end', '事件结束': 'module_end', '镜头结束': 'module_end',
    'SUMMARY_BEGIN': 'summary_begin', '摘要开始': 'summary_begin',
    'SUMMARY_END': 'summary_end', '摘要结束': 'summary_end',
  };

  // 归一化辅助：忽略大小写、下划线、空白后的查找表（英文键）
  const PW_TP_KEY_MAP_LOOSE = (() => {
    const m = {};
    for (const k of Object.keys(PW_TP_KEY_MAP)) {
      const loose = k.toUpperCase().replace(/[_\s]/g, '');
      if (!(loose in m)) m[loose] = PW_TP_KEY_MAP[k];
    }
    return m;
  })();

  function pwTpNormalizeKey(rawKey) {
    if (!rawKey) return '';
    // 去掉标签外壳字符（# < > 【】［］ 冒号 空白），保留核心键名
    const cleaned = String(rawKey).trim().replace(/[#<>【】\[\]：:\s]/g, '');
    if (!cleaned) return '';
    // 1) 中文/原样键直接查表
    if (PW_TP_KEY_MAP[cleaned]) return PW_TP_KEY_MAP[cleaned];
    // 2) 英文键大写后查表
    const upper = cleaned.toUpperCase();
    if (PW_TP_KEY_MAP[upper]) return PW_TP_KEY_MAP[upper];
    // 3) 忽略下划线/空白的宽松匹配（兼容 # WORLD CLOCK / WORLDCLOCK 等写法）
    const loose = upper.replace(/[_\s]/g, '');
    if (PW_TP_KEY_MAP_LOOSE[loose]) return PW_TP_KEY_MAP_LOOSE[loose];
    // 4) 兜底：返回小写英文键
    return upper.toLowerCase();
  }

  function pwTpToBool(v) {
    const s = String(v || '').trim();
    if (!s) return false;
    if (PW_TP_BOOL_TRUE.test(s)) return true;
    if (PW_TP_BOOL_FALSE.test(s)) return false;
    return false;
  }

  function pwTpToNumber(v) {
    const s = String(v || '').trim();
    const m = s.match(/-?\d+(?:\.\d+)?/);
    return m ? parseFloat(m[0]) : 0;
  }

  // ── 统一标签匹配（高容错）──────────────────────────────
  // 新格式（推荐，简单直观）：每个标签独占一行，以 # 开头，例如：
  //   # 标题
  //   # DETAIL
  // 旧格式（向后兼容）：<<<KEY>>>，并兼容写错括号数量的情况，如 <<<KEY>> / <<KEY>>> / <<KEY>>。
  //
  // 这里用一个统一正则把"一整行就是一个标签"的行识别出来：
  // - 形如  #KEY / # KEY / ##KEY
  // - 形如  <<<KEY>>> / <<KEY>> / <<<KEY>>  （两个或更多尖括号，左右数量可不一致）
  // 标签行里只允许标签本身（前后可有空白），不允许夹带正文，避免误伤。
  const PW_TP_TAG_LINE_RE = /^[ \t]*(?:#{1,3}[ \t]*([^\r\n#<>]+?)|<{2,}[ \t]*([^\r\n<>]+?)[ \t]*>{2,})[ \t]*$/;

  // 块的开始/结束标记（标准键，已归一化后比较）
  const PW_TP_BLOCK_BEGIN = { module: 'module_begin', summary: 'summary_begin' };
  const PW_TP_BLOCK_END = { module: 'module_end', summary: 'summary_end' };

  // 所有合法的归一化"字段"键集合（只有命中这些键的行才会被当作字段标签，
  // 否则视为正文，避免正文中偶发的 # 开头行被误判为标签而截断内容）。
  // 注意：故意排除块边界标记（module_begin/end、summary_begin/end），
  // 因为块的识别由 pwTpExtractBlocks/pwTpStripBlocks 单独处理；
  // 这样即便正文里出现“# 模块结束”等词，也只会当作普通正文，不会截断字段。
  const PW_TP_BLOCK_NORMS = new Set([
    PW_TP_BLOCK_BEGIN.module, PW_TP_BLOCK_END.module,
    PW_TP_BLOCK_BEGIN.summary, PW_TP_BLOCK_END.summary,
  ]);
  const PW_TP_VALID_NORMS = (() => {
    const s = new Set(Object.values(PW_TP_KEY_MAP));
    for (const b of PW_TP_BLOCK_NORMS) s.delete(b);
    return s;
  })();

  function pwTpScanTags(text) {
    const out = [];
    const src = String(text || '');
    const lines = src.split(/\r?\n/);
    let pos = 0;
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const lineLen = line.length;
      const lineEnd = pos + lineLen;
      pos = lineEnd + 1; // +1 为换行符
      const m = line.match(PW_TP_TAG_LINE_RE);
      if (m) {
        const rawKey = (m[1] || m[2] || '').trim();
        if (!rawKey) continue;
        const norm = pwTpNormalizeKey(rawKey);
        // 只接受已知字段键或块边界标记，未知的一律当正文处理
        if (!norm || !PW_TP_VALID_NORMS.has(norm)) continue;
        out.push({ rawKey, norm, contentStart: lineEnd + 1 });
      }
    }
    return out;
  }

  // 解析单个块内的字段（块内文本不含 BEGIN/END 标记行）
  function pwTpParseBlock(blockText) {
    const obj = {};
    if (!blockText) return obj;
    const tags = pwTpScanTags(blockText);
    if (!tags.length) return obj;
    for (let i = 0; i < tags.length; i++) {
      const cur = tags[i];
      const next = tags[i + 1];
      const norm = cur.norm;
      // 跳过块边界标记
      if (!norm || /_(begin|end)$/.test(norm)) continue;
      const sliceEnd = next ? Math.max(cur.contentStart, blockTextIndexOfTagLine(blockText, next)) : blockText.length;
      const value = blockText.slice(cur.contentStart, sliceEnd).trim();
      // 只在第一次出现时写入，避免重复标签覆盖（如正文中误带标签行的极端情况）
      if (!(norm in obj)) obj[norm] = value;
    }
    return obj;
  }

  // 找到某个标签在原文中所属行的起始下标（用于切分上一字段的值的末尾）
  function blockTextIndexOfTagLine(blockText, tag) {
    // tag.contentStart 是该标签行的下一行起点；回退到该标签行的行首
    let idx = tag.contentStart - 1; // 换行符位置
    if (idx < 0) idx = 0;
    // 回退到行首
    let lineStart = blockText.lastIndexOf('\n', idx - 1);
    return lineStart < 0 ? 0 : lineStart + 1;
  }

  // 通用块切分：按 BEGIN/END 标记，返回每个块内部文本（不含标记行）。高容错。
  function pwTpExtractBlocks(text, kind /* 'module' | 'summary' */) {
    const beginNorm = PW_TP_BLOCK_BEGIN[kind];
    const endNorm = PW_TP_BLOCK_END[kind];
    const src = String(text || '');
    const lines = src.split(/\r?\n/);
    const blocks = [];
    let cur = null; // 当前块的行缓冲
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const m = line.match(PW_TP_TAG_LINE_RE);
      const norm = m ? pwTpNormalizeKey((m[1] || m[2] || '').trim()) : '';
      if (norm === beginNorm) {
        // 开始一个新块（若上一个块未闭合，也先收掉，容错）
        if (cur !== null) blocks.push(cur.join('\n'));
        cur = [];
        continue;
      }
      if (norm === endNorm) {
        if (cur !== null) { blocks.push(cur.join('\n')); cur = null; }
        continue;
      }
      if (cur !== null) cur.push(line);
    }
    // 块未显式闭合也收掉（容错：模型漏写结束标记）
    if (cur !== null && cur.length) blocks.push(cur.join('\n'));
    return blocks;
  }

  // 把块标记行从文本中剔除，得到"顶层"部分（用于顶层标量解析）
  function pwTpStripBlocks(text) {
    const src = String(text || '');
    const lines = src.split(/\r?\n/);
    const out = [];
    let depth = 0;
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const m = line.match(PW_TP_TAG_LINE_RE);
      const norm = m ? pwTpNormalizeKey((m[1] || m[2] || '').trim()) : '';
      if (norm === PW_TP_BLOCK_BEGIN.module || norm === PW_TP_BLOCK_BEGIN.summary) { depth++; continue; }
      if (norm === PW_TP_BLOCK_END.module || norm === PW_TP_BLOCK_END.summary) { if (depth > 0) depth--; continue; }
      if (depth === 0) out.push(line);
    }
    return out.join('\n');
  }

  // 仅当整段输出被一对代码围栏包裹时，才剥掉首尾的围栏行。
  // 不再用贪婪的“首对反引号之间”捕获，避免正文里偶发的 ``` 把后续内容（整块模块/摘要）误删。
  function pwTpStripFence(text) {
    const raw = String(text || '');
    const lines = raw.split(/\r?\n/);
    // 找到第一行非空行与最后一行非空行
    let first = 0;
    while (first < lines.length && lines[first].trim() === '') first++;
    let last = lines.length - 1;
    while (last >= 0 && lines[last].trim() === '') last--;
    if (first > last) return raw;
    const isFenceLine = (s) => /^[ \t]*`{3,}[a-zA-Z]*[ \t]*$/.test(s);
    // 只有首尾都是围栏行时，才认为是“整段被围栏包裹”，剥掉这两行
    if (isFenceLine(lines[first]) && last > first && isFenceLine(lines[last])) {
      return lines.slice(first + 1, last).join('\n');
    }
    return raw;
  }

  // 顶层文本协议解析：返回与 JSON 等价的对象
  // 适用于 pwGenerateStep（整轮）/ pwAdvanceMultipleModules（多条推进）的输出
  function pwParseTextProtocolWorld(text) {
    const raw = String(text || '');
    if (!raw.trim()) throw new Error('AI 返回空内容');

    // 去掉可能的代码围栏（仅当整段被围栏包裹时）
    const body = pwTpStripFence(raw);

    // 先提取 module/summary 块，并把它们从主体里挖空，
    // 避免它们内部的字段干扰顶层标量解析
    const moduleBlocks = pwTpExtractBlocks(body, 'module');
    const summaryBlocks = pwTpExtractBlocks(body, 'summary');

    const topPart = pwTpStripBlocks(body);

    const top = pwTpParseBlock(topPart);

    const modules = moduleBlocks.map((b, i) => {
      const o = pwTpParseBlock(b);
      return {
        id: o.id || `module_${i + 1}`,
        type: o.type || 'other',
        title: o.title || `后台镜头 ${i + 1}`,
        perspective: o.perspective || '',
        role_audit: o.role_audit || '',
        detail: o.detail || '',
        summary: o.summary || '',
        independence: o.independence || '',
        mainline_impact: o.mainline_impact || '暂无直接影响',
        impact_level: o.impact_level || 'none',
        required_mainline_insertion: o.required_mainline_insertion || '',
        progress_enabled: pwTpToBool(o.progress_enabled),
        progress: pwTpToNumber(o.progress),
        progress_note: o.progress_note || '',
        current_location: o.current_location || '',
        current_state: o.current_state || '',
        next_tendency: o.next_tendency || '',
        danger_level: o.danger_level || 'none',
      };
    });

    const moduleSummaries = summaryBlocks.map((b, i) => {
      const o = pwTpParseBlock(b);
      return {
        id: o.id || modules[i]?.id || `summary_${i + 1}`,
        type: o.type || modules[i]?.type || 'other',
        title: o.title || modules[i]?.title || `后台摘要 ${i + 1}`,
        time: o.time || '',
        summary: o.summary || '',
        impact_level: o.impact_level || 'none',
        progress_enabled: pwTpToBool(o.progress_enabled),
        progress: pwTpToNumber(o.progress),
        progress_note: o.progress_note || '',
        impact_to_main: o.impact_to_main || o.mainline_impact || '暂无直接影响',
        required_mainline_insertion: o.required_mainline_insertion || '',
      };
    });

    if (!modules.length) {
      throw new Error('文本协议未解析到任何模块块（缺少 #模块开始 ... #模块结束 包裹）');
    }

    return {
      world_clock: top.world_clock || '',
      global_state: {
        title: top.global_title || '当前世界状态',
        detail: top.global_detail || '',
      },
      modules,
      inject_summary: {
        global_summary: top.global_summary || '',
        module_summaries: moduleSummaries.length ? moduleSummaries : modules.map(m => ({
          id: m.id, type: m.type, title: m.title, summary: m.summary,
          impact_level: m.impact_level, impact_to_main: m.mainline_impact,
          required_mainline_insertion: m.required_mainline_insertion,
          progress_enabled: m.progress_enabled, progress: m.progress, progress_note: m.progress_note,
        })),
      },
    };
  }

  // 摘要-only 文本协议解析（用于 pwSummarize 重压缩摘要）
  function pwParseTextProtocolSummary(text) {
    const raw = String(text || '');
    if (!raw.trim()) throw new Error('AI 返回空内容');
    const body = pwTpStripFence(raw);

    const summaryBlocks = pwTpExtractBlocks(body, 'summary');
    const topPart = pwTpStripBlocks(body);
    const top = pwTpParseBlock(topPart);

    const moduleSummaries = summaryBlocks.map((b, i) => {
      const o = pwTpParseBlock(b);
      return {
        id: o.id || `summary_${i + 1}`,
        type: o.type || 'other',
        title: o.title || `后台摘要 ${i + 1}`,
        time: o.time || '',
        summary: o.summary || '',
        impact_level: o.impact_level || 'none',
        impact_to_main: o.impact_to_main || '暂无直接影响',
        required_mainline_insertion: o.required_mainline_insertion || '',
      };
    });

    return {
      global_summary: top.global_summary || '',
      module_summaries: moduleSummaries,
    };
  }

  // 选模块阶段（pwSelectModulesToAdvance）解析
  function pwParseTextProtocolSelect(text) {
    const raw = String(text || '');
    const body = pwTpStripFence(raw);
    const top = pwTpParseBlock(body);
    let ids = [];
    const rawIds = top.selected_ids || '';
    if (rawIds) {
      // 支持 JSON 数组、逗号、换行、顿号、分号分隔
      try {
        const parsed = JSON.parse(rawIds);
        if (Array.isArray(parsed)) ids = parsed.map(x => String(x).trim());
      } catch {}
      if (!ids.length) {
        ids = rawIds
          .split(/[,，;；、\n\r]+/)
          .map(x => x.replace(/^[\-•·\*\d\.\s\[\]"'`]+|[\s\[\]"'`]+$/g, '').trim())
          .filter(Boolean);
      }
    }
    return {
      selected_ids: ids,
      reason: top.reason || '',
    };
  }

  // 统一入口：先尝试文本协议，失败再回退到 JSON 提取，确保兼容性
  function pwParseWorldOutput(text) {
    try { return pwParseTextProtocolWorld(text); } catch (e) {
      log('[平行世界] 文本协议解析失败，回退尝试 JSON 解析：', e?.message || e);
      return pwExtractJson(text);
    }
  }
  function pwParseSummaryOutput(text) {
    try { return pwParseTextProtocolSummary(text); } catch (e) {
      log('[平行世界·摘要] 文本协议解析失败，回退尝试 JSON 解析：', e?.message || e);
      return pwExtractJson(text);
    }
  }
  function pwParseSelectOutput(text) {
    try {
      const r = pwParseTextProtocolSelect(text);
      if (r.selected_ids && r.selected_ids.length) return r;
      // selected_ids 为空也允许：但确认确实是文本协议格式（含 # 标签 或 旧 <<< 标签）
      if (/^[ \t]*(?:#{1,3}[ \t]*[^\r\n#<>]+|<{2,}[ \t]*[^\r\n<>]+[ \t]*>{2,})[ \t]*$/m.test(String(text || ''))) return r;
      throw new Error('文本协议无 selected_ids 标签');
    } catch (e) {
      log('[平行世界·选模块] 文本协议解析失败，回退尝试 JSON 解析：', e?.message || e);
      try { return pwExtractJson(text); } catch { return { selected_ids: [], reason: '' }; }
    }
  }

  function pwNormalizeWorldResult(obj, oldData) {
    const now = new Date().toISOString();
    const old = oldData || pwLoadData();

    const modules = Array.isArray(obj.modules) ? obj.modules : [];
    const injectObj = obj.inject_summary || obj.inject || {};

    const normalizedModules = modules.map((m, i) => ({
      id: String(m.id || `module_${i + 1}`),
      type: String(m.type || 'other'),
      title: String(m.title || `后台镜头 ${i + 1}`),
      roleAudit: String(m.role_audit || m.roleAudit || ''),
      detail: String(m.detail || m.content || ''),
      summary: String(m.summary || ''),
      independence: String(m.independence || ''),
      mainlineImpact: String(m.mainline_impact || m.mainlineImpact || '暂无直接影响'),
      impactLevel: pwNormalizeImpactLevel(m.impact_level || m.impactLevel || m.danger_level || m.dangerLevel || 'none', 'none'),
      requiredMainlineInsertion: String(m.required_mainline_insertion || m.requiredMainlineInsertion || ''),
      progressEnabled: m.progress_enabled === true || m.progressEnabled === true,
      progress: pwClampProgress(m.progress ?? m.progress_percent ?? m.progressPercent ?? 0),
      progressNote: String(m.progress_note || m.progressNote || ''),
      perspective: String(m.perspective || m.viewpoint || m.point_of_view || ''),
      currentLocation: String(m.current_location || m.currentLocation || ''),
      currentState: String(m.current_state || m.currentState || ''),
      nextTendency: String(m.next_tendency || m.nextTendency || ''),
      dangerLevel: String(m.danger_level || m.dangerLevel || ''),
      updatedAt: now,
    }));

    const moduleMap = new Map(normalizedModules.map(m => [m.id, m]));

    const rawSummaries = Array.isArray(injectObj.module_summaries)
      ? injectObj.module_summaries
      : normalizedModules.map(m => ({
        id: m.id,
        type: m.type,
        title: m.title,
        summary: m.summary,
        impact_level: m.impactLevel || m.dangerLevel || 'none',
        impact_to_main: m.mainlineImpact,
        required_mainline_insertion: m.requiredMainlineInsertion,
      }));

    const moduleSummaries = rawSummaries.map((s, i) => {
      const id = String(s.id || normalizedModules[i]?.id || `summary_${i + 1}`);
      const mod = moduleMap.get(id) || normalizedModules[i] || {};

      return {
        id,
        type: String(s.type || mod.type || 'other'),
        title: String(s.title || mod.title || `后台摘要 ${i + 1}`),
        summary: String(s.summary || mod.summary || ''),
        impactLevel: pwNormalizeImpactLevel(s.impact_level || s.impactLevel || mod.impactLevel || mod.dangerLevel || 'none', 'none'),
        impactToMain: String(s.impact_to_main || s.impactToMain || mod.mainlineImpact || '暂无直接影响'),
        requiredMainlineInsertion: String(s.required_mainline_insertion || s.requiredMainlineInsertion || mod.requiredMainlineInsertion || ''),
        progressEnabled: s.progress_enabled === true || s.progressEnabled === true || mod.progressEnabled === true,
        progress: pwClampProgress(s.progress ?? s.progress_percent ?? s.progressPercent ?? mod.progress ?? 0),
        progressNote: String(s.progress_note || s.progressNote || mod.progressNote || ''),
        dangerLevel: pwNormalizeImpactLevel(s.danger_level || s.dangerLevel || mod.dangerLevel || '', ''),
        time: String(s.time || ''),
      };
    });

    return {
      version: 2,
      cleared: false,
      turn: Number(old.turn || 0) + 1,
      worldClock: String(obj.world_clock || obj.worldClock || `主线最新事件后的后台第 ${Number(old.turn || 0) + 1} 轮`),
      globalState: {
        title: String(obj.global_state?.title || obj.globalTitle || '当前世界状态'),
        // ✅ 兜底链里禁止把 obj.global_state（一个对象）丢给 String()——
        //    那样会得到 "[object Object]" 显示在面板下拉栏。
        //    只接受字符串字段，object 全部跳过。
        detail: String(
          (typeof obj.global_state?.detail === 'string' ? obj.global_state.detail : '') ||
          (typeof obj.globalDetail === 'string' ? obj.globalDetail : '') ||
          (typeof obj.global_state === 'string' ? obj.global_state : '') ||
          ''
        ),
      },
      modules: normalizedModules,
      inject: {
        global_summary: String(injectObj.global_summary || obj.global_summary || ''),
        module_summaries: moduleSummaries,
        manual_text: old.inject?.manual_text || '',
      },
      raw: obj,
      updatedAt: now,
    };
  }


  function pwNormalizeSummaryResult(obj, data) {
    const now = new Date().toISOString();

    const summaries = Array.isArray(obj.module_summaries)
      ? obj.module_summaries
      : Array.isArray(obj.modules)
        ? obj.modules
        : [];

    const moduleLookup = new Map(
      (data.modules || []).map(m => [String(m.id || ''), m])
    );

    const normalized = summaries.map((m, i) => {
      const id = String(m.id || data.modules?.[i]?.id || `summary_${i + 1}`);
      const oldModule = moduleLookup.get(id) || data.modules?.[i] || {};

      return {
        id,
        type: String(m.type || oldModule.type || 'other'),
        title: String(m.title || oldModule.title || `后台摘要 ${i + 1}`),
        summary: String(m.summary || m.content || ''),
        impactToMain: String(m.impact_to_main || m.impactToMain || m.mainlineImpact || oldModule.mainlineImpact || '暂无直接影响'),
        impactLevel: pwNormalizeImpactLevel(m.impact_level || m.impactLevel || oldModule.impactLevel || oldModule.dangerLevel || 'none', 'none'),
        requiredMainlineInsertion: String(m.required_mainline_insertion || m.requiredMainlineInsertion || oldModule.requiredMainlineInsertion || ''),
        progressEnabled: m.progress_enabled === true || m.progressEnabled === true || oldModule.progressEnabled === true,
        progress: pwClampProgress(m.progress ?? m.progress_percent ?? m.progressPercent ?? oldModule.progress ?? 0),
        progressNote: String(m.progress_note || m.progressNote || oldModule.progressNote || ''),
        dangerLevel: pwNormalizeImpactLevel(m.danger_level || m.dangerLevel || oldModule.dangerLevel || '', ''),
        time: String(m.time || data.worldClock || ''),
      };
    });

    const map = new Map(normalized.map(x => [x.id, x]));

    return {
      ...data,
      cleared: false,
      modules: (data.modules || []).map(m => {
        const s = map.get(m.id);
        if (!s) return m;

        return {
          ...m,
          summary: s.summary || m.summary,
          mainlineImpact: s.impactToMain || m.mainlineImpact,
          impactLevel: pwNormalizeImpactLevel(s.impactLevel || m.impactLevel || 'none', 'none'),
          requiredMainlineInsertion: s.requiredMainlineInsertion || m.requiredMainlineInsertion,
          progressEnabled: s.progressEnabled === true || m.progressEnabled === true,
          progress: pwClampProgress(s.progress ?? m.progress ?? 0),
          progressNote: s.progressNote || m.progressNote || '',
          updatedAt: now,
        };
      }),
      inject: {
        global_summary: String(obj.global_summary || obj.globalSummary || ''),
        module_summaries: normalized,
        manual_text: data.inject?.manual_text || '',
      },
      updatedAt: now,
    };
  }


  function pwPreviousStateForPrompt(data = pwLoadData()) {
    return JSON.stringify({
      turn: data.turn || 0,
      worldClock: data.worldClock || '',
      globalState: data.globalState || {},
      modules: (data.modules || []).map(m => ({
        id: m.id,
        type: m.type,
        title: m.title,
        roleAudit: pwClip(m.roleAudit, 700),
        detail: pwClip(m.detail, 1200),
        summary: pwClip(m.summary, 400),
        currentLocation: m.currentLocation,
        currentState: m.currentState,
        nextTendency: m.nextTendency,
        mainlineImpact: m.mainlineImpact,
        impactLevel: m.impactLevel,
        requiredMainlineInsertion: m.requiredMainlineInsertion,
        progressEnabled: m.progressEnabled,
        progress: m.progress,
        progressNote: m.progressNote,
      })),
    }, null, 2);
  }

  function pwBuildCustomApi() {
    const c = pwState.config || pwLoadConfig();

    if (c.apiType !== 'custom') return null;

    const ca = c.customApi || {};

    // 🦊 与狐裁/狐忆/狐搜同款守卫：自定义 API 必须提供 apiurl 或 proxyPreset，
    //    否则宿主 generateRaw 不会把 chat_completion_source 切到 'custom'，
    //    只填模型名会被静默忽略 → 平行世界仍走主模型（本次修复的 BUG 根因）。
    if (!ca.apiurl && !ca.proxyPreset) return null;

    const customApi = {
      source: ca.source || 'openai',
    };

    if (ca.proxyPreset) {
      customApi.proxy_preset = ca.proxyPreset;
    } else {
      if (ca.apiurl) customApi.apiurl = ca.apiurl;
      if (ca.key) customApi.key = ca.key;
    }

    if (ca.model) customApi.model = ca.model;

    if (ca.temperature !== '' && !isNaN(parseFloat(ca.temperature))) {
      customApi.temperature = parseFloat(ca.temperature);
    }

    if (ca.max_tokens !== '' && !isNaN(parseInt(ca.max_tokens))) {
      customApi.max_tokens = parseInt(ca.max_tokens);
    }

    if (ca.top_p !== '' && !isNaN(parseFloat(ca.top_p))) {
      customApi.top_p = parseFloat(ca.top_p);
    }

    if (ca.frequency_penalty !== '' && !isNaN(parseFloat(ca.frequency_penalty))) {
      customApi.frequency_penalty = parseFloat(ca.frequency_penalty);
    }

    if (ca.presence_penalty !== '' && !isNaN(parseFloat(ca.presence_penalty))) {
      customApi.presence_penalty = parseFloat(ca.presence_penalty);
    }

    return customApi;
  }

  // 🦊 平行世界附加参数：根据 c.customApi 中的 YAML 文本构建 fetch hook inject。
  //    仅在 apiType === 'custom' 时生效，避免误污染主模型请求。
  function pwBuildExtraInject() {
    const c = pwState.config || pwLoadConfig();
    if (c.apiType !== 'custom') return null;
    return ssBuildExtraInjectFromCustomApi(c.customApi || {});
  }

  // 🏷️ 平行世界固定上下文构建：
  // - 启用标签过滤时（enableContentFilter !== false）：复用狐构/狐忆同款
  //   ssBuildFilteredChatHistoryPromptsForAnalysis，把 chat_history 展开成已过滤掉指定标签内容的
  //   逐楼 message prompts。即使 includeTagPairs/excludeTagPairs 都是空数组也走过滤路径，
  //   ssFilterByTagPairs 在两者都空时等价于"读取全文"，行为可预期。
  // - 关闭标签过滤时：仍然走原生 'chat_history'，由酒馆自己处理。
  //
  // ⚠️ 注：标签过滤启用时，host 的 max_chat_history 不再生效（chat_history token 没了）。
  //   楼层数量改由 pwResolveChatHistoryLimit() 映射到 contextFloors 控制，最近 N 楼的语义略有
  //   差异：host 的 max_chat_history 按 user/assistant 配对计数；contextFloors 按总楼层计数。
  function pwBuildContextOrderedPrompts() {
    const cfg = pwState.config || pwLoadConfig();

    const fixedHead = [
      'char_description',
      'char_personality',
      'scenario',
      'persona_description',
      'world_info_before',
      'world_info_after',
    ];

    const enabled = cfg.enableContentFilter !== false;

    if (!enabled) {
      return [...fixedHead, 'chat_history'];
    }

    // 把 pwResolveChatHistoryLimit 的 'all' 或正整数映射到 contextFloors（0=全部）
    const limit = pwResolveChatHistoryLimit();
    const contextFloors = (limit === 'all' || !Number.isFinite(limit) || limit <= 0) ? 0 : limit;

    try {
      const filtered = ssBuildFilteredChatHistoryPromptsForAnalysis({
