  async function pwRunCycle(auto = false) {
    if (pwState.running || ssIsTaskRunning('parallel_world')) {
      // ✅ Toast 中止时，直接调 ssCancelTask。
      // 任务内部会在 finally 里把 pwState.running / pwState.status 复位。
      ssCancelTask('parallel_world', '平行世界');
      return;
    }

    if (!pwGuardChatReady()) return;

    pwReadConfigFromPanel();

    pwState.running = true;
    pwUpdateRunButton();

    ssStartTask('parallel_world', '平行世界');

    let taskToast = null;

    try {
      taskToast = ssTaskToast(
        'parallel_world',
        '🌌 平行世界更新中：点击中断可立即停止后台生成与摘要生成。'
      );
    } catch { }

    // ✅ 立即在状态栏写正在运行，避免用户以为没反应
    pwSetStatus(auto ? '自动推进中：正在生成平行世界后台正文……' : '生成中：正在生成平行世界后台正文……');
    pwUpdateRunButton();

    try {
      pwSetStatus(auto ? '自动推进中：正在生成平行世界正文 + 主线注入摘要……' : '生成中：正在生成平行世界正文 + 主线注入摘要……');

      const fullData = await pwGenerateStep(auto);

      // ✅ 一次性注入门闩：本次更新后，仅注入到接下来"下一楼"那一次主线请求，不再持续注入
      if (!fullData.inject) fullData.inject = { global_summary: '', module_summaries: [], manual_text: '' };
      fullData.inject.consumed = false;

      pwSaveData(fullData);
      pwRenderPanel();
      pwRenderStateFloat();

      pwSetStatus(`完成：第 ${fullData.turn} 轮后台世界已更新，并已生成主线注入摘要`);
      toast('✅ 平行世界已更新：本次为一次请求，已同时生成后台正文与主线摘要', 'success');

      // ✅ 自动模式下，刷新自动模式计数锚点，避免主回复计数被错位清零
      if (auto) {
        pwState.autoCounter = 0;
        pwState.lastAutoMessageId = getCurrentLastMessageId();
      }
    } catch (e) {
      const msg = e?.message || String(e || '');

      if (/abort|aborted|cancel|中断|取消/i.test(msg)) {
        pwState.running = false;
        pwSetStatus('已中断');
        pwUpdateRunButton();
        toast('⛔ 平行世界已中断', 'warning');
      } else {
        pwState.running = false;
        pwSetStatus(`失败：${msg}`);
        pwUpdateRunButton();
        log('[平行世界] 生成失败', e);
        toast(`❌ 平行世界生成失败：${msg}`, 'error');
      }
    } finally {

      try { taskToast?.remove?.(); } catch { }

      pwState.running = false;
      ssEndTask('parallel_world');
      pwUpdateRunButton();
    }
  }


