        throw new Error('AI 没有返回有效的 module 字段');
      }

      // ✅ merge 而不是整体替换：保留旧字段做兜底，避免 AI 漏返回字段时清空历史
      data.worldClock = normalized.worldClock || data.worldClock;
      data.modules = (data.modules || []).map(m => {
        if (String(m.id) !== targetId) return m;
        return pwMergeModuleUpdate(m, newModule);
      });

      if (!data.inject) {
        data.inject = { global_summary: '', module_summaries: [], manual_text: '' };
      }

      const oldSummaries = Array.isArray(data.inject.module_summaries) ? data.inject.module_summaries : [];
      const idx = oldSummaries.findIndex(s => String(s.id) === targetId);

      if (newSummary) {
        const oldS = idx >= 0 ? oldSummaries[idx] : null;
        const merged = pwMergeSummaryUpdate(oldS, newSummary);
        merged.id = targetId;
        if (idx >= 0) {
          oldSummaries[idx] = merged;
        } else {
          oldSummaries.push(merged);
        }
        data.inject.module_summaries = oldSummaries;
      }

      data.updatedAt = new Date().toISOString();
      // 单条推进不动整体 turn

      if (!data.inject) data.inject = { global_summary: '', module_summaries: [], manual_text: '' };
      data.inject.consumed = false;

      pwSaveData(data);
      try { pwRenderPanel?.(); } catch { }
      try { pwRenderStateFloat?.(); } catch { }

      pwSetStatus?.(`单条推进完成：${newModule.title || target.title}`);
      toast(`✅ 已单独推进事件：${newModule.title || target.title}`, 'success');
    } catch (e) {
      const msg = e?.message || String(e || '');
      if (/abort|aborted|cancel|中断|取消/i.test(msg)) {
        pwSetStatus?.('已中断');
        toast('⛔ 单条推进已中断', 'warning');
      } else {
        pwSetStatus?.(`单条推进失败：${msg}`);
        log('[平行世界] 单条推进失败', e);
        toast(`❌ 单条推进失败：${msg}`, 'error');
      }
    } finally {
      try { taskToast?.remove?.(); } catch { }
      pwState.singleRunning = false;
      ssEndTask('parallel_world_single');
    }
  }


  // ==================== 🌌 双阶段动态推进 ====================
  // 阶段 2-A：让 AI 根据当前主线上下文 + 已有平行世界事件，判断哪几个模块需要推进。
