    const text = await pwGenerateRaw({
      user_input: '',
      should_silence: true,
      should_stream: false,
      max_chat_history: pwResolveChatHistoryLimit(),
      ordered_prompts: [
        { role: 'system', content: preContextPrompt },

        ...pwBuildContextOrderedPrompts(),

        { role: 'system', content: finalPrompt },
      ],
    });

    const parsed = pwParseWorldOutput(text);

    // 兼容文本协议：module_summaries 解析后位于 parsed.inject_summary.module_summaries；
    // 同时兼容旧 JSON 顶层字段。
    const parsedModuleSummaries = Array.isArray(parsed.inject_summary?.module_summaries)
      ? parsed.inject_summary.module_summaries
      : (Array.isArray(parsed.module_summaries) ? parsed.module_summaries : []);

    // 复用整轮归一化：让 AI 返回的 modules 走一遍统一字段化
    const fakeWhole = {
      world_clock: parsed.world_clock || parsed.worldClock || data.worldClock || '',
      global_state: { title: data.globalState?.title || '', detail: data.globalState?.detail || '' },
      modules: Array.isArray(parsed.modules) ? parsed.modules : [],
      inject_summary: {
        global_summary: data.inject?.global_summary || '',
        module_summaries: parsedModuleSummaries,
      },
    };

    // 不增加 turn：使用临时 oldData，让 normalize 出来的 turn 抛弃
    const tmpOld = { ...data, turn: (data.turn || 0) - 1 < 0 ? 0 : (data.turn || 0) };
    const normalized = pwNormalizeWorldResult(fakeWhole, tmpOld);

    const newModulesMap = new Map((normalized.modules || []).map(m => [String(m.id), m]));
    const newSummariesMap = new Map((normalized.inject?.module_summaries || []).map(s => [String(s.id), s]));

    // ✅ 把更新后的模块/摘要 merge 回原 data，其它模块原样保留。
    //    用 merge 而不是整体替换，避免 AI 漏返回字段时清空历史。
    data.worldClock = normalized.worldClock || data.worldClock;
    data.modules = (data.modules || []).map(m => {
      const nm = newModulesMap.get(String(m.id));
      if (!nm) return m;
      return pwMergeModuleUpdate(m, nm);
    });

    if (!data.inject) {
      data.inject = { global_summary: '', module_summaries: [], manual_text: '' };
    }

    const oldSummaries = Array.isArray(data.inject.module_summaries) ? data.inject.module_summaries : [];
    const oldSumMap = new Map(oldSummaries.map(s => [String(s.id), s]));

    for (const id of ids) {
      const ns = newSummariesMap.get(id);
      if (!ns) continue;
      const merged = pwMergeSummaryUpdate(oldSumMap.get(id), ns);
      merged.id = id;
      oldSumMap.set(id, merged);
    }

    data.inject.module_summaries = Array.from(oldSumMap.values());
    data.updatedAt = new Date().toISOString();

    return data;
  }

  // 阶段 2 总入口：判断 + 一次性推进选中模块。
  async function pwRunDynamicCycle(auto = false) {
    if (pwState.running || ssIsTaskRunning('parallel_world')) {
      ssCancelTask('parallel_world', '平行世界');
      return;
    }

    if (!pwGuardChatReady()) return;

    pwReadConfigFromPanel?.();
    pwState.config = pwLoadConfig();

    const data = pwLoadData();
    const modules = Array.isArray(data.modules) ? data.modules : [];

    if (!modules.length) {
      toast('⚠️ 当前还没有平行世界事件，请先点"推进所有事件"做初始化', 'warning');
      return;
    }

    pwState.running = true;
    pwUpdateRunButton?.();
    ssStartTask('parallel_world', '平行世界');

    let taskToast = null;
    try {
      taskToast = ssTaskToast(
        'parallel_world',
        auto
          ? '⚡ 动态推进中……点击中断'
          : '⚡ 动态推进中……点击中断'
      );
    } catch { }

    pwSetStatus(auto ? '动态推进中：正在判断需要推进哪些事件……' : '动态推进中：正在判断需要推进哪些事件……');

    try {
      // 阶段 2-A：选模块
      const selectedIds = await pwSelectModulesToAdvance(data);

      if (!selectedIds.length) {
        pwSetStatus('动态推进完成：本次没有事件需要推进');
        toast('✅ 动态推进：AI 判断本次无事件需要推进', 'success');
        return;
      }

      // 阶段 2-B：推进选中模块
      pwSetStatus(`动态推进中：正在更新 ${selectedIds.length} 个事件……`);

      const newData = await pwAdvanceMultipleModules(data, selectedIds);

      if (!newData.inject) newData.inject = { global_summary: '', module_summaries: [], manual_text: '' };
      newData.inject.consumed = false;

      pwSaveData(newData);
      try { pwRenderPanel?.(); } catch { }
      try { pwRenderStateFloat?.(); } catch { }

      pwSetStatus(`动态推进完成：已更新 ${selectedIds.length} 个事件`);
      toast(`✅ 动态推进完成：已更新 ${selectedIds.length} 个事件`, 'success');

      if (auto) {
        pwState.autoCounter = 0;
        pwState.lastAutoMessageId = getCurrentLastMessageId();
      }
    } catch (e) {
      const msg = e?.message || String(e || '');

      if (/abort|aborted|cancel|中断|取消/i.test(msg)) {
        pwSetStatus('已中断');
        toast('⛔ 动态推进已中断', 'warning');
      } else {
        pwSetStatus(`动态推进失败：${msg}`);
        log('[平行世界·动态推进] 失败', e);
        toast(`❌ 动态推进失败：${msg}`, 'error');
      }
    } finally {
      try { taskToast?.remove?.(); } catch { }
      pwState.running = false;
      ssEndTask('parallel_world');
      pwUpdateRunButton?.();
    }
  }

  // 自动推进入口：按 advanceMode 分流
  // - two_phase  → 走动态推进；前提是已经有事件，否则回退一次整轮初始化
  // - legacy_full → 走整轮推进
  async function pwRunAutoAdvance() {
    pwState.config = pwLoadConfig();
    const mode = pwState.config?.advanceMode === 'legacy_full' ? 'legacy_full' : 'two_phase';

    if (mode === 'legacy_full') {
      return pwRunCycle(true);
    }

    // two_phase：如果还没有任何模块，回退到整轮做一次初始化
    const data = pwLoadData();
    if (!Array.isArray(data.modules) || !data.modules.length) {
      log('[平行世界·自动推进] 双阶段模式但无模块，回退一次整轮初始化');
      return pwRunCycle(true);
    }

    return pwRunDynamicCycle(true);
  }


  function pwBuildInjectPlainText() {
    const data = pwLoadData();

    if (!pwHasContent(data)) return '';

    const cfg = pwState.config || pwLoadConfig();
    const inject = data.inject || {};

    if (inject.manual_text?.trim()) {
      return inject.manual_text.trim();
    }

    let summaries = Array.isArray(inject.module_summaries) ? inject.module_summaries : [];

    if (!summaries.length && Array.isArray(data.modules) && data.modules.length) {
      summaries = data.modules.map(m => ({
        id: m.id,
        type: m.type,
        title: m.title,
        time: data.worldClock || '',
        summary: m.summary?.trim()
          ? m.summary.trim()
          : pwClip(m.detail || '', pwSummaryRangeMaxChars(cfg)),
        impactToMain: m.mainlineImpact || '暂无直接影响',
        impactLevel: m.impactLevel || m.dangerLevel || 'none',
        requiredMainlineInsertion: m.requiredMainlineInsertion || '',
        progressEnabled: m.progressEnabled,
        progress: m.progress,
        progressNote: m.progressNote,
        dangerLevel: m.dangerLevel || '',
      }));
    }

    const moduleLookup = new Map(
      (data.modules || []).map(m => [String(m.id || ''), m])
    );

    summaries = summaries.map(s => {
      const old = moduleLookup.get(String(s.id || '')) || {};

      const merged = {
        ...s,
        impactToMain: s.impactToMain || s.impact_to_main || old.mainlineImpact || '暂无直接影响',
        impactLevel: pwNormalizeImpactLevel(s.impactLevel || s.impact_level || old.impactLevel || old.dangerLevel || 'none', 'none'),
        requiredMainlineInsertion: s.requiredMainlineInsertion || s.required_mainline_insertion || old.requiredMainlineInsertion || '',
        progressEnabled: s.progressEnabled === true || s.progress_enabled === true || old.progressEnabled === true,
        progress: pwClampProgress(s.progress ?? s.progress_percent ?? s.progressPercent ?? old.progress ?? 0),
        progressNote: s.progressNote || s.progress_note || old.progressNote || '',
        dangerLevel: pwNormalizeImpactLevel(s.dangerLevel || s.danger_level || old.dangerLevel || '', ''),
      };

      merged.effectiveImpactLevel = pwGetEffectiveImpactLevel(merged);

      return merged;
    });

    const maxModules = Math.max(1, Math.min(50, parseInt(cfg.maxInjectModules) || 10));
    const impactMode = cfg.impactMode || 'strong';

    const highAll = pwSortForInject(
      summaries.filter(m => ['high', 'critical'].includes(pwGetEffectiveImpactLevel(m)))
    );

    const midAll = pwSortForInject(
      summaries.filter(m => pwGetEffectiveImpactLevel(m) === 'mid')
    );

    const lowAll = pwSortForInject(
      summaries.filter(m => ['none', 'low'].includes(pwGetEffectiveImpactLevel(m)))
    );

    const high = highAll.slice(0, maxModules);
    const remainAfterHigh = Math.max(0, maxModules - high.length);
    const mid = midAll.slice(0, Math.ceil(remainAfterHigh * 0.58));
    const low = lowAll.slice(0, Math.max(0, remainAfterHigh - mid.length));

    const fmt = (m, i) => {
      const level = pwGetEffectiveImpactLevel(m);
      const showProgress = pwShouldShowProgress(m);
      const progress = pwClampProgress(m.progress);

      return `【${i + 1}. ${m.title || '未命名后台事件'}】
类型：${m.type || 'unknown'}
影响等级：${level}（${pwImpactLabel(level)}）
${showProgress ? `动态进度：${progress}%${m.progressNote ? `｜${m.progressNote}` : ''}` : '动态进度：无'}
时间：${m.time || data.worldClock || '未知'}
摘要：${String(m.summary || '').trim()}
对主线的自然影响：${String(m.impactToMain || '暂无直接影响').trim()}
必须插入主线的方式：${String(m.requiredMainlineInsertion || '无').trim()}`;
    };

    const lines = [];

    lines.push(`【平行世界注入执行规则】
这是主线之外的动态世界后台摘要。它不是装饰文本，也不是可有可无的背景设定。

${pwBuildImpactModeInstruction(impactMode)}

【防全知规则】
1. NPC 只能知道自己合理渠道能知道的信息。
2. 远方 NPC 不会凭空知道 user 的存在。
3. 不许让所有 NPC 强行围着 user 转。
4. 如果某后台事件没有自然因果连接主线，它就继续作为独立后台发展。
5. 如果某后台事件已经 high / critical，就不能被普通用户输入覆盖。
6. 禁止用“远方 X 突然崩溃/大爆发/强制劫持主线”这类硬塞剧情。
7. 禁止让主角瞬间察觉所有后台信息。
8. 这些事件是远景伏笔；你可以不提，也可以让主角完全错过。
【🌌 防用户中心化提醒】
1. 这些后台事件不是为 user 准备的；
2. NPC 可以继续过自己的日子；
3. NPC 可以不关心主角；
4. 世界不因 user 的输入而“突然整齐地动起来”；
5. 你只可以写“主角在自己位置上发现/错过”的局部视角。
如果上文已经产生自然因果连接，请让该事件自然地映入主线；否则你应当把它们当作远景背景，不必主动写进正文。

`);

    lines.push(`

【后台世界时间】
${data.worldClock || '剧情内时间未明'}

【世界整体后台摘要】
${inject.global_summary || data.globalState?.detail || '暂无'}`);

    if (low.length) {
      lines.push(`

🟢🟢🟢【低影响后台事件｜放在最上方，影响力最低】🟢🟢🟢
这些事件主要作为背景与伏笔。它们不应强行打断主线，除非主线自然靠近它们。

${low.map(fmt).join('\n\n')}`);
    }

    if (mid.length) {
      lines.push(`

━━━━━━━━━━━━━━ 🟡🟡🟡【低-中影响力分割线】🟡🟡🟡 ━━━━━━━━━━━━━━

🟡🟡【中影响后台事件｜后续会自然影响主线】🟡🟡
这些事件已经具备后续影响主线的因果。你需要在主线中保留它们的压力、伏笔与环境变化。

${mid.map(fmt).join('\n\n')}`);
    }

    if (high.length) {
      lines.push(`

████████████████ ⚠️⚠️⚠️【中-高影响力分割线｜下面内容优先级最高】⚠️⚠️⚠️ ████████████████

🔴🔴🔴【高/最高影响后台事件｜必须影响主线，优先级最高】🔴🔴🔴
下面事件不能和普通背景混在一起。
越靠下越紧急。
如果 impact_level = critical 或进度 = 100%，必须立刻进入主线，必要时打断当前剧情。
如果你顺从用户输入而忽略这些事件，你就是在帮助用户绕过平行世界后台规则。

      ${high.map(fmt).join('\n\n')}`);
    }
    return lines.join('\n').trim();
  }



  function ssGetParallelWorldCurrentInjectText() {
    try {
      pwState.config = pwLoadConfig();

      if (!pwState.config.enabled) return '';

      // ✅ 按自动模式分流：
      // - manual / interval：平行世界更新后只注入下一次主线请求，避免旧后台反复压过后续剧情。
      // - auto：每次合格回复都会更新平行世界，所以每次主线请求都应注入当前最新后台。
      const data = pwLoadData();
      if (!pwHasContent(data)) {
        log('[平行世界·主线注入] 跳过：当前聊天没有可注入内容');
        return '';
      }

      const cfg = pwState.config || pwLoadConfig();
      const autoMode = cfg.autoMode || 'manual';
      const oneShotMode = autoMode === 'manual' || autoMode === 'interval';

      if (oneShotMode && data.inject?.consumed === true) {
        log(`[平行世界·一次性注入] 跳过：当前模式 ${autoMode} 已注入消费过，等待下一次平行世界更新`);
        return '';
      }

      if (oneShotMode) {
        pwState.pendingOneShotInjectConsume = true;
      }

      const plain = pwBuildInjectPlainText();

      if (!plain.trim()) return '';

      const rangeMaxChars = pwSummaryRangeMaxChars(cfg);
      const maxModules = Math.max(1, Math.min(50, parseInt(cfg.maxInjectModules) || 10));
      const safetyMaxChars = Math.max(1500, Math.min(30000, rangeMaxChars * maxModules + 2600));
      const clipped = pwClip(plain, safetyMaxChars);

      return `<parallel_world>
【用户侧高优先级补充：平行世界后台摘要】
以下内容是主线之外正在独立发生的世界后台。主线 AI 必须读取其中的剧情内时间、地点、人物、事件、人物情绪、人物动机、关系变化、危险等级与对主线的影响路径。
如果其中存在 high 或 critical 事件，必须在后续主线中体现，甚至打断主线剧情，绝对不能被普通日常输入覆盖，必须体现！

${clipped}
</parallel_world>`;
    } catch (e) {
      log('[平行世界] 构建注入失败', e);
      return '';
    }
  }

  function pwGetAssistantTextForAutoCheck(messageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (!gcm) return '';

      const m = gcm(messageId, {
        hide_state: 'all',
        include_swipes: false,
      })?.[0];

      if (!m || m.role !== 'assistant') return '';

      let text = String(m.message || '').trim();

      try {
        text = ssCleanXuanhuInjectedBlocksFromMessage(text);
      } catch { }

      try {
        const filtered = foxMemoryFilterContent(text);
        if (filtered?.trim()) text = filtered.trim();
      } catch { }

      text = text
        .replace(/<[^>]+>/g, '')
        .replace(/\s+/g, '')
        .trim();

      return text;
    } catch {
      return '';
    }
  }

  function pwIsTruncatedMessage(messageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (!gcm) return false;

      const m = gcm(messageId, {
        hide_state: 'all',
        include_swipes: false,
      })?.[0];

      if (!m) return false;

      const raw = JSON.stringify({
        data: m.data || {},
        extra: m.extra || {},
        swipes_data: m.swipes_data || [],
        swipes_info: m.swipes_info || [],
      }).toLowerCase();

      if (raw.includes('"finish_reason":"length"')) return true;
      if (raw.includes('"finishreason":"length"')) return true;
      if (raw.includes('"stop_reason":"max_tokens"')) return true;
      if (raw.includes('"truncated":true')) return true;
      if (raw.includes('"is_truncated":true')) return true;

      return false;
    } catch {
      return false;
    }
  }

  function pwShouldAutoAdvance(messageId, type) {
    if (pwState.internalGenerating) return false;
    if (pwState.running || ssIsTaskRunning('parallel_world')) return false;

    // 🦊 reroll / swipe 保护：
    //   MESSAGE_RECEIVED 偶尔不会透传 type 参数（参数为 undefined / null / ''）。
    //   此时回退到 GENERATION_STARTED 抓到的 xhLastGenerationType，
    //   避免 reroll / swipe 被当成 'normal' 再触发一次平行世界推进。
    const effType = (type && typeof type === 'string')
      ? type
      : (xhGetLastGenerationType() || null);
    if (effType && effType !== 'normal') {
      log(`[平行世界自动推进] 跳过：非 normal 回复 type=${effType}${type ? '' : '（来自 GENERATION_STARTED 追踪）'}`);
      return false;
    }

    if (pwIsTruncatedMessage(messageId)) {
      log('[平行世界自动推进] 跳过：检测到截断');
      return false;
    }

    const text = pwGetAssistantTextForAutoCheck(messageId);

    if (!text.trim()) {
      log('[平行世界自动推进] 跳过：空回');
      return false;
    }

    if (text.length < 300) {
      log(`[平行世界自动推进] 跳过：低于 300 字，当前=${text.length}`);
      return false;
    }

    return true;
  }

  function pwRegisterAutoListener() {
    pwUnregisterAutoListener();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof eo !== 'function' || !te?.MESSAGE_RECEIVED) {
      log('[平行世界自动推进] 注册失败：缺少 MESSAGE_RECEIVED');
      return;
    }

    pwState.autoHandle = eo(te.MESSAGE_RECEIVED, (messageId, type) => {
      pwState.config = pwLoadConfig();

      const mode = pwState.config.autoMode || 'manual';

      if (mode === 'manual') return;

      // 🦊 reroll / swipe 保护：
      //   立即在 MESSAGE_RECEIVED 触发的"那一刻"快照当前生成类型，
      //   后续 setTimeout（默认 2600ms）期间 xhLastGenerationType 可能被脚本
      //   自己的 generateRaw（quiet）覆盖，所以必须先冻结。
      const snapshotType = (type && typeof type === 'string')
        ? type
        : (xhGetLastGenerationType() || null);

      setTimeout(() => {
        try {
          pwState.config = pwLoadConfig();

          const latestMode = pwState.config.autoMode || 'manual';
          if (latestMode === 'manual') return;

          // 防止同一条消息被重复触发
          const midKey = String(messageId ?? '');
          if (midKey && pwState.lastAutoMessageId === midKey) {
            log('[平行世界自动推进] 跳过：同一消息已处理');
            return;
          }

          // ✅ 所有自动模式都先走严格跳过检查：
          // - 非 normal，例如 roll / swipe / continue 等，跳过
          // - 截断，跳过
          // - 空回，跳过
          // - 正文不足 300 字，跳过
          if (!pwShouldAutoAdvance(messageId, snapshotType)) return;

          if (latestMode === 'auto') {
            pwState.lastAutoMessageId = midKey;
            toast('🌌 平行世界：检测到合格回复，开始自动推进……', 'info');
            xhEnqueueAutoTask(
              'parallel_world_auto_advance',
              '平行世界自动推进',
              () => pwRunAutoAdvance(),
              { dedupe: true }
            );
            return;
          }

          if (latestMode === 'interval') {
            const interval = Math.max(1, parseInt(pwState.config.autoInterval) || 5);
            const prevId = Number.isFinite(Number(pwState.lastAutoMessageId))
              ? Number(pwState.lastAutoMessageId)
              : -1;
            const currentId = Number(messageId);
            const floorDelta = currentId > prevId ? (currentId - prevId) : 0;
            pwState.autoCounter += Math.max(1, floorDelta);

            log(`[平行世界自动推进] 实际楼层计数：${pwState.autoCounter}/${interval}`);

            if (pwState.autoCounter >= interval) {
              pwState.autoCounter = 0;
              pwState.lastAutoMessageId = midKey;
              toast(`🌌 平行世界：已达到 ${interval} 个实际楼层，开始自动推进……`, 'info');
              xhEnqueueAutoTask(
                'parallel_world_auto_advance',
                '平行世界自动推进',
                () => pwRunAutoAdvance(),
                { dedupe: true }
              );
            }
          }
        } catch (e) {
          log('[平行世界自动推进] 检查失败', e);
        }
      }, Math.max(2600, parseInt(pwState.config.autoDelayMs) || 2600));
    });

    log('[平行世界自动推进] 已注册 MESSAGE_RECEIVED 监听');
  }
  function pwUnregisterAutoListener() {
    try { pwState.autoHandle?.stop?.(); } catch { }
    pwState.autoHandle = null;
  }

  function pwGetPresetOptionsHtml(selected) {
    try {
      const fn = getFn('getPresetNames');
      if (typeof fn !== 'function') return '<option value="">无可用预设</option>';

      const names = fn().filter(x => x !== 'in_use').sort();

      if (!names.length) return '<option value="">无可用预设</option>';

      return [
        '<option value="">使用内置提示词（推荐）</option>',
        ...names.map(n => `<option value="${escapeHtml(n)}" ${n === selected ? 'selected' : ''}>${escapeHtml(n)}</option>`),
      ].join('');
    } catch {
      return '<option value="">无可用预设</option>';
    }
  }

