  function pwRenderModulesHtml(data) {
    if (!pwHasContent(data)) {
      return `
<div class="pw-card pw-card-empty pw-card-impact-none">
  <div class="pw-meta"><span class="pw-chip">未启动</span></div>
  <h4>暂无平行世界数据</h4>
  <pre>当前平行世界为空。点击"推进所有事件"后，后台世界才会开始独立运转。</pre>
</div>`;
    }

    const globalHtml = `
<div class="pw-main-card">
  <div class="pw-meta">
    <span class="pw-chip">第 ${escapeHtml(data.turn || 0)} 轮</span>
    <span class="pw-chip">${escapeHtml(data.worldClock || '剧情内时间未明')}</span>
    ${data.updatedAt ? `<span class="pw-chip">更新：${escapeHtml(new Date(data.updatedAt).toLocaleString('zh-CN'))}</span>` : ''}
  </div>
  <h4>${escapeHtml(data.globalState?.title || '当前世界状态')}</h4>

  <details class="pw-card-details">
    <summary>世界整体状态</summary>
    <pre>${escapeHtml(data.globalState?.detail || '暂无')}</pre>
  </details>
</div>`;

    const modules = Array.isArray(data.modules) ? data.modules : [];

    if (!modules.length) {
      return `${globalHtml}
<div class="pw-card pw-card-empty pw-card-impact-none">
  <pre>暂无平行世界模块。</pre>
</div>`;
    }

    const cards = modules.map((m, index) => {
      const detailLength = String(m.detail || '').length;
      const auditLength = String(m.roleAudit || '').length;
      const summaryLength = String(m.summary || '').length;

      let sizeClass = 'pw-card-mid';

      if (detailLength > 900 || auditLength > 500) {
        sizeClass = 'pw-card-large';
      } else if (detailLength < 260 && summaryLength < 140) {
        sizeClass = 'pw-card-small';
      }

      const offsetClass = index % 5 === 1
        ? 'pw-card-offset-a'
        : index % 5 === 3
          ? 'pw-card-offset-b'
          : '';

      const effectiveLevel = pwGetEffectiveImpactLevel(m);
      const impactClass = pwImpactCardClass(m);
      const progressHtml = pwBuildProgressHtml(m);
      const moduleId = escapeHtml(m.id || '');

      return `
<div class="pw-card ${sizeClass} ${offsetClass} ${impactClass}">
  <div class="pw-card-topbar">
    <div class="pw-meta" style="margin-bottom:0;">
      <span class="pw-chip">${escapeHtml(m.type || 'other')}</span>
      <span class="pw-chip">影响：${escapeHtml(pwImpactLabel(effectiveLevel))}</span>
      ${m.perspective ? `<span class="pw-chip">视角：${escapeHtml(m.perspective)}</span>` : ''}
      ${m.currentLocation ? `<span class="pw-chip">${escapeHtml(m.currentLocation)}</span>` : ''}
    </div>
    <div class="pw-card-actions" style="display:flex;gap:6px;align-items:center;">
      <button type="button" class="pw-module-advance" data-pw-id="${moduleId}" title="只推进这个事件，不影响其他事件">▶ 推进</button>
      <button type="button" class="pw-module-delete" data-pw-id="${moduleId}" title="删除这个平行世界条目及对应摘要">🗑</button>
    </div>
  </div>

  <h4>${escapeHtml(m.title || '未命名模块')}</h4>

  ${progressHtml}

  ${m.detail ? `
  <div class="pw-meta">完整后台生成内容</div>
  <pre>${escapeHtml(m.detail)}</pre>` : ''}

  ${m.summary ? `
  <details class="pw-card-details">
    <summary>镜头摘要</summary>
    <pre>${escapeHtml(m.summary)}</pre>
  </details>` : ''}

  ${m.roleAudit ? `
  <details class="pw-card-details">
    <summary>人设审查结论</summary>
    <pre>${escapeHtml(m.roleAudit)}</pre>
  </details>` : ''}

  ${m.mainlineImpact ? `
  <details class="pw-card-details">
    <summary>对主线的自然影响</summary>
    <pre>${escapeHtml(m.mainlineImpact)}</pre>
  </details>` : ''}

  ${m.requiredMainlineInsertion ? `
  <details class="pw-card-details" open>
    <summary>必须插入主线</summary>
    <pre>${escapeHtml(m.requiredMainlineInsertion)}</pre>
  </details>` : ''}

  ${m.nextTendency ? `
  <details class="pw-card-details">
    <summary>下一步倾向</summary>
    <pre>${escapeHtml(m.nextTendency)}</pre>
  </details>` : ''}
</div>`;
    }).join('');

    return `${globalHtml}
<div class="pw-masonry">
${cards}
</div>`;
  }

  function pwOpenStateFloat() {
    pwInjectStyle();

    const old = topDoc.getElementById('pw-state-float');

    if (old) {
      old.remove();
      return;
    }

    const box = topDoc.createElement('div');
    box.id = 'pw-state-float';
