- 章节/段落之间的衔接要稳，人物口吻和文风必须与原文一致。`;
  }

  function novelBuildTailPrompt(polishMode) {
    if (polishMode) {
      return `你是狐神抚，你现在负责对用户提供的小说原文进行【润色】工作。
