// ============================================
// 🔄 自动刷新楼层
// 进入酒馆延迟刷新 + 生成结束后自动刷新
// ============================================

(function() {
    'use strict';

    const CONFIG = {
        INIT_DELAY: 2000,      // 进入酒馆后延迟刷新（毫秒）
        RESTORE_DELAY: 200,    // 生成结束后延迟刷新（毫秒）
    };

    const state = {
        eventHandles: [],
    };

    function log(...args) {
        console.log('[🔄自动刷新]', ...args);
    }

    function getCurrentLastMessageId() {
        try { return getLastMessageId?.() ?? -1; } catch { return -1; }
    }

    async function refreshCurrentFloor(messageId) {
        const id = messageId ?? getCurrentLastMessageId();
        if (id < 0) return;
        await setChatMessages([{ message_id: id }], { refresh: 'affected' });
        log('已刷新楼层:', id);
    }

    function onGenEnd() {
        log('生成结束，延迟刷新...');
        setTimeout(async () => {
            await refreshCurrentFloor();
        }, CONFIG.RESTORE_DELAY);
    }

    function bindEvents() {
        unbindEvents();
        const h = eventOn?.(tavern_events.GENERATION_ENDED, onGenEnd);
        if (h) state.eventHandles.push(h);
        log('事件已绑定');
    }

    function unbindEvents() {
        state.eventHandles.forEach(h => h?.stop?.());
        state.eventHandles = [];
    }

    function init() {
        log('初始化');

        // 进入酒馆后延迟刷新当前楼层
        setTimeout(async () => {
            await refreshCurrentFloor();
            log('初始刷新完成');
        }, CONFIG.INIT_DELAY);

        // 绑定生成结束事件
        bindEvents();
        log('完成');
    }

    if (typeof SillyTavern !== 'undefined') {
        init();
    } else {
        const check = setInterval(() => {
            if (typeof SillyTavern !== 'undefined') {
                clearInterval(check);
                init();
            }
        }, 500);
    }

    log('脚本已加载');
})();

